function normalizeVendorFeedSchedule(feed = {}, index = 0) {
  const scheduleType = String(feed.scheduleType || "times").toLowerCase() === "interval" ? "interval" : "times";
  const fileFormat = String(feed.fileFormat || "bson-gzip").toLowerCase();
  const requestedSyncMode = String(feed.syncMode || "split").toLowerCase();
  return {
    id: String(feed.id || crypto.randomUUID()),
    name: sourceTextValue(feed.name || `Vendor feed ${index + 1}`),
    vendorId: sourceTextValue(feed.vendorId || ""),
    vendorName: sourceTextValue(feed.vendorName || ""),
    enabled: feed.enabled === true || String(feed.enabled || "").toLowerCase() === "true",
    transport: "ftp",
    ftpHost: sourceTextValue(feed.ftpHost || ""),
    ftpPort: Math.max(1, Math.min(65535, Number(feed.ftpPort || 21) || 21)),
    ftpUsername: sourceTextValue(feed.ftpUsername || ""),
    ftpPassword: String(feed.ftpPassword || ""),
    ftpRemotePath: sourceTextValue(feed.ftpRemotePath || ""),
    fileFormat: ["bson-gzip", "csv"].includes(fileFormat) ? fileFormat : "bson-gzip",
    importTarget: sourceTextValue(feed.importTarget || "source-catalog") || "source-catalog",
    mappingProfile: sourceTextValue(feed.mappingProfile || "source-catalog-standard") || "source-catalog-standard",
    syncMode: ["full", "split", "catalog", "reconciliation"].includes(requestedSyncMode) ? requestedSyncMode : "split",
    refreshEnabled: feed.refreshEnabled === undefined ? (feed.enabled === true || String(feed.enabled || "").toLowerCase() === "true") : (feed.refreshEnabled === true || String(feed.refreshEnabled || "").toLowerCase() === "true"),
    refreshScheduleType: String(feed.refreshScheduleType || scheduleType).toLowerCase() === "interval" ? "interval" : "times",
    refreshScheduleTimes: [...new Set(String(feed.refreshScheduleTimes || feed.scheduleTimes || "02:00").split(/[,;\s]+/).map((value) => value.trim()).filter((value) => /^([01]\d|2[0-3]):[0-5]\d$/.test(value)))].join(",") || "02:00",
    refreshScheduleEveryHours: Math.max(1, Math.min(24, Number(feed.refreshScheduleEveryHours || feed.scheduleEveryHours || 24) || 24)),
    fullImportEnabled: feed.fullImportEnabled === true || String(feed.fullImportEnabled || "").toLowerCase() === "true",
    fullImportScheduleType: String(feed.fullImportScheduleType || "times").toLowerCase() === "interval" ? "interval" : "times",
    fullImportScheduleTimes: [...new Set(String(feed.fullImportScheduleTimes || "01:00").split(/[,;\s]+/).map((value) => value.trim()).filter((value) => /^([01]\d|2[0-3]):[0-5]\d$/.test(value)))].join(",") || "01:00",
    fullImportScheduleEveryHours: Math.max(1, Math.min(24, Number(feed.fullImportScheduleEveryHours || 24) || 24)),
    notes: sourceTextValue(feed.notes || ""),
    postImportInventoryMode: ["disabled", "dry-run", "apply"].includes(String(feed.postImportInventoryMode || "dry-run").toLowerCase()) ? String(feed.postImportInventoryMode || "dry-run").toLowerCase() : "dry-run",
    postImportPriceMode: ["disabled", "dry-run", "apply"].includes(String(feed.postImportPriceMode || "dry-run").toLowerCase()) ? String(feed.postImportPriceMode || "dry-run").toLowerCase() : "dry-run",
    scheduleType,
    scheduleTimes: [...new Set(String(feed.scheduleTimes || "02:00").split(/[,;\s]+/).map((value) => value.trim()).filter((value) => /^([01]\d|2[0-3]):[0-5]\d$/.test(value)))].join(",") || "02:00",
    scheduleEveryHours: Math.max(1, Math.min(24, Number(feed.scheduleEveryHours || 24) || 24)),
    lastQueuedAt: sourceTextValue(feed.lastQueuedAt || ""),
    lastJobId: sourceTextValue(feed.lastJobId || ""),
    createdAt: sourceTextValue(feed.createdAt || new Date().toISOString()),
    updatedAt: sourceTextValue(feed.updatedAt || new Date().toISOString())
  };
}

function publicVendorFeedSchedule(feed = {}) {
  const normalized = normalizeVendorFeedSchedule(feed);
  return { ...normalized, ftpPassword: "", ftpPasswordConfigured: Boolean(normalized.ftpPassword) };
}

async function queueShopifyVariantPricePushJob(db, body = {}, options = {}) {
  requireEnabledChannel(db, "Shopify");
  const requestedSkus = [...new Set((Array.isArray(body.skus) ? body.skus : []).map((sku) => String(sku || "").trim()).filter(Boolean))];
  const dryRun = body.apply === true ? false : body.dryRun !== false;
  const suppliedFilters = body.filters && typeof body.filters === "object" ? body.filters : {};
  // A broad price review is only meaningful for catalog records that are already live in Shopify.
  // This also prevents scheduled reviews from walking every approved product by default.
  const filters = requestedSkus.length || String(body.query || "").trim() || Object.keys(suppliedFilters).length
    ? suppliedFilters
    : { channelStatus: "shopify-live" };
  const query = String(body.query || "");
  const productTotal = requestedSkus.length || await postgres.countProducts({ q: query, filters }).catch(() => 0);
  const variantTotal = await postgres.countShopifyVariantStatuses({ skus: requestedSkus, liveOnly: requestedSkus.length ? false : shopifyPricePushUsesLiveVariantTotal(filters) }).catch(() => 0);
  const totalRows = variantTotal || productTotal;
  const workerPayload = { skus: requestedSkus, query, filters, templateId: body.templateId || "", dryRun, apply: !dryRun, scheduled: options.scheduled === true, sourceJobId: String(options.sourceJobId || "") };
  const operation = options.operation || (dryRun ? "Shopify price push dry run" : "Shopify price push");
  const duplicate = await findActiveImportJobByWorkerTask(db, "shopify-variant-price-push")
    || await findActiveDuplicateImportJob(db, { section: "Products", operation, direction: "sync", fileName: dryRun ? "shopify-price-push-dry-run.json" : "shopify-price-push-report.json", workerTask: "shopify-variant-price-push", workerPayload });
  if (duplicate) return { duplicate: true, job: duplicate, workerPayload };
  const job = createImportJob(db, { section: "Products", operation, direction: "sync", status: "queued", fileName: dryRun ? "shopify-price-push-dry-run.json" : "shopify-price-push-report.json", totalRows, processedRows: 0, progressPercent: 0, rowLabel: variantTotal ? "variant SKUs" : "products", progressLabel: variantTotal ? "Queued Shopify variant SKU update" : "Queued Shopify product scan", estimatedVariantRows: variantTotal, estimatedProductRows: productTotal, phase: "queued", workerTask: "shopify-variant-price-push", workerPayload, message: `${options.scheduled ? "Scheduled " : ""}${dryRun ? "Shopify price review" : "Shopify price push"} queued from a verified source import for ${Number(totalRows || 0).toLocaleString()} ${variantTotal ? "variant SKU" : "product"}${Number(totalRows || 0) === 1 ? "" : "s"}.` });
  upsertImportJobStore(job);
  if (postgres.isPostgresEnabled()) await postgres.upsertOperationJob(job);
  return { duplicate: false, job, workerPayload };
}

async function queueShopifyShippingEligibilitySyncJob(db, body = {}) {
  requireEnabledChannel(db, "Shopify");
  const requestedSkus = [...new Set((Array.isArray(body.skus) ? body.skus : []).map((sku) => String(sku || "").trim()).filter(Boolean))];
  const dryRun = body.apply === true ? false : body.dryRun !== false;
  const limit = Math.max(1, Math.min(25000, Number(body.limit || 1000) || 1000));
  const workerPayload = { skus: requestedSkus, dryRun, apply: !dryRun, limit };
  const totalRows = requestedSkus.length || await postgres.countProducts({ filters: { channelStatus: "shopify-linked" } }).catch(() => limit);
  const job = createImportJob(db, {
    section: "Products",
    operation: dryRun ? "Shopify shipping eligibility dry run" : "Shopify shipping eligibility sync",
    direction: "sync",
    status: "queued",
    fileName: dryRun ? "shopify-shipping-eligibility-dry-run.json" : "shopify-shipping-eligibility-report.json",
    totalRows: Math.min(totalRows || limit, limit),
    processedRows: 0,
    progressPercent: 0,
    rowLabel: "Shopify products",
    phase: "queued",
    workerTask: "shopify-shipping-eligibility-sync",
    workerPayload,
    message: `${dryRun ? "Shipping eligibility review" : "Shipping eligibility sync"} queued for up to ${Math.min(totalRows || limit, limit).toLocaleString()} Shopify-linked product${Math.min(totalRows || limit, limit) === 1 ? "" : "s"}.`
  });
  upsertImportJobStore(job);
  if (postgres.isPostgresEnabled()) await postgres.upsertOperationJob(job);
  return { job, workerPayload };
}

function resolvedVendorFeedSchedules(settings = {}, vendors = []) {
  const feeds = (Array.isArray(settings.vendorFeedSchedules) ? settings.vendorFeedSchedules : []).map((feed, index) => normalizeVendorFeedSchedule(feed, index));
  return feeds.filter((feed) => feed.id !== "product-datadump");
}

function resolvedDataSourceFeeds(settings = {}) {
  const feeds = (Array.isArray(settings.dataSourceFeeds) ? settings.dataSourceFeeds : []).map((feed, index) => normalizeVendorFeedSchedule(feed, index));
  if (feeds.some((feed) => feed.id === "product-datadump")) return feeds;
  const hasConfiguredDump = Boolean(process.env.PRODUCT_DUMP_FTP_HOST || process.env.PRODUCT_DUMP_FTP_USER || process.env.PRODUCT_DUMP_FTP_REMOTE_PATH);
  if (!hasConfiguredDump) return feeds;
  return [normalizeVendorFeedSchedule({
    id: "product-datadump",
    name: "Product datadump",
    vendorId: "",
    vendorName: "DataWarehouse",
    enabled: false,
    ftpHost: process.env.PRODUCT_DUMP_FTP_HOST || "",
    ftpPort: Number(process.env.PRODUCT_DUMP_FTP_PORT || 21),
    ftpUsername: process.env.PRODUCT_DUMP_FTP_USER || "",
    ftpPassword: process.env.PRODUCT_DUMP_FTP_PASSWORD || "",
    ftpRemotePath: process.env.PRODUCT_DUMP_FTP_REMOTE_PATH || "/dump/datawarehouse/products.bson.gz",
    fileFormat: "bson-gzip",
    importTarget: "source-catalog",
    mappingProfile: "source-catalog-standard",
    syncMode: "split",
    postImportInventoryMode: "dry-run",
    postImportPriceMode: "dry-run",
    scheduleType: "times",
    scheduleTimes: "02:00",
    scheduleEveryHours: 24
  }), ...feeds];
}

const UOM_DEFINITIONS = {
  EA: "Each",
  PL: "Pallet",
  CS: "Case",
  BD: "Bundle",
  RL: "Roll",
  SK: "Skid",
  BX: "Box",
  PK: "Pack",
  KT: "Kit",
  CT: "Carton",
  BL: "Bale",
  RM: "Ream",
  FT: "Foot",
  DR: "Drum",
  PR: "Pair",
  BG: "Bag",
  ST: "Set",
  CL: "Coil",
  CX: "Carton",
  GL: "Gallon",
  LB: "Pound",
  SO: "Spool",
  CA: "Can",
  DS: "Dispenser",
  TU: "Tube",
  YD: "Yard",
  TB: "Tub"
};

function normalizedUomCode(value = "") {
  return String(value || "").trim().toUpperCase();
}

function productUomQty(item = {}) {
  const quantities = [
    item.uomQty,
    item.uom_qty,
    item.minQuantity,
    item.min_quantity,
    item.quantityIncrements,
    item.quantity_increments
  ].map((value) => Number(sourceNumberValue(value))).filter((value) => Number.isFinite(value) && value > 1);
  return quantities.length ? Math.max(...quantities) : 1;
}

function productHasMinimumSellMultiple(item = {}) {
  return [item.minQuantity, item.min_quantity, item.quantityIncrements, item.quantity_increments]
    .some((value) => Number(sourceNumberValue(value)) > 1);
}

function productSupplierTokens(item = {}) {
  return [
    item.supplierCode,
    item.supplier_code,
    item.raw?.supplierCode,
    item.raw?.supplier_code,
    item.supplier,
    item.vendor,
    item.defaultSupplier,
    item.default_supplier,
    item.raw?.supplier,
    item.raw?.vendor,
    item.raw?.defaultSupplier,
    item.raw?.default_supplier
  ].map(sourceTextValue).filter(Boolean);
}

function vendorProfileForProduct(db = null, item = {}) {
  const vendors = Array.isArray(db?.vendors) ? db.vendors : [];
  if (!vendors.length) return null;
  const tokens = productSupplierTokens(item).map((value) => value.toLowerCase()).filter(Boolean);
  if (!tokens.length) return null;
  let lookup = vendorProfileLookupCache.get(db);
  if (!lookup) {
    lookup = new Map();
    for (const vendor of vendors) {
      for (const token of [vendor.id, vendor.vendor_id, vendor.code, vendor.vendorCode, vendor.vendorNumber, vendor.name]) {
        const key = sourceTextValue(token).toLowerCase();
        if (key && !lookup.has(key)) lookup.set(key, vendor);
      }
    }
    vendorProfileLookupCache.set(db, lookup);
  }
  for (const token of tokens) {
    if (lookup.has(token)) return lookup.get(token);
  }
  const tokenSet = new Set(tokens);
  return vendors.find((vendor) => {
    const vendorTokens = [
      vendor.id,
      vendor.vendor_id,
      vendor.code,
      vendor.vendorCode,
      vendor.vendorNumber,
      vendor.name
    ].map(sourceTextValue).map((value) => value.toLowerCase()).filter(Boolean);
    return vendorTokens.some((value) => tokenSet.has(value) || (value && tokens.some((token) => token.includes(value) || value.includes(token))));
  }) || null;
}

function productPricingRules(item = {}, db = null) {
  const vendor = vendorProfileForProduct(db, item);
  const rules = vendor?.pricingRules && typeof vendor.pricingRules === "object" ? vendor.pricingRules : {};
  return {
    costBasis: rules.costBasis || (productSupplierTokens(item).some((value) => {
      const text = value.toLowerCase();
      return text === "uss" || text.includes("essendant");
    }) ? "sell-unit" : "each-unit"),
    enforceMinimumAllowedPrice: rules.enforceMinimumAllowedPrice !== false,
    suspiciousPriceMultiplier: Number(rules.suspiciousPriceMultiplier || 5),
    note: rules.note || ""
  };
}

function productExplicitPricingCostBasis(item = {}, db = null) {
  const vendor = vendorProfileForProduct(db, item);
  const rules = vendor?.pricingRules && typeof vendor.pricingRules === "object" ? vendor.pricingRules : {};
  return String(rules.costBasis || "").trim();
}

function productIsEssendant(item = {}) {
  return productSupplierTokens(item).some((value) => {
    const text = value.toLowerCase();
    return text === "uss" || text.includes("essendant");
  });
}

function productVariationRules(item = {}, db = null) {
  const vendor = vendorProfileForProduct(db, item);
  const rules = vendor?.variationRules && typeof vendor.variationRules === "object" ? vendor.variationRules : {};
  const channelRules = vendor?.channelRules?.shopify && typeof vendor.channelRules.shopify === "object" ? vendor.channelRules.shopify : {};
  const isEssendant = productIsEssendant(item);
  const isTrueValue = productSupplierTokens(item).some((value) => {
    const text = value.toLowerCase();
    return text === "trv" || text.includes("true value");
  });
  return {
    shopifyVariantMode: rules.shopifyVariantMode || channelRules.variantMode || (isEssendant ? "uom-only" : isTrueValue ? "each-and-uom" : "standard"),
    allowShopifyVariations: rules.allowShopifyVariations ?? channelRules.allowVariations ?? (isEssendant ? false : true),
    note: rules.note || channelRules.note || ""
  };
}

function productUsesSellUnitPricing(item = {}, db = null) {
  return productEffectiveCostBasis(item, db) === "sell-unit";
}

function productRequiresUomOnlyVariants(item = {}, db = null) {
  const rules = productVariationRules(item, db);
  return rules.shopifyVariantMode === "uom-only" || rules.allowShopifyVariations === false;
}

function productRequiresEachAndUomVariants(item = {}, db = null) {
  const rules = productVariationRules(item, db);
  return rules.shopifyVariantMode === "each-and-uom" && rules.allowShopifyVariations !== false && productUomQty(item) > 1 && !productHasMinimumSellMultiple(item);
}

function productSourceCostValue(item = {}) {
  const values = [
    item.cost,
    item.sourceCost,
    item.source_cost,
    item.vendorCost,
    item.vendor_cost,
    item.wholesalePrice,
    item.wholesale_price,
    item.fobPrice,
    item.fob_price,
    item.price,
    item.websitePrice
  ].map((value) => Number(sourceNumberValue(value))).filter((value) => Number.isFinite(value) && value > 0);
  return values[0] || 0;
}

function productSourceSellPriceValue(item = {}) {
  const values = [
    item.vendorWebsitePrice,
    item.vendor_website_price,
    item.websitePrice,
    item.shopifyPrice,
    item.price,
    item.productManagerFields?.vendor_website_price,
    item.productManagerFields?.website_price
  ].map((value) => Number(sourceNumberValue(value))).filter((value) => Number.isFinite(value) && value > 0);
  return values[0] || 0;
}

function productCostAppearsToBeSellUnit(item = {}, db = null) {
  const explicitCostBasis = productExplicitPricingCostBasis(item, db);
  if (explicitCostBasis === "sell-unit") return true;
  if (explicitCostBasis === "each-unit") return false;
  if (productIsEssendant(item)) return true;
  if (productRequiresEachAndUomVariants(item, db)) return false;
  const qty = productUomQty(item);
  const sourceCost = productSourceCostValue(item);
  const sourceSellPrice = productSourceSellPriceValue(item);
  if (!(qty > 1) || !(sourceCost > 0) || !(sourceSellPrice > 0)) return false;
  const suspiciousMultiplier = Math.max(2, Number(productPricingRules(item, db).suspiciousPriceMultiplier || 5));
  const expectedEachPrice = pricedFromCost(sourceCost, SHOPIFY_PRICE_MARKUP_PERCENT);
  const expectedPackPrice = pricedFromCost(sourceCost * qty, SHOPIFY_PRICE_MARKUP_PERCENT);
  if (expectedEachPrice > 0 && sourceSellPrice > expectedEachPrice * suspiciousMultiplier) return true;
  if (!(expectedPackPrice > sourceSellPrice * suspiciousMultiplier)) return false;
  return sourceCost <= sourceSellPrice * 1.5 && expectedEachPrice <= sourceSellPrice * 1.75;
}

function productEffectiveCostBasis(item = {}, db = null) {
  return productCostAppearsToBeSellUnit(item, db) ? "sell-unit" : productPricingRules(item, db).costBasis;
}

function productUomInfo(item = {}) {
  const code = normalizedUomCode(item.uom ?? item.unitOfMeasure ?? item.unit_of_measure ?? "");
  const name = UOM_DEFINITIONS[code] || code || "Each";
  const qty = productUomQty(item);
  return {
    code: code || "EA",
    name,
    qty,
    isMultiUnit: qty > 1,
    display: qty > 1 ? (code === "EA" ? `Pack of ${qty}` : `${name} of ${qty}`) : name
  };
}

function productEachUnitCost(item = {}, db = null) {
  const cost = productSourceCostValue(item);
  if (productUsesSellUnitPricing(item, db)) {
    const qty = productUomQty(item);
    return qty > 1 && cost > 0 ? Math.round((cost / qty) * 10000) / 10000 : cost;
  }
  return cost;
}

function productSellUnitCost(item = {}, db = null) {
  if (productUsesSellUnitPricing(item, db)) {
    const cost = productSourceCostValue(item);
    return cost > 0 ? cost : 0;
  }
  const unitCost = productEachUnitCost(item, db);
  if (!(unitCost > 0)) return 0;
  return Math.round(unitCost * productUomQty(item) * 10000) / 10000;
}

function productAvailableQty(item = {}) {
  return Math.max(0, Number(sourceNumberValue(item.qty ?? item.stockQty ?? item.inventoryQty ?? item.shopifyInventoryQty ?? 0)) - Number(sourceNumberValue(item.reserved || 0)));
}

function productIsReplenishable(item = {}) {
  if (item.replenishableUseVendorRules === true || item.raw?.replenishableUseVendorRules === true) return false;
  const value = item.replenishable ?? item.isReplenishable ?? item.raw?.replenishable ?? item.raw?.isReplenishable;
  return value === true || ["true", "yes", "y", "1"].includes(String(value || "").trim().toLowerCase());
}

function productUsesVendorReplenishableRules(item = {}) {
  const value = item.replenishableUseVendorRules ?? item.raw?.replenishableUseVendorRules;
  return value === true || ["true", "yes", "y", "1"].includes(String(value || "").trim().toLowerCase());
}

function productUsesVendorReplenishableQty(item = {}) {
  const value = item.replenishableQtyUseVendorDefault ?? item.raw?.replenishableQtyUseVendorDefault;
  return value === true || ["true", "yes", "y", "1"].includes(String(value || "").trim().toLowerCase());
}

function productReplenishableQty(item = {}, db = null) {
  const vendor = vendorProfileForProduct(db, item);
  const vendorRuleEnabled = vendor?.inventoryRules?.replenishableEnabled === true || vendor?.inventoryRules?.enabled === true;
  const vendorQty = vendorRuleEnabled ? Number(sourceNumberValue(vendor?.inventoryRules?.replenishableQty ?? vendor?.replenishableQty ?? 0)) : 0;
  if (productUsesVendorReplenishableRules(item)) {
    if (!vendorRuleEnabled) return 0;
    return Math.max(1, Math.floor(vendorQty > 0 ? vendorQty : 1));
  }
  if (!productIsReplenishable(item)) return 0;
  if (productUsesVendorReplenishableQty(item)) {
    if (!vendorRuleEnabled) return 0;
    return Math.max(1, Math.floor(vendorQty > 0 ? vendorQty : 1));
  }
  const skuQty = Number(sourceNumberValue(item.replenishableQty ?? item.raw?.replenishableQty ?? 0));
  if (skuQty > 0) return Math.max(1, Math.floor(skuQty));
  return 0;
}

function productSellableQty(item = {}, db = null) {
  const replenishableQty = productReplenishableQty(item, db);
  return replenishableQty > 0 ? replenishableQty : productAvailableQty(item);
}

function syncReplenishableWarehouseStock(db = {}, item = {}) {
  const warehouse = (db.warehouses || []).find((row) => String(row.name || "").trim().toLowerCase() === "staten island")
    || (db.warehouses || []).find((row) => String(row.code || "").trim().toUpperCase() === "WH-SI");
  if (!warehouse) return null;
  const qty = productReplenishableQty(item, db);
  const stockRow = ensureInventoryWarehouseStock(item, warehouse);
  stockRow.warehouseName = warehouse.name;
  stockRow.qty = qty > 0 ? qty : 0;
  stockRow.reserved = 0;
  stockRow.committed = 0;
  stockRow.incoming = 0;
  stockRow.available = stockRow.qty;
  stockRow.updatedAt = new Date().toISOString();
  syncInventoryTotalsFromWarehouses(item);
  return stockRow;
}

function shopifyVariantPriceBasis(item = {}, variant = {}, db = null) {
  const eachCost = productEachUnitCost(item, db);
  const qty = Math.max(1, Number(variant.uomQty || variant.packQty || productUomQty(item) || 1));
  if (productUsesSellUnitPricing(item, db)) {
    const sellQty = productUomQty(item);
    if (qty === sellQty) return productSellUnitCost(item, db);
    if (eachCost > 0) return Math.round(eachCost * qty * 10000) / 10000;
  }
  if (eachCost > 0) return Math.round(eachCost * qty * 10000) / 10000;
  return Number(variant.unitCost || productSellUnitCost(item, db) || 0);
}

function variantBaseSku(item = {}) {
  return String(item.sku || item.vendorSku || item.vendor_sku || item.mfrPartNumber || item.mfr_part_number || "").trim();
}

function variantSkuFromBase(baseSku = "", suffix = "") {
  const sku = String(baseSku || "").trim();
  const cleanSuffix = String(suffix || "").trim().toUpperCase();
  return sku && cleanSuffix && !sku.toUpperCase().endsWith(`-${cleanSuffix}`) ? `${sku}-${cleanSuffix}` : sku;
}

function normalizeSystemVariant(variant = {}, parent = {}, db = null) {
  const uom = productUomInfo({ ...parent, uom: variant.uom || parent.uom, uomQty: variant.uomQty || variant.packQty || parent.uomQty });
  const parentSku = variantBaseSku(parent);
  const sku = String(variant.sku || (uom.isMultiUnit ? variantSkuFromBase(parentSku, `${uom.qty}PC`) : parentSku)).trim();
  const available = productSellableQty(parent, db);
  const key = String(variant.key || (uom.isMultiUnit ? `pack-${uom.qty}` : "each")).trim();
  const fallbackUnitCost = productUsesSellUnitPricing(parent, db) && uom.qty === productUomQty(parent)
    ? productSellUnitCost(parent, db)
    : Math.round((productEachUnitCost(parent, db) * uom.qty) * 10000) / 10000;
  return {
    id: String(variant.id || `${parentSku || "sku"}:${key}`),
    key,
    sku,
    parentSku,
    title: String(variant.title || parent.marketplaceTitle || parent.title || parentSku || "").trim(),
    source: String(variant.source || "data-dump"),
    variantType: String(variant.variantType || "sell-unit"),
    optionName: String(variant.optionName || (uom.isMultiUnit ? "Purchase Unit" : "Title")),
    optionValue: String(variant.optionValue || (uom.isMultiUnit ? uom.display : "Default Title")),
    uom: String(variant.uom || uom.code),
    uomName: String(variant.uomName || uom.name),
    uomQty: Number(variant.uomQty || variant.packQty || uom.qty || 1),
    packQty: Number(variant.packQty || variant.uomQty || uom.qty || 1),
    inventoryMultiplier: Number(variant.inventoryMultiplier || 1),
    quantity: Number(variant.quantity ?? available),
    unitCost: Number(variant.unitCost ?? fallbackUnitCost),
    actual: variant.actual === undefined ? true : Boolean(variant.actual),
    generated: variant.generated === undefined ? true : Boolean(variant.generated),
    status: String(variant.status || "active"),
    note: String(variant.note || (uom.isMultiUnit ? `Actual sell unit from source data: ${uom.display}.` : "Actual sell unit from source data."))
  };
}

function systemProductVariants(item = {}, db = null) {
  if (item.__systemVariantsCache && item.__systemVariantsCache.db === db) return item.__systemVariantsCache.variants;
  let variants;
  if (productRequiresUomOnlyVariants(item, db)) {
    variants = [normalizeSystemVariant({
      sku: variantBaseSku(item),
      note: "Single vendor UOM sell unit from vendor variation rules. No generated UOM SKU suffix."
    }, item, db)];
  } else if (productRequiresEachAndUomVariants(item, db)) {
    variants = [
      normalizeSystemVariant({
        key: "each",
        optionName: "Purchase Unit",
        optionValue: "Each",
        uom: "EA",
        uomQty: 1,
        packQty: 1,
        variantType: "each",
        note: "Individual unit generated from vendor variation rules."
      }, item, db),
      normalizeSystemVariant({
        key: `pack-${productUomQty(item)}`,
        optionName: "Purchase Unit",
        variantType: "sell-unit",
        note: "Vendor UOM sell unit generated from vendor variation rules."
      }, item, db)
    ];
  } else {
    const explicit = Array.isArray(item.systemVariants) ? item.systemVariants : [];
    const generated = normalizeSystemVariant({}, item, db);
    const manual = explicit.filter((variant) => variant.generated === false || String(variant.source || "").toLowerCase() === "manual").map((variant) => normalizeSystemVariant(variant, item, db));
    const seen = new Set();
    variants = [generated, ...manual].filter((variant) => {
      const key = String(variant.sku || "").trim().toLowerCase();
      if (!key || seen.has(key)) return false;
      if (productHasMinimumSellMultiple(item) && Number(variant.uomQty || variant.packQty || 1) <= 1) return false;
      seen.add(key);
      return true;
    });
  }
  Object.defineProperty(item, "__systemVariantsCache", {
    value: { db, variants }, enumerable: false, configurable: true
  });
  return variants;
}

function pricedFromCost(cost, markupPercent = DEFAULT_CHANNEL_SETTINGS.priceMarkupPercent) {
  const numericCost = Number(sourceNumberValue(cost));
  const numericMarkup = Number(markupPercent || 0);
  if (!(numericCost > 0)) return 0;
  return Math.round((numericCost * (1 + numericMarkup / 100)) * 100) / 100;
}

function websitePriceFromRule(item = {}, cost = null, markupPercent = SHOPIFY_PRICE_MARKUP_PERCENT, options = {}, db = null) {
  const vendorWebsitePrice = shopifyUsableVendorWebsitePrice(item, db);
  if (options.allowVendorWebsitePrice !== false && vendorWebsitePrice > 0) return vendorWebsitePrice;
  const basis = cost === null || cost === undefined ? productSellUnitCost(item, db) || sourceCatalogCost(item) : cost;
  const minimumAllowedPrice = Number(sourceNumberValue(item.minimumAllowedPrice ?? item.minimum_allowed_price ?? item.productManagerFields?.minimum_allowed_price ?? 0));
  const fallbackPrice = Number(sourceNumberValue(item.websitePrice ?? item.price ?? 0));
  const computedPrice = pricedFromCost(basis, markupPercent) || fallbackPrice;
  return productPricingRules(item, db).enforceMinimumAllowedPrice && minimumAllowedPrice > 0 ? Math.max(computedPrice, minimumAllowedPrice) : computedPrice;
}

function shopifyUsableVendorWebsitePrice(item = {}, db = null) {
  const vendorWebsitePrice = Number(sourceNumberValue(item.vendorWebsitePrice ?? item.vendor_website_price ?? item.productManagerFields?.vendor_website_price ?? 0));
  if (!(vendorWebsitePrice > 0)) return 0;
  const costFloor = productUsesSellUnitPricing(item, db) ? productSellUnitCost(item, db) : productEachUnitCost(item, db);
  const minimumAllowedPrice = Number(sourceNumberValue(item.minimumAllowedPrice ?? item.minimum_allowed_price ?? item.productManagerFields?.minimum_allowed_price ?? 0));
  const floor = Math.max(costFloor || 0, productPricingRules(item, db).enforceMinimumAllowedPrice ? minimumAllowedPrice || 0 : 0);
  return floor > 0 && vendorWebsitePrice < floor ? 0 : vendorWebsitePrice;
}

function shopifySingleUnitWebsitePrice(item = {}, markupPercent = SHOPIFY_PRICE_MARKUP_PERCENT, db = null) {
  const vendorWebsitePrice = shopifyUsableVendorWebsitePrice(item, db);
  if (vendorWebsitePrice > 0) return vendorWebsitePrice;
  const eachCost = productEachUnitCost(item, db);
  if (eachCost > 0) return pricedFromCost(eachCost, markupPercent);
  return Number(sourceNumberValue(item.websitePrice ?? item.price ?? 0));
}

function shopifyVariantWebsitePrice(item = {}, variant = {}, markupPercent = SHOPIFY_PRICE_MARKUP_PERCENT, db = null) {
  const qty = Math.max(1, Number(variant.uomQty || variant.packQty || productUomQty(item) || 1));
  if (productUsesSellUnitPricing(item, db)) {
    return websitePriceFromRule(item, shopifyVariantPriceBasis(item, variant, db), markupPercent, {
      allowVendorWebsitePrice: true
    }, db);
  }
  if (qty > 1) {
    const singlePrice = shopifySingleUnitWebsitePrice(item, markupPercent, db);
    const discountMultiplier = 1 - (SHOPIFY_MULTIPACK_DISCOUNT_PERCENT / 100);
    if (singlePrice > 0) return Math.round(singlePrice * qty * discountMultiplier * 100) / 100;
  }
  return websitePriceFromRule(item, shopifyVariantPriceBasis(item, variant, db), markupPercent, {
    allowVendorWebsitePrice: qty <= 1
  }, db);
}

