function ensureInventoryWarehouseStock(item, warehouse) {
  item.warehouseStock = Array.isArray(item.warehouseStock) ? item.warehouseStock : [];
  let row = item.warehouseStock.find((entry) => entry.warehouseId === warehouse.id);
  if (!row) {
    row = normalizeWarehouseStockRow({
      warehouseId: warehouse.id,
      warehouseName: warehouse.name,
      qty: 0,
      reserved: 0,
      reorderPoint: 0
    }, warehouse, item);
    item.warehouseStock.push(row);
  }
  return row;
}

function findPreferredOrderWarehouse(db, order) {
  const preferredId = order.fulfillmentWarehouseId || order.reservationWarehouseId || order.returnWarehouseId || "";
  const physicalWarehouses = (db.warehouses || []).filter((warehouse) => warehouse.status !== "inactive" && isPhysicalWarehouse(warehouse));
  return physicalWarehouses.find((warehouse) => warehouse.id === preferredId)
    || physicalWarehouses.find((warehouse) => warehouse.isDefaultReceiving)
    || physicalWarehouses[0]
    || null;
}

function normalizeReceiptAttachment(file = {}, user = "Luis") {
  return {
    id: file.id || crypto.randomUUID(),
    name: String(file.name || "Receiving attachment"),
    size: Number(file.size || 0),
    mimeType: String(file.mimeType || ""),
    source: String(file.source || "Manual upload"),
    dataUrl: String(file.dataUrl || ""),
    uploadedBy: file.uploadedBy || user,
    uploadedAt: file.uploadedAt || new Date().toISOString()
  };
}

function barcodeLookupForms(value) {
  const barcode = String(value || "").replace(/[^0-9A-Za-z]/g, "").trim();
  const forms = new Set([barcode]);
  if (/^\d{11}$/.test(barcode)) forms.add(`0${barcode}`);
  if (/^0\d{11}$/.test(barcode)) forms.add(barcode.slice(1));
  return [...forms].filter(Boolean);
}

async function resolveScannedCatalogBarcode(value) {
  const forms = barcodeLookupForms(value);
  if (!forms.length) return { barcode: "", product: null, sourceItem: null };
  const matches = await postgres.findBarcodeMatches(forms);
  let product = matches.products?.[0] || null;
  const sourceItem = matches.sourceItems?.[0] || null;
  if (!product && sourceItem) {
    for (const key of [sourceItem.sku, sourceItem.id, sourceItem.internalSku, sourceItem.vendorSku].filter(Boolean)) {
      product = await postgres.readProductByKey(key);
      if (product) break;
    }
  }
  if (product) product = await postgres.readProductByKey(product.id || product.sku) || product;
  return { barcode: forms[0], product, sourceItem };
}

function auditWarehouseStockRow(product, audit, locationBin = "") {
  const rows = Array.isArray(product?.warehouseStock) ? product.warehouseStock : [];
  const warehouseId = String(audit?.warehouseId || "").trim().toLowerCase();
  const warehouseName = String(audit?.warehouseName || "").trim().toLowerCase();
  const bin = String(locationBin || "").trim().toLowerCase();
  const warehouseRows = rows.filter((row) => (warehouseId && String(row.warehouseId || "").trim().toLowerCase() === warehouseId)
    || (warehouseName && String(row.warehouseName || "").trim().toLowerCase() === warehouseName));
  if (bin) return warehouseRows.find((row) => String(row.locationBin || "").trim().toLowerCase() === bin) || warehouseRows[0] || null;
  return warehouseRows[0] || null;
}

function auditExpectedQuantity(product, audit, locationBin = "") {
  const warehouseRow = auditWarehouseStockRow(product, audit, locationBin);
  if (warehouseRow) return Number(warehouseRow.qty || 0);
  return Array.isArray(product?.warehouseStock) && product.warehouseStock.length ? 0 : Number(product?.qty || 0);
}

function normalizeReturnAttachment(file = {}, user = "Luis") {
  return {
    id: file.id || crypto.randomUUID(),
    name: String(file.name || "Return attachment"),
    size: Number(file.size || 0),
    mimeType: String(file.mimeType || ""),
    source: String(file.source || "Manual upload"),
    dataUrl: String(file.dataUrl || ""),
    stage: String(file.stage || "requested"),
    uploadedBy: file.uploadedBy || user,
    uploadedAt: file.uploadedAt || new Date().toISOString()
  };
}

function defaultWarehouseBinCode(warehouse) {
  const bins = Array.isArray(warehouse?.bins) ? warehouse.bins : [];
  return bins.find((bin) => bin.isDefault && bin.active !== false)?.code
    || bins.find((bin) => bin.active !== false)?.code
    || "";
}

function applyShadowSkuPatch(shadow, body) {
  const textFields = ["shadowSku", "marketplace", "company", "status", "notes", "inventoryPolicy", "shippingProfile", "shippingService", "shippingTemplateId"];
  for (const field of textFields) {
    if (body[field] !== undefined) shadow[field] = String(body[field]).trim();
  }
  const numberFields = ["price", "handlingTimeDays", "safetyQty", "maxSellableQty"];
  for (const field of numberFields) {
    if (body[field] !== undefined && Number.isFinite(Number(body[field]))) shadow[field] = Number(body[field]);
  }
  if (body.handlingTime !== undefined && Number.isFinite(Number(body.handlingTime))) shadow.handlingTimeDays = Number(body.handlingTime);
  if (body.freeShipping !== undefined) shadow.freeShipping = body.freeShipping === true || String(body.freeShipping).toLowerCase() === "true";
  if (body.attributeKey && body.attributeValue !== undefined) {
    shadow.marketplaceAttributes = shadow.marketplaceAttributes || {};
    shadow.marketplaceAttributes[String(body.attributeKey)] = body.attributeValue;
  }
  if (body.marketplaceAttributes && typeof body.marketplaceAttributes === "object") {
    shadow.marketplaceAttributes = { ...(shadow.marketplaceAttributes || {}), ...body.marketplaceAttributes };
  }
  if (body.contentOverrides && typeof body.contentOverrides === "object") {
    shadow.contentOverrides = {
      ...(shadow.contentOverrides || {}),
      ...body.contentOverrides
    };
    if (body.contentOverrides.imageUrls !== undefined) shadow.contentOverrides.imageUrls = parseList(body.contentOverrides.imageUrls);
  }
  if (body.overrideField) {
    shadow.contentOverrides = shadow.contentOverrides || {};
    shadow.contentOverrides[body.overrideField] = body.overrideField === "imageUrls" ? parseList(body.overrideValue) : String(body.overrideValue || "");
  }
  if (body.marketplace !== undefined || body.company !== undefined) {
    shadow.marketplace = shadow.marketplace || shadow.company || "";
    shadow.company = shadow.marketplace;
  }
  shadow.updatedAt = new Date().toISOString();
  addShadowTimeline(shadow, {
    type: "edited",
    title: "Shadow SKU edited",
    message: `Updated ${Object.keys(body).filter((key) => !["attributeKey", "attributeValue"].includes(key)).join(", ") || body.attributeKey || "shadow fields"}.`
  });
}

function catalogSearchText(product = {}) {
  return [
    product.sku,
    product.title,
    product.marketplaceTitle,
    product.brand,
    product.category,
    product.manufacturer,
    product.mfrPartNumber,
    product.vendorSku,
    product.supplier,
    product.supplierCode,
    product.zoroSku,
    product.altVendorSku,
    product.itemKey,
    product.barcode,
    product.wildcardSearch
  ].filter(Boolean).join(" ").toLowerCase();
}

function catalogFilterParams(searchParams) {
  return {
    supplier: searchParams.get("supplier") || "",
    suppliers: searchParams.get("suppliers") || "",
    active: searchParams.get("active") || "",
    productMembership: searchParams.get("productMembership") || "",
    stockStatus: searchParams.get("stockStatus") || "",
    channelStatus: searchParams.get("channelStatus") || searchParams.get("shopifyStatus") || "",
    hasStock: searchParams.get("hasStock") || "",
    hasImage: searchParams.get("hasImage") || "",
    multipleSuppliers: searchParams.get("multipleSuppliers") || "",
    stockQty: searchParams.get("stockQty") || "",
    stockQtyOperator: searchParams.get("stockQtyOperator") || "",
    hazardous: searchParams.get("hazardous") || "",
    toBeDiscontinued: searchParams.get("toBeDiscontinued") || searchParams.get("discontinued") || "",
    verifiedBrand: searchParams.get("verifiedBrand") || "",
    brand: searchParams.get("brand") || "",
    manufacturer: searchParams.get("manufacturer") || "",
    category: searchParams.get("category") || "",
    inventoryAvailability: searchParams.get("inventoryAvailability") || "",
    lowStock: searchParams.get("lowStock") || "",
    replenishable: searchParams.get("replenishable") || "",
    warehouse: searchParams.get("warehouse") || "",
    vendorScope: searchParams.get("vendorScope") || "",
    includedSuppliers: searchParams.get("includedSuppliers") || "",
    includedSupplierCodes: searchParams.get("includedSupplierCodes") || "",
    excludedSuppliers: searchParams.get("excludedSuppliers") || ""
  };
}

function vendorCatalogSourceCodes(vendor = {}) {
  const configuredCodes = Array.isArray(vendor.catalogSettings?.sourceCodes)
    ? vendor.catalogSettings.sourceCodes
    : String(vendor.catalogSettings?.sourceCodes || "").split(/[|,\n]/);
  return [...new Set(configuredCodes
    .map((value) => sourceTextValue(value).toLowerCase())
    .filter(Boolean))];
}

function applyVendorCatalogScope(filters = {}, vendors = []) {
  const scope = String(filters.vendorScope || "enabled").trim().toLowerCase();
  if (scope === "all") return { ...filters };
  const enabledSourceCodes = [...new Set((vendors || [])
    .filter((vendor) => vendor?.catalogSettings?.enabled === true)
    .flatMap(vendorCatalogSourceCodes))];
  if (!enabledSourceCodes.length) return { ...filters, includedSupplierCodes: "__no_enabled_source__" };
  return {
    ...filters,
    includedSupplierCodes: [...new Set([
      ...catalogFilterValues(filters.includedSupplierCodes),
      ...enabledSourceCodes
    ])].join("|")
  };
}

function catalogSupplierFacetLabels(facets = {}, vendors = []) {
  const aliases = catalogSupplierAliasIndex(vendors);
  const canonical = new Map();
  for (const supplier of facets.suppliers || []) {
    const value = sourceTextValue(supplier);
    if (!value) continue;
    const label = aliases.nameByKey.get(value.toLowerCase()) || canonicalCatalogSupplierName(value);
    if (!canonical.has(label.toLowerCase())) canonical.set(label.toLowerCase(), label);
  }
  return {
    ...facets,
    suppliers: [...canonical.values()].sort((left, right) => left.localeCompare(right))
  };
}

function catalogFilterValues(value = "") {
  return String(value || "").split("|").map((item) => item.trim()).filter(Boolean);
}

function catalogFilterMatches(value = "", actual = "", normalizer = (item) => String(item || "")) {
  const values = catalogFilterValues(value);
  if (!values.length) return true;
  const normalizedActual = normalizer(actual);
  return values.some((item) => normalizer(item) === normalizedActual);
}

function catalogNumberFilterMatches(operator = "", value = "", actualValue = "") {
  if (!operator) return true;
  if (operator === "empty") return String(actualValue ?? "").trim() === "";
  if (operator === "notEmpty") return String(actualValue ?? "").trim() !== "";
  const values = catalogFilterValues(value).map((item) => Number(item)).filter((item) => Number.isFinite(item));
  if (!values.length) return true;
  const actual = Number(actualValue);
  if (!Number.isFinite(actual)) return false;
  if (operator === "gt") return actual > values[0];
  if (operator === "gte") return actual >= values[0];
  if (operator === "lt") return actual < values[0];
  if (operator === "lte") return actual <= values[0];
  if (operator === "between") return actual >= values[0] && actual <= (values[1] ?? values[0]);
  return actual === values[0];
}

function catalogProductHasImage(product = {}) {
  const images = product.images || product.shopifyImages || product.productImages;
  if (Array.isArray(images) && images.length) return true;
  return Boolean(product.image || product.imageUrl || product.defaultImage || product.primaryImage || product.thumbnailUrl);
}

function catalogProductShopifyReadinessStatus(product = {}) {
  const shopifyLinked = Boolean(String(product.shopifyId || product.shopifyProductId || "").trim());
  const shopifyStatus = String(product.shopifyStatus || "").trim().toLowerCase();
  const live = shopifyLinked && shopifyStatus === "active" && product.shopifyPublished === true;
  if (live) return "live";

  const price = Number(product.price ?? product.websitePrice ?? product.shopifyPrice ?? product.listPrice ?? 0);
  const stockQty = Number(product.stockQty ?? product.qty ?? product.inventoryQty ?? product.shopifyInventoryQty ?? 0);
  if (Boolean(product.toBeDiscontinued || product.closeoutEligible) && !(Number.isFinite(stockQty) && stockQty > 0)) return "not-ready";
  const missingRequired = [
    !String(product.sku || product.variantSku || product.shopifyVariantSku || "").trim(),
    !String(product.marketplaceTitle || product.title || product.name || "").trim(),
    !String(product.bodyHtml || product.bodyHTML || product.longDescription || product.description || product.shortDescription || "").trim(),
    !String(product.productType || product.shopifyProductType || product.category || product.shopifyTaxonomyId || product.shopifyCategoryId || "").trim(),
    !String(product.vendor || product.supplier || product.brand || "").trim(),
    !(Number.isFinite(price) && price > 0),
    !(Number.isFinite(stockQty) && stockQty > 0),
    !catalogProductHasImage(product)
  ].some(Boolean);

  return missingRequired ? "not-ready" : "ready";
}

function catalogProductEbayStatus(product = {}) {
  const listing = product.ebayListing || {};
  if (listing.listingId || product.ebayId) return "live";
  if (listing.offerId) return "offer";
  return "missing";
}

function catalogProductEbayReadinessStatus(product = {}) {
  const ebayStatus = catalogProductEbayStatus(product);
  if (ebayStatus === "live") return "live";
  const listing = product.ebayListing || {};
  const price = Number(listing.price ?? product.ebayPrice ?? product.price ?? product.websitePrice ?? product.listPrice ?? 0);
  const quantity = Number(listing.quantity ?? product.available ?? product.stockQty ?? product.qty ?? 0);
  const hasRequiredFields = [
    listing.merchantLocationKey || product.ebayMerchantLocationKey,
    listing.categoryId || product.ebayCategoryId || product.category,
    listing.paymentPolicyId || product.ebayPaymentPolicyId,
    listing.returnPolicyId || product.ebayReturnPolicyId,
    listing.fulfillmentPolicyId || product.ebayFulfillmentPolicyId,
    Number.isFinite(price) && price > 0,
    Number.isFinite(quantity) && quantity > 0,
    catalogProductHasImage(product)
  ].every(Boolean);
  if (ebayStatus === "offer" && hasRequiredFields) return "offer";
  return hasRequiredFields ? "ready" : "not-ready";
}

function catalogMarketplaceRecordValue(value) {
  if (typeof value === "boolean") return value;
  if (typeof value === "number") return Number.isFinite(value) && value !== 0;
  if (typeof value === "string") {
    return !["", "false", "0", "none", "missing", "not found", "not enabled", "disabled", "inactive", "unknown"].includes(value.trim().toLowerCase());
  }
  if (Array.isArray(value)) return value.length > 0;
  if (!value || typeof value !== "object") return false;
  const record = value;
  const identifiers = ["id", "productId", "listingId", "offerId", "variantId", "sku", "merchantSku", "externalId"];
  if (identifiers.some((key) => catalogMarketplaceRecordValue(record[key]))) return true;
  if (record.enabled === true || record.published === true || record.active === true) return true;
  return catalogMarketplaceRecordValue(record.status ?? record.state ?? record.lifecycle);
}

function catalogProductMarketplaceDetected(product = {}, marketplace = "") {
  const channel = String(marketplace || "").trim().toLowerCase();
  const channelStatuses = product.channelStatuses && typeof product.channelStatuses === "object" ? product.channelStatuses : {};
  const sources = product.sources && typeof product.sources === "object" ? product.sources : {};
  const matchesChannelStatus = Object.entries(channelStatuses)
    .filter(([key]) => String(key).toLowerCase().includes(channel))
    .some(([, value]) => catalogMarketplaceRecordValue(value));
  const matchesSource = Object.entries(sources)
    .filter(([key]) => String(key).toLowerCase().includes(channel))
    .some(([, value]) => catalogMarketplaceRecordValue(value));

  if (channel === "shopify") {
    return Boolean(product.shopifyId || product.shopifyProductId || product.shopifyVariantId || product.shopifyVariantSku || product.shopifyHandle || matchesChannelStatus);
  }
  if (channel === "ebay") {
    const listing = product.ebayListing && typeof product.ebayListing === "object" ? product.ebayListing : {};
    return Boolean(product.ebayId || listing.listingId || listing.offerId || matchesChannelStatus || matchesSource);
  }
  if (channel === "temu") {
    return Boolean(product.temuId || product.temuProductId || product.temuListingId || product.temuOfferId || product.temuSku || product.temuListing || matchesChannelStatus || matchesSource);
  }
  return false;
}

function productMatchesCatalogChannelStatus(product = {}, status = "") {
  const value = String(status || "").trim().toLowerCase();
  if (!value) return true;
  const shopifyLinked = catalogProductMarketplaceDetected(product, "shopify");
  const shopifyStatus = String(product.shopifyStatus || "").trim().toLowerCase();
  const shopifySyncSource = String(product.shopifySyncSource || product.syncSource || "").trim().toLowerCase();
  const ebayListing = product.ebayListing || {};
  const ebayStatus = catalogProductEbayStatus(product);
  if (value === "shopify-live" || value === "live") return shopifyLinked && shopifyStatus === "active" && product.shopifyPublished === true;
  if (value === "shopify-not-live") return !(shopifyLinked && shopifyStatus === "active" && product.shopifyPublished === true);
  if (value === "shopify-price-mismatch") return Boolean(product.shopifyPriceMismatch)
    || (Number(product.shopifyLivePrice || 0) > 0 && Math.abs(Number(product.websitePrice ?? product.price ?? 0) - Number(product.shopifyLivePrice || 0)) >= 0.01);
  if (value === "shopify-ready") {
    const readiness = catalogProductShopifyReadinessStatus(product);
    return readiness === "ready" || readiness === "live";
  }
  if (value === "shopify-not-ready") return catalogProductShopifyReadinessStatus(product) === "not-ready";
  if (value === "shopify-linked" || value === "shopify-detected") return shopifyLinked;
  if (value === "shopify-published") return shopifyLinked && product.shopifyPublished === true;
  if (value === "shopify-unpublished") return shopifyLinked && product.shopifyPublished === false;
  if (value === "shopify-missing" || value === "missing") return !shopifyLinked;
  if (value === "shopify-sync-graphql") return shopifySyncSource === "graphql";
  if (value === "shopify-sync-manual") return shopifySyncSource === "manual_upload";
  if (value === "shopify-sync-failed") return shopifySyncSource === "failed";
  if (value.startsWith("shopify:")) return shopifyStatus === value.slice("shopify:".length);
  if (value.startsWith("shopify-")) return shopifyStatus === value.slice("shopify-".length);
  if (value === "ebay-detected") return catalogProductMarketplaceDetected(product, "ebay");
  if (value === "ebay-live") return ebayStatus === "live";
  if (value === "ebay-offer") return ebayStatus === "offer";
  if (value === "ebay-missing") return ebayStatus === "missing";
  if (value === "ebay-ready") return catalogProductEbayReadinessStatus(product) === "ready";
  if (value === "ebay-not-ready") return catalogProductEbayReadinessStatus(product) === "not-ready";
  if (value.startsWith("ebay:")) return String(ebayListing.ebayStatus || ebayListing.status || ebayStatus).toLowerCase() === value.slice("ebay:".length);
  if (value === "temu-detected") return catalogProductMarketplaceDetected(product, "temu");
  if (value === "temu-missing") return !catalogProductMarketplaceDetected(product, "temu");
  return shopifyStatus === value;
}

function productMatchesCatalogFilters(product = {}, filters = {}) {
  const supplierValues = catalogFilterValues(filters.suppliers || filters.supplier).map((value) => value.toLowerCase());
  if (supplierValues.length && !supplierValues.includes(String(product.supplier || product.vendor || "").toLowerCase())) return false;
  if (!catalogFilterMatches(filters.active, String(product.active !== false))) return false;
  if (filters.productMembership === "in-products" && !product.inProducts) return false;
  if (filters.productMembership === "not-in-products" && product.inProducts) return false;
  if (!catalogFilterMatches(filters.stockStatus, product.stockStatus)) return false;
  if (filters.channelStatus && !catalogFilterValues(filters.channelStatus).some((value) => productMatchesCatalogChannelStatus(product, value))) return false;
  if (!catalogFilterMatches(filters.hasStock, String(Number(product.stockQty ?? product.qty ?? 0) > 0))) return false;
  if (!catalogFilterMatches(filters.hasImage, String(catalogProductHasImage(product)))) return false;
  if (!catalogFilterMatches(filters.multipleSuppliers, String(product.hasMultipleSuppliers === true))) return false;
  if (!catalogNumberFilterMatches(filters.stockQtyOperator, filters.stockQty, product.stockQty ?? product.qty)) return false;
  if (!catalogFilterMatches(filters.hazardous, String(Boolean(product.hazardous)))) return false;
  if (!catalogFilterMatches(filters.toBeDiscontinued, String(Boolean(product.toBeDiscontinued || product.closeoutEligible)))) return false;
  if (!catalogFilterMatches(filters.verifiedBrand, String(Boolean(verifiedBrandForHandle(product))))) return false;
  if (!catalogFilterMatches(filters.brand, product.brand || "", formatBrandName)) return false;
  if (!catalogFilterMatches(filters.manufacturer, product.manufacturer || "")) return false;
  if (!catalogFilterMatches(filters.category, product.category || "", formatCategoryName)) return false;
  return true;
}

function hasCatalogFilters(filters = {}) {
  return Object.values(filters).some((value) => value !== "");
}

function normalizeSourceCatalogOverrides(overrides = {}) {
  const entries = Array.isArray(overrides)
    ? overrides.map((row) => [row.sku, row])
    : Object.entries(overrides || {});
  const result = {};
  for (const [sku, row] of entries) {
    const key = String(sku || row?.sku || "").trim().toLowerCase();
    if (!key) continue;
    result[key] = {
      sku: row.sku || sku,
      status: row.status || "",
      active: row.active === undefined ? undefined : Boolean(row.active),
      category: row.category ? formatCategoryName(row.category) : "",
      categoryVerified: row.categoryVerified === undefined ? Boolean(row.category) : Boolean(row.categoryVerified),
      deleted: Boolean(row.deleted),
      updatedAt: row.updatedAt || new Date().toISOString()
    };
  }
  return result;
}

function vendorCategoryMappingKey(supplier, vendorCategory) {
  const supplierKey = String(supplier || "").trim().toLowerCase();
  const categoryKey = formatCategoryName(vendorCategory || "").toLowerCase();
  return supplierKey && categoryKey ? `${supplierKey}::${categoryKey}` : "";
}

function normalizeVendorCategoryMappings(mappings = {}) {
  const entries = Array.isArray(mappings)
    ? mappings.map((row) => [vendorCategoryMappingKey(row?.supplier, row?.vendorCategory), row])
    : Object.entries(mappings || {});
  const result = {};
  for (const [key, row] of entries) {
    const supplier = canonicalCatalogSupplierName(sourceTextValue(row?.supplier), sourceTextValue(row?.supplierCode));
    const vendorCategory = formatCategoryName(row?.vendorCategory || row?.sourceCategory || row?.category);
    const mainCategory = formatCategoryName(row?.mainCategory || row?.mappedCategory || row?.categoryOverride);
    const normalizedKey = vendorCategoryMappingKey(supplier, vendorCategory);
    if (!normalizedKey || !supplier || !vendorCategory || !mainCategory) continue;
    result[normalizedKey] = {
      supplier,
      vendorCategory,
      mainCategory,
      categoryVerified: row.categoryVerified === undefined ? true : Boolean(row.categoryVerified),
      source: row.source || "vendor-category-map",
      sampleSku: row.sampleSku || "",
      matchCount: Number(row.matchCount || 0),
      conflictCount: Number(row.conflictCount || 0),
      updatedAt: row.updatedAt || new Date().toISOString(),
      createdAt: row.createdAt || row.updatedAt || new Date().toISOString()
    };
  }
  return result;
}

function learnVendorCategoryMappingsFromProducts(db = {}, options = {}) {
  const now = new Date().toISOString();
  const mappings = normalizeVendorCategoryMappings(db.vendorCategoryMappings);
  const scopeCategory = formatCategoryName(options.categoryName || "").toLowerCase();
  const candidates = new Map();
  for (const item of Array.isArray(db.inventory) ? db.inventory : []) {
    const mainCategory = formatCategoryName(item.mainCategory || (item.categoryVerified ? item.category : ""));
    if (!mainCategory || item.categoryVerified === false) continue;
    if (scopeCategory && mainCategory.toLowerCase() !== scopeCategory) continue;
    const supplier = sourceTextValue(item.supplier || item.vendor || item.defaultSupplier);
    const vendorCategory = formatCategoryName(item.sourceCategory || item.vendorCategory || "");
    const key = vendorCategoryMappingKey(supplier, vendorCategory);
    if (!key) continue;
    if (!candidates.has(key)) {
      candidates.set(key, {
        supplier,
        vendorCategory,
        sampleSku: item.sku || "",
        products: 0,
        categories: new Map()
      });
    }
    const candidate = candidates.get(key);
    candidate.products += 1;
    candidate.categories.set(mainCategory, (candidate.categories.get(mainCategory) || 0) + 1);
    if (!candidate.sampleSku && item.sku) candidate.sampleSku = item.sku;
  }
  let created = 0;
  let refreshed = 0;
  let conflicts = 0;
  const samples = [];
  for (const [key, candidate] of candidates.entries()) {
    const rankedCategories = [...candidate.categories.entries()].sort((a, b) => b[1] - a[1] || a[0].localeCompare(b[0]));
    const [mainCategory, matchCount] = rankedCategories[0] || ["", 0];
    const categoryConflictCount = Math.max(0, rankedCategories.length - 1);
    const existing = mappings[key];
    if (existing && formatCategoryName(existing.mainCategory).toLowerCase() !== mainCategory.toLowerCase()) {
      conflicts += 1;
      mappings[key] = {
        ...existing,
        conflictCount: Math.max(Number(existing.conflictCount || 0), candidate.products),
        updatedAt: now
      };
      if (samples.length < 10) samples.push({ supplier: candidate.supplier, vendorCategory: candidate.vendorCategory, mainCategory, existingMainCategory: existing.mainCategory, status: "conflict" });
      continue;
    }
    mappings[key] = {
      ...(existing || {}),
      supplier: candidate.supplier,
      vendorCategory: candidate.vendorCategory,
      mainCategory,
      categoryVerified: true,
      source: existing?.source || "verified-product-catalog",
      sampleSku: existing?.sampleSku || candidate.sampleSku,
      matchCount,
      conflictCount: Math.max(Number(existing?.conflictCount || 0), categoryConflictCount),
      updatedAt: now,
      createdAt: existing?.createdAt || now
    };
    if (existing) refreshed += 1;
    else created += 1;
    if (samples.length < 10) samples.push({ supplier: candidate.supplier, vendorCategory: candidate.vendorCategory, mainCategory, matchCount, status: existing ? "refreshed" : "created" });
  }
  db.vendorCategoryMappings = mappings;
  return {
    scannedProducts: Array.isArray(db.inventory) ? db.inventory.length : 0,
    candidateMappings: candidates.size,
    created,
    refreshed,
    conflicts,
    samples
  };
}

function sourceCatalogOverrideMap(db = {}) {
  db.sourceCatalogOverrides = normalizeSourceCatalogOverrides(db.sourceCatalogOverrides);
  return db.sourceCatalogOverrides;
}

function vendorCategoryMappingMap(db = {}) {
  db.vendorCategoryMappings = normalizeVendorCategoryMappings(db.vendorCategoryMappings);
  return db.vendorCategoryMappings;
}

async function readSourceCatalogRuntimeDb() {
  if (!postgres.isPostgresEnabled()) return readDbFast();
  const runtimeState = await postgres.readStateFields([
    "sourceCatalogOverrides",
    "vendorCategoryMappings"
  ], { fallbackToLegacy: false }).catch(() => ({}));
  return {
    inventory: [],
    sourceCatalogOverrides: runtimeState.sourceCatalogOverrides || {},
    vendorCategoryMappings: runtimeState.vendorCategoryMappings || {}
  };
}

function auditLineKey(line = {}) {
  return String(line.id || `${line.productId || line.sku || ""}::${line.locationBin || ""}`);
}

function selectableAuditSupplierMatch(row = {}) {
  return !["rejected"].includes(String(row.matchStatus || "").trim().toLowerCase());
}

async function auditSupplierOptionsForLine(line = {}) {
  const product = await postgres.readProductByKey(line.productId || line.sku);
  if (!product) return { product: null, options: [], pendingReviewCount: 0 };
  const cacheVersion = String(product.supplierCoverageUpdatedAt || "unindexed").trim();
  const cacheIdentity = encodeURIComponent(`${String(product.id || product.sku || line.productId || line.sku || "").trim().toLowerCase()}:${cacheVersion}`);
  const cacheKey = cacheIdentity ? `dataplus:audit-supplier-options:v2:${cacheIdentity}` : "";
  if (cacheKey) {
    const cached = await redisCache.getJson(cacheKey);
    if (cached && Array.isArray(cached.options)) {
      return {
        product,
        options: cached.options,
        pendingReviewCount: Number(cached.pendingReviewCount || 0),
        cached: true
      };
    }
  }
  const coverage = await postgres.readProductSupplierLinks({
    productId: product.id,
    sku: product.sku
  });
  const matches = [...(coverage.matches || [])];
  const primarySupplier = String(product.supplier || product.vendor || "").trim();
  const primaryVendorSku = String(product.vendorSku || product.sku || "").trim();
  if (primarySupplier && !matches.some((row) => selectableAuditSupplierMatch(row)
    && String(row.supplier || "").trim().toLowerCase() === primarySupplier.toLowerCase())) {
    matches.unshift({
      supplier: primarySupplier,
      supplierCode: product.supplierCode || "",
      vendorSku: primaryVendorSku,
      sourceSku: product.sourceSku || primaryVendorSku,
      cost: product.cost,
      qty: product.qty ?? product.stockQty,
      matchType: "primary",
      matchStatus: "confirmed",
      requiresReview: false
    });
  }
  const bySupplier = new Map();
  for (const match of matches.filter(selectableAuditSupplierMatch)) {
    const supplierName = String(match.supplier || "").trim();
    const supplierCode = String(match.supplierCode || "").trim();
    if (!supplierName && !supplierCode) continue;
    const key = String(match.vendorId || supplierCode || supplierName).trim().toLowerCase();
    const option = {
      key,
      vendorId: String(match.vendorId || "").trim(),
      supplierName: String(supplierName || supplierCode).trim(),
      supplierCode,
      sourceSku: String(match.sourceSku || match.sku || "").trim(),
      vendorSku: String(match.vendorSku || match.sourceSku || match.sku || "").trim(),
      manufacturerSku: String(match.mfrPartNumber || product.mfrPartNumber || product.manufacturerPartNumber || product.mpn || "").trim(),
      barcode: String(match.barcode || match.upc || match.gtin || product.barcode || product.upc || product.gtin || "").trim(),
      cost: Number(match.cost || 0),
      qty: Number(match.qty || 0),
      matchType: String(match.matchType || coverage.matchType || "").trim(),
      matchStatus: String(match.matchStatus || "confirmed").trim().toLowerCase(),
      requiresReview: Boolean(match.requiresReview || String(match.matchStatus || "").trim().toLowerCase() === "pending"),
      reviewId: String(match.reviewId || "").trim(),
      confidence: match.confidence == null ? null : Number(match.confidence)
    };
    const current = bySupplier.get(key);
    const optionConfirmed = !option.requiresReview;
    const currentConfirmed = current && !current.requiresReview;
    if (!current
      || (optionConfirmed && !currentConfirmed)
      || (optionConfirmed === currentConfirmed && option.cost > 0 && (Number(current.cost || 0) <= 0 || option.cost < Number(current.cost || 0)))) {
      bySupplier.set(key, option);
    }
  }
  const result = {
    product,
    options: [...bySupplier.values()].sort((a, b) => a.supplierName.localeCompare(b.supplierName)),
    pendingReviewCount: Number(coverage.pendingReviewCount || 0),
    cached: false
  };
  if (cacheKey) {
    await redisCache.setJson(cacheKey, {
      options: result.options,
      pendingReviewCount: result.pendingReviewCount
    }, result.options.length ? 3600 : 300);
  }
  return result;
}

function normalizeAuditDemandSku(value) {
  return String(value || "").trim().toLowerCase()
    .replace(/[-_](?:[0-9]+(?:pc|pk|pack|ct|cs|case|bx|ea)|ea|each)$/i, "");
}

function auditOrderLineRemaining(match = {}) {
  const line = match.lineRaw || {};
  const requested = Math.max(0, Number(match.qty || line.quantity || line.qty || 0));
  const explicitRemaining = Number(line.remainingQty ?? line.remainingQuantity ?? line.unfulfilledQuantity);
  const fulfilled = Math.max(0, Number(line.fulfilledQty ?? line.fulfilledQuantity ?? 0));
  const order = match.orderRaw || {};
  const lineIndex = Number(match.lineIndex ?? 0);
  const warehouseCommitted = (order.fulfillmentRoutes || []).reduce((sum, route) => {
    if (Number(route.lineIndex) !== lineIndex || String(route.type || "").toLowerCase() !== "warehouse") return sum;
    const status = String(route.status || "").toLowerCase();
    if (["canceled", "cancelled", "closed", "expired", "void"].includes(status)) return sum;
    return sum + Math.max(0, Number(route.qty || 0));
  }, 0);
  const openCustomerDemand = Number.isFinite(explicitRemaining) ? explicitRemaining : requested - fulfilled;
  return Math.max(0, openCustomerDemand - warehouseCommitted);
}

function auditOrderMatchIsOpen(match = {}) {
  const order = match.orderRaw || {};
  const line = match.lineRaw || {};
  const values = [match.status, order.status, order.operationalStatus, order.workflowStatus, order.fulfillmentStatus, line.fulfillmentStatus]
    .map((value) => String(value || "").trim().toLowerCase());
  const terminal = new Set(["archived", "canceled", "cancelled", "closed", "complete", "completed", "delivered", "deleted", "done", "fulfilled", "refunded", "returned", "shipped", "void"]);
  if (match.shippedAt || order.cancelledAt || order.canceledAt || values.some((value) => terminal.has(value))) return false;
  const financial = String(order.financialStatus || order.paymentStatus || "").trim().toLowerCase();
  if (["refunded", "voided", "pending", "unpaid"].includes(financial)) return false;
  return auditOrderLineRemaining(match) > 0;
}

async function buildWarehouseAuditActionPreview(audit = {}) {
  const families = [];
  for (const line of audit.lines || []) {
    const countedQty = Math.max(0, Number(line.countedQty || 0));
    if (!countedQty || String(line.reviewStatus || "").toLowerCase() === "excluded") continue;
    const supplierResult = await auditSupplierOptionsForLine(line);
    const candidates = [...new Set([
      line.sku,
      line.productId,
      line.selectedSupplierSku,
      line.selectedVendorSku,
      line.selectedManufacturerSku,
      line.selectedSupplierUpc,
      line.vendorSku,
      line.manufacturerSku,
      line.mfrPartNumber,
      line.manufacturerPartNumber,
      line.mpn,
      line.upc,
      line.barcode,
      ...supplierResult.options.flatMap((option) => [
        option.sourceSku,
        option.vendorSku,
        option.manufacturerSku,
        option.manufacturerPartNumber,
        option.mfrPartNumber,
        option.mpn,
        option.barcode,
        option.upc
      ])
    ].map(normalizeAuditDemandSku).filter(Boolean))];
    families.push({
      lineKey: auditLineKey(line),
      sku: String(line.selectedSupplierSku || line.sku || "").trim(),
      catalogSku: String(line.sku || "").trim(),
      title: String(line.title || supplierResult.product?.title || "").trim(),
      countedQty,
      supplierCount: new Set(supplierResult.options.map((option) => String(option.vendorId || option.supplierCode || option.supplierName || "").trim().toLowerCase()).filter(Boolean)).size,
      selectedSupplierName: String(line.selectedSupplierName || "").trim(),
      candidates,
      candidateSet: new Set(candidates)
    });
  }
  const lookupSkus = [...new Set(families.flatMap((family) => family.candidates))];
  const matches = lookupSkus.length ? await postgres.readOrderLinesBySkus(lookupSkus) : [];
  const demand = [];
  const seen = new Set();
  for (const match of matches || []) {
    if (!auditOrderMatchIsOpen(match)) continue;
    const rowCandidates = [match.sku, match.mappedSku, match.originalSku, match.lineRaw?.parentSku, match.lineRaw?.baseSku, match.lineRaw?.catalogSku]
      .map(normalizeAuditDemandSku).filter(Boolean);
    const family = families.find((entry) => rowCandidates.some((candidate) => entry.candidateSet.has(candidate)));
    if (!family) continue;
    const identity = `${match.orderId}:${match.lineId || match.lineIndex}:${family.lineKey}`;
    if (seen.has(identity)) continue;
    seen.add(identity);
    const remainingQty = auditOrderLineRemaining(match);
    const order = match.orderRaw || {};
    demand.push({
      id: identity,
      lineKey: family.lineKey,
      auditSku: family.sku,
      catalogSku: family.catalogSku,
      orderId: match.orderId,
      lineIndex: Number(match.lineIndex ?? 0),
      orderNumber: String(match.internalOrderNumber || match.orderNumber || match.marketplaceOrderId || match.orderId || "").trim(),
      customer: String(order.customerName || order.customer?.displayName || order.customer?.name || order.shippingAddress?.name || "Customer").trim(),
      orderSku: String(match.sku || match.mappedSku || match.originalSku || "").trim(),
      title: String(match.lineRaw?.title || match.lineRaw?.name || family.title || "").trim(),
      remainingQty,
      matchedBy: rowCandidates.some((candidate) => candidate === normalizeAuditDemandSku(family.catalogSku)) ? "catalog_sku" : "supplier_family"
    });
  }
  const byLine = families.map((family) => {
    const orders = demand.filter((row) => row.lineKey === family.lineKey);
    const openDemandQty = orders.reduce((sum, row) => sum + Number(row.remainingQty || 0), 0);
    return {
      lineKey: family.lineKey,
      sku: family.sku,
      catalogSku: family.catalogSku,
      title: family.title,
      countedQty: family.countedQty,
      supplierCount: family.supplierCount,
      selectedSupplierName: family.selectedSupplierName,
      openDemandQty,
      usableQty: Math.min(family.countedQty, openDemandQty),
      orders
    };
  });
  return {
    lines: byLine,
    orders: demand,
    orderIds: [...new Set(demand.map((row) => row.orderId).filter(Boolean))],
    totalCountedQty: byLine.reduce((sum, row) => sum + row.countedQty, 0),
    totalOpenDemandQty: byLine.reduce((sum, row) => sum + row.openDemandQty, 0),
    totalUsableQty: byLine.reduce((sum, row) => sum + row.usableQty, 0),
    affectedOrderCount: new Set(demand.map((row) => row.orderId)).size,
    multipleSupplierLineCount: byLine.filter((row) => row.supplierCount > 1).length
  };
}

function applySourceCatalogOverride(product = {}, overrides = {}, vendorMappings = {}) {
  const override = overrides[String(product.sku || "").toLowerCase()];
  const supplier = sourceTextValue(product.supplier || product.vendor);
  const vendorCategory = formatCategoryName(product.sourceCategory || product.vendorCategory || product.category || "");
  const vendorMapping = vendorMappings[vendorCategoryMappingKey(supplier, vendorCategory)];
  if (!override && !vendorMapping) return product;
  const mappedCategory = override?.category || vendorMapping?.mainCategory || product.mainCategory || "";
  return {
    ...product,
    sourceCategory: product.sourceCategory || product.vendorCategory || product.category || "",
    vendorCategory: product.vendorCategory || product.sourceCategory || product.category || "",
    mainCategory: mappedCategory,
    categoryVerified: mappedCategory ? true : Boolean(product.categoryVerified),
    status: override?.status || product.status,
    active: override?.active === undefined ? product.active : override.active,
    sourceCatalogDeleted: Boolean(override?.deleted),
    sourceCatalogOverrideUpdatedAt: override?.updatedAt || "",
    vendorCategoryMappingUpdatedAt: vendorMapping?.updatedAt || "",
    vendorCategoryMappedFrom: vendorMapping ? "vendor-category-map" : ""
  };
}

function inventoryBySkuMap(db = {}) {
  const rows = Array.isArray(db.inventory) ? db.inventory : [];
  return new Map(rows.map((item) => [String(item.sku || "").toLowerCase(), item]).filter(([sku]) => sku));
}

function sourceProductDiffs(source = {}, product = {}) {
  if (!product) return [];
  const checks = [
    ["title", source.marketplaceTitle || source.title, product.marketplaceTitle || product.title],
    ["brand", source.brand, product.brand],
    ["cost", Number(source.cost || 0), Number(product.cost || 0)],
    ["price", Number(source.price || 0), Number(product.price || 0)],
    ["qty", Number(source.stockQty ?? source.qty ?? 0), Number(product.stockQty ?? product.qty ?? 0)],
    ["status", source.status || (source.active === false ? "Inactive" : "Active"), product.status || (product.active === false ? "Inactive" : "Active")]
  ];
  return checks
    .filter(([, left, right]) => String(left ?? "").trim() !== String(right ?? "").trim())
    .map(([field]) => field);
}

function sourceCatalogLookupKeys(product = {}) {
  return [...new Set([
    product.id,
    product.sku,
    product.internalSku,
    product.vendorSku,
    product.mfrPartNumber,
    product.externalId,
    product.shopifyVariantSku,
    product.barcode
  ]
    .map((value) => String(value || "").trim().toLowerCase())
    .filter(Boolean))];
}

function managedProductLookup(products = []) {
  const lookup = new Map();
  for (const product of Array.isArray(products) ? products : []) {
    for (const key of sourceCatalogLookupKeys(product)) {
      if (!lookup.has(key)) lookup.set(key, product);
    }
    for (const alias of Array.isArray(product.aliases) ? product.aliases : []) {
      const key = String(alias?.aliasSku || alias?.sku || alias?.value || "").trim().toLowerCase();
      if (key && !lookup.has(key)) lookup.set(key, product);
    }
  }
  return lookup;
}

function managedProductForSource(row = {}, productsBySku = new Map()) {
  for (const key of sourceCatalogLookupKeys(row)) {
    const product = productsBySku.get(key);
    if (product) return product;
  }
  return null;
}

function catalogManagedFields(product = {}) {
  if (!product) return {};
  const fields = [
    "shopifyId", "shopifyProductId", "shopifyVariantId", "shopifyVariantSku", "shopifyHandle",
    "shopifyStatus", "shopifyPublished", "shopifyPublishedAt", "shopifyUpdatedAt", "shopifySyncedAt",
    "shopifyLivePrice", "shopifyLiveInventoryQuantity", "shopifyOnlineStoreUrl", "shopifySyncSource",
    "shopifyVariantCount", "ebayId", "ebayListing", "channelStatuses", "sources",
    "shippingClass", "shippingMethod", "shippingClassReason", "createdAt", "createdBy",
    "createdMethod", "createdSource", "createdSourceDetail", "updatedAt", "imageCount"
  ];
  return Object.fromEntries(fields
    .filter((field) => product[field] !== undefined)
    .map((field) => [field, product[field]]));
}

function decorateSourceCatalogProduct(product = {}, overrides = {}, productsBySku = new Map(), vendorMappings = {}) {
  const row = applySourceCatalogOverride(product, overrides, vendorMappings);
  const activeProduct = managedProductForSource(row, productsBySku);
  const sourceImages = Array.isArray(row.images) ? row.images.filter(Boolean) : [];
  const managedImages = Array.isArray(activeProduct?.images) ? activeProduct.images.filter(Boolean) : [];
  return {
    ...row,
    ...catalogManagedFields(activeProduct),
    defaultImage: row.defaultImage || activeProduct?.defaultImage || "",
    images: sourceImages.length ? sourceImages : managedImages,
    inProducts: Boolean(activeProduct),
    productCatalogId: activeProduct?.id || "",
    productCatalogSku: activeProduct?.sku || "",
    productCatalogStatus: activeProduct?.status || "",
    productCatalogActive: activeProduct ? activeProduct.active !== false : false,
    productCatalogDiffs: activeProduct ? sourceProductDiffs(row, activeProduct) : []
  };
}

function isExactCatalogIdentifier(value = "") {
  return /^[a-z0-9_-]{5,}$/i.test(String(value || "").trim());
}

async function readExactSourceCatalogMatches(value = "") {
  const identifier = String(value || "").trim();
  if (!postgres.isPostgresEnabled() || !isExactCatalogIdentifier(identifier)) return [];
  const rows = await postgres.readVendorCatalogItemsBySkus([identifier]);
  const normalizedItems = (rows || [])
    .map((item) => normalizeCatalogProductForInventory(item))
    .filter(Boolean);
  if (!normalizedItems.length) return [];
  const runtimeDb = await readSourceCatalogRuntimeDb();
  const managedProducts = await postgres.readProductsByKeys(
    normalizedItems.flatMap((item) => sourceCatalogLookupKeys(item))
  );
  const productsBySku = managedProductLookup(managedProducts);
  const overrides = sourceCatalogOverrideMap(runtimeDb);
  const vendorMappings = vendorCategoryMappingMap(runtimeDb);
  return normalizedItems
    .map((item) => decorateSourceCatalogProduct(item, overrides, productsBySku, vendorMappings))
    .filter((item) => !item.sourceCatalogDeleted);
}

function sourceCatalogCost(product = {}) {
  const sourceCost = Number(sourceNumberValue(product.sourceCost));
  if (sourceCost > 0) return sourceCost;
  const cost = Number(sourceNumberValue(product.cost));
  const price = Number(sourceNumberValue(product.price));
  const listPrice = Number(sourceNumberValue(product.listPrice ?? product.msrp));
  const appearsToBeRawDumpPrice = price > 0 && listPrice > 0 && price <= listPrice && (!cost || cost >= price);
  if (appearsToBeRawDumpPrice) return price;
  return cost || price || 0;
}

function catalogSummary(product = {}) {
  const cost = sourceCatalogCost(product);
  const listPrice = isClearanceItem(product) ? Number(sourceNumberValue(product.listPrice ?? product.msrp ?? 0)) : 0;
  const websitePrice = websitePriceFromRule(product, cost, SHOPIFY_PRICE_MARKUP_PERCENT);
  return {
    id: product.id || product.sku,
    sku: product.sku || "",
    title: product.title || product.marketplaceTitle || "",
    marketplaceTitle: product.marketplaceTitle || product.title || "",
    brand: formatBrandName(product.brand || ""),
    sourceBrand: product.sourceBrand || "",
    brandLocked: Boolean(product.brandLocked),
    category: formatCategoryName(product.mainCategory || (product.categoryVerified ? product.category : "")),
    mainCategory: formatCategoryName(product.mainCategory || (product.categoryVerified ? product.category : "")),
    categoryVerified: Boolean(product.categoryVerified),
    sourceCategory: formatCategoryName(product.sourceCategory || product.vendorCategory || product.category || ""),
    vendorCategory: formatCategoryName(product.vendorCategory || product.sourceCategory || product.category || ""),
    manufacturer: product.manufacturer || "",
    mfrPartNumber: product.mfrPartNumber || "",
    vendorSku: product.vendorSku || "",
    supplier: canonicalCatalogSupplierName(product.supplier || product.vendor, product.supplierCode),
    supplierCode: product.supplierCode || "",
    stockStatus: product.stockStatus || "",
    hazardous: Boolean(product.hazardous),
    toBeDiscontinued: Boolean(product.toBeDiscontinued || product.closeoutEligible),
    closeoutEligible: Boolean(product.toBeDiscontinued || product.closeoutEligible),
    tags: productExportTags(product),
    price: websitePrice,
    websitePrice,
    cost,
    sourceCost: cost,
    listPrice,
    msrp: listPrice,
    stockQty: Number(product.stockQty ?? product.qty ?? 0),
    active: product.active !== false,
    status: product.status || "Draft",
    inProducts: Boolean(product.inProducts),
    productCatalogId: product.productCatalogId || "",
    productCatalogSku: product.productCatalogSku || "",
    productCatalogStatus: product.productCatalogStatus || "",
    productCatalogActive: Boolean(product.productCatalogActive),
    productCatalogDiffs: Array.isArray(product.productCatalogDiffs) ? product.productCatalogDiffs : [],
    shopifyId: product.shopifyId || "",
    shopifyProductId: product.shopifyProductId || "",
    shopifyVariantId: product.shopifyVariantId || "",
    shopifyVariantSku: product.shopifyVariantSku || "",
    shopifyHandle: product.shopifyHandle || "",
    shopifyStatus: product.shopifyStatus || "",
    shopifyPublished: Boolean(product.shopifyPublished),
    shopifyPublishedAt: product.shopifyPublishedAt || "",
    shopifyUpdatedAt: product.shopifyUpdatedAt || "",
    shopifySyncedAt: product.shopifySyncedAt || "",
    shopifyLivePrice: product.shopifyLivePrice ?? null,
    shopifyLiveInventoryQuantity: product.shopifyLiveInventoryQuantity ?? null,
    shopifyOnlineStoreUrl: product.shopifyOnlineStoreUrl || "",
    shopifySyncSource: product.shopifySyncSource || "",
    shopifyVariantCount: Number(product.shopifyVariantCount || 0),
    ebayId: product.ebayId || "",
    ebayListing: product.ebayListing || {},
    channelStatuses: product.channelStatuses || {},
    createdAt: product.createdAt || product.lastSeenAt || "",
    createdBy: product.createdBy || "",
    createdMethod: product.createdMethod || "",
    createdSource: product.createdSource || "source catalog / data dump",
    createdSourceDetail: product.createdSourceDetail || "",
    updatedAt: product.updatedAt || "",
    shippingClass: product.shippingClass || "",
    shippingMethod: product.shippingMethod || "",
    shippingClassReason: product.shippingClassReason || "",
    alternateVendorCount: Number(product.alternateVendorCount || 0),
    defaultImage: product.defaultImage || "",
    images: Array.isArray(product.images) ? product.images.slice(0, 4) : [],
    zoroSku: product.zoroSku || "",
    zoroPrice: Number(product.zoroPrice || 0),
    varisContractPrice: Number(product.varisContractPrice || 0),
    countryOfOrigin: product.countryOfOrigin || "",
    lastPricesUpdateAt: product.lastPricesUpdateAt || product.productDumpUpdatedAt || "",
    lastPricesUpdateBy: product.lastPricesUpdateBy || "",
    productManagerFieldCount: product.productManagerFields ? Object.keys(product.productManagerFields).length : 0
  };
}

function readCatalogManifest() {
  if (!fs.existsSync(CATALOG_MANIFEST_FILE)) return null;
  try {
    return JSON.parse(fs.readFileSync(CATALOG_MANIFEST_FILE, "utf8"));
  } catch {
    return null;
  }
}

function readCatalogVendorIndex() {
  if (!fs.existsSync(CATALOG_VENDOR_INDEX_FILE)) return null;
  try {
    return JSON.parse(fs.readFileSync(CATALOG_VENDOR_INDEX_FILE, "utf8"));
  } catch {
    return null;
  }
}

function catalogFiltersWithIndexedSupplierKeys(filters = {}) {
  const selectedSuppliers = String(filters.suppliers || filters.supplier || "")
    .split("|")
    .map((value) => value.trim())
    .filter(Boolean);
  if (!selectedSuppliers.length) return filters;
  const supplierNames = new Set(selectedSuppliers.map((supplier) => supplier.toLowerCase()));
  const keys = new Set(selectedSuppliers);
  const vendorIndex = readCatalogVendorIndex();
  const aliases = catalogSupplierAliasIndex(vendorIndex?.vendors || vendorIndex?.suppliers || []);
  for (const selectedSupplier of selectedSuppliers) {
    const displayName = aliases.nameByKey.get(selectedSupplier.toLowerCase())
      || canonicalCatalogSupplierName(selectedSupplier);
    if (displayName) {
      keys.add(displayName);
      for (const code of aliases.codesByName.get(displayName) || []) {
        keys.add(code);
        keys.add(code.toLowerCase());
        keys.add(code.toUpperCase());
      }
    }
  }
  for (const row of vendorIndex?.vendors || vendorIndex?.suppliers || []) {
    const name = typeof row === "string" ? row : row?.name;
    if (!name || !supplierNames.has(String(name).toLowerCase()) && !supplierNames.has(canonicalCatalogSupplierName(name).toLowerCase())) continue;
    keys.add(String(name));
    for (const code of row?.supplierCodes || row?.codes || []) {
      if (!code) continue;
      keys.add(String(code));
      keys.add(String(code).toLowerCase());
      keys.add(String(code).toUpperCase());
    }
  }
  return { ...filters, supplierKeys: [...keys] };
}

function readSourceCatalogIndexManifest() {
  if (!fs.existsSync(CATALOG_INDEX_MANIFEST_FILE) || !fs.existsSync(CATALOG_INDEX_SUPPLIERS_FILE)) return null;
  try {
    const manifest = JSON.parse(fs.readFileSync(CATALOG_INDEX_MANIFEST_FILE, "utf8"));
    const catalogStat = fs.existsSync(CATALOG_FILE) ? fs.statSync(CATALOG_FILE) : null;
    if (!catalogStat || Number(manifest.catalogSize || 0) !== catalogStat.size || Number(manifest.catalogMtimeMs || 0) !== catalogStat.mtimeMs) return null;
    const suppliers = JSON.parse(fs.readFileSync(CATALOG_INDEX_SUPPLIERS_FILE, "utf8"));
    return { ...manifest, suppliers: suppliers.suppliers || [] };
  } catch {
    return null;
  }
}

function skuShardName(sku) {
  const key = String(sku || "").toLowerCase().replace(/[^a-z0-9]/g, "");
  return (key.slice(0, 2) || "__").padEnd(2, "_");
}

async function readCatalogProductFromSkuIndex(sku) {
  const key = String(sku || "").trim().toLowerCase();
  const index = readSourceCatalogIndexManifest();
  if (!key || !index) return null;
  const shardPath = path.join(CATALOG_INDEX_SKU_DIR, `${skuShardName(key)}.ndjson`);
  if (!fs.existsSync(shardPath)) return null;
  const rl = readline.createInterface({ input: fs.createReadStream(shardPath, { encoding: "utf8" }), crlfDelay: Infinity });
  for await (const line of rl) {
    if (!line.trim()) continue;
    let row;
    try { row = JSON.parse(line); } catch { continue; }
    if (String(row[0] || "").toLowerCase() !== key) continue;
    rl.close();
    return readCatalogProductAtOffset(row[1]);
  }
  return null;
}

async function readCatalogProductAtOffset(offset) {
  const handle = await fs.promises.open(CATALOG_FILE, "r");
  try {
    const chunks = [];
    const buffer = Buffer.alloc(8192);
    let position = Number(offset || 0);
    while (true) {
      const { bytesRead } = await handle.read(buffer, 0, buffer.length, position);
      if (!bytesRead) break;
      const slice = buffer.subarray(0, bytesRead);
      const newline = slice.indexOf(10);
      if (newline >= 0) {
        chunks.push(slice.subarray(0, newline));
        break;
      }
      chunks.push(Buffer.from(slice));
      position += bytesRead;
    }
    const line = Buffer.concat(chunks).toString("utf8").trim();
    return line ? JSON.parse(line) : null;
  } finally {
    await handle.close();
  }
}

function normalizeCatalogProductForInventory(record) {
  if (!record || typeof record !== "object") return null;
  const sku = sourceTextValue(record._id || record.sku || record.SKU || record.id);
  if (!sku) return null;
  const originalSourceRecord = record && typeof record === "object" ? { ...record } : {};
  delete originalSourceRecord.productManagerFields;
  delete originalSourceRecord.original;
  const defaultImage = sourceTextValue(record.defaultImage || record.default_image || record.image || record.image_url);
  const images = [...new Set([defaultImage, ...sourceListValue(record.images || record.image_urls)].filter(Boolean))];
  const stockQty = sourceNumberValue(record.stockQty ?? record.stock_qty ?? record.qty ?? record.quantity);
  const minQuantity = sourceTextValue(productDumpRecordFieldValue(record, PRODUCT_DUMP_FIELD_ALIASES.minQuantity));
  const checkedImage = record.checkedImage || record.checked_image || {};
  const sourceBrand = sourceTextValue(record.sourceBrand || record.brand);
  const sourceCategory = formatCategoryName(record.sourceCategory || record.vendorCategory || record.category || record.product_type);
  const mainCategory = formatCategoryName(record.mainCategory || record.categoryOverride || (record.categoryVerified ? record.category : ""));

  const product = {
    sku,
    externalId: sourceTextValue(record.externalId || record._id || record.id),
    title: sourceTextValue(record.title || record.name || sku),
    marketplaceTitle: sourceTextValue(record.marketplaceTitle || record.name || record.title || sku),
    shortDescription: sourceTextValue(record.shortDescription || record.short_description),
    longDescription: sourceTextValue(record.longDescription || record.description || record.long_description),
    bulletPoints: sourceListValue(record.bulletPoints || record.bullet_points || record.keyFeatures || record.features),
    brand: sourceBrand,
    sourceBrand,
    brandLocked: sourceBooleanValue(record.brandLocked, false),
    category: mainCategory,
    mainCategory,
    categoryVerified: Boolean(mainCategory),
    sourceCategory,
    vendorCategory: sourceCategory,
    condition: sourceTextValue(record.condition) || "New",
    status: record.active === false ? "Draft" : sourceTextValue(record.status) || "Draft",
    active: sourceBooleanValue(record.active, true),
    barcode: sourceTextValue(record.barcode || record.upc || record.gtin),
    defaultImage,
    images,
    manufacturer: sourceTextValue(record.manufacturer),
    mfrPartNumber: sourceTextValue(record.mfrPartNumber || record.mfr_part_number),
    vendorSku: sourceTextValue(record.vendorSku || record.vendor_sku),
    supplier: canonicalCatalogSupplierName(
      sourceTextValue(record.supplier || record.vendor),
      sourceTextValue(record.supplierCode || record.supplier_code)
    ),
    supplierCode: sourceTextValue(record.supplierCode || record.supplier_code),
    vendor: canonicalCatalogSupplierName(
      sourceTextValue(record.vendor || record.supplier),
      sourceTextValue(record.supplierCode || record.supplier_code)
    ),
    unspsc: sourceTextValue(record.unspsc),
    uom: sourceTextValue(record.uom),
    uomQty: sourceTextValue(record.uomQty || record.uom_qty),
    minQuantity,
    quantityIncrements: sourceTextValue(productDumpRecordFieldValue(record, PRODUCT_DUMP_FIELD_ALIASES.quantityIncrements)),
    hazardous: sourceBooleanValue(record.hazardous, false),
    sdsUrl: sourceTextValue(record.sdsUrl || record.sds_url),
    itemHeight: sourceNumberValue(record.itemHeight || record.item_height),
    itemLength: sourceNumberValue(record.itemLength || record.item_length),
    itemWeight: sourceNumberValue(record.itemWeight || record.item_weight),
    itemWidth: sourceNumberValue(record.itemWidth || record.item_width),
    packageHeight: sourceNumberValue(record.packageHeight || record.package_height),
    packageLength: sourceNumberValue(record.packageLength || record.package_length),
    packageWeight: sourceNumberValue(record.packageWeight || record.package_weight),
    packageWidth: sourceNumberValue(record.packageWidth || record.package_width),
    dimensionalWeight: sourceNumberValue(record.dimensionalWeight || record.dimensional_weight),
    qty: stockQty,
    stockQty,
    stockStatus: sourceTextValue(record.stockStatus || record.stock_status),
    stockUpdatedAt: sourceTextValue(record.stockUpdatedAt || record.stock_updated_at),
    reorderPoint: sourceNumberValue(minQuantity),
    ctechId: sourceTextValue(record.ctechId || record.ctech_id),
    ctechIdLastExport: sourceTextValue(record.ctechIdLastExport || record.ctech_id_last_export),
    fobPrice: sourceNumberValue(record.fobPrice || record.fob_price),
    vendorWebsitePrice: sourceNumberValue(record.vendorWebsitePrice || record.vendor_website_price),
    price: sourceNumberValue(record.price || record.sale_price || record.sell_price),
    cost: sourceNumberValue(record.cost || record.fob_price || record.wholesale_price),
    msrp: isClearanceItem(record) ? sourceNumberValue(record.msrp || record.list_price) : 0,
    toBeDiscontinued: sourceBooleanValue(record.toBeDiscontinued ?? record.to_be_discontinued, false),
    closeoutEligible: sourceBooleanValue(record.closeoutEligible ?? record.closeout_eligible ?? record.toBeDiscontinued ?? record.to_be_discontinued, false),
    wildcardSearch: sourceTextValue(record.wildcardSearch),
    tags: sourceListValue(record.tags),
    attributes: record.attributes && typeof record.attributes === "object" ? record.attributes : {},
    productDumpCreatedAt: sourceTextValue(record.productDumpCreatedAt || record.created_at || record.createdAt),
    productDumpUpdatedAt: sourceTextValue(record.productDumpUpdatedAt || record.updated_at || record.updatedAt),
    inactiveMailedAt: sourceTextValue(record.inactiveMailedAt || record.inactive_mailed_at),
    validatedAt: sourceTextValue(record.validatedAt || record.validated_at),
    checkedImage: checkedImage && typeof checkedImage === "object" ? checkedImage : {},
    checkedImageUrl: sourceTextValue(checkedImage?.url),
    checkedImageError: sourceTextValue(checkedImage?.error),
    checkedImageSize: sourceTextValue(checkedImage?.size),
    checkedImageTimestamp: sourceTextValue(checkedImage?.timestamp),
    originalImage: sourceTextValue(record.originalImage || record.original_image),
    countryOfOrigin: sourceTextValue(record.countryOfOrigin || record.country_of_origin),
    original: record.original === undefined ? originalSourceRecord : record.original,
    productManagerFields: record.productManagerFields && typeof record.productManagerFields === "object" ? record.productManagerFields : originalSourceRecord,
    sources: { ...(record.sources || {}), catalog: sku },
    importedFrom: record.importedFrom || "source catalog",
    updatedAt: new Date().toISOString()
  };
  product.websitePrice = websitePriceFromRule(product, product.cost, SHOPIFY_PRICE_MARKUP_PERCENT);
  product.price = product.websitePrice;
  product.dimensionalWeight = product.dimensionalWeight || calculateDimensionalWeight(product);
  return product;
}

function isInventoryShellProduct(item) {
  const sku = sourceTextValue(item.sku);
  if (!sku) return false;
  const title = sourceTextValue(item.title);
  const marketplaceTitle = sourceTextValue(item.marketplaceTitle);
  return (!title || title === sku || marketplaceTitle === sku)
    && !sourceTextValue(item.vendorSku || item.vendor_sku)
    && !sourceTextValue(item.supplier || item.vendor)
    && !sourceTextValue(item.defaultImage || item.default_image)
    && !sourceTextValue(item.shortDescription || item.short_description)
    && !sourceTextValue(item.longDescription || item.description);
}

function upsertInventoryProductFromCatalog(db, product, creation = {}) {
  product = normalizeCatalogProductForInventory(product);
  if (!product) return { item: null, existing: false };
  db.inventory = Array.isArray(db.inventory) ? db.inventory : [];
  const existing = db.inventory.find((item) => String(item.sku || "").toLowerCase() === String(product.sku || "").toLowerCase());
  if (existing) {
    const wasShell = isInventoryShellProduct(existing);
    if (wasShell) {
      const keep = {
        id: existing.id,
        reserved: existing.reserved,
        shadowSkus: existing.shadowSkus,
        serialUnits: existing.serialUnits,
        warehouseStock: [],
        sources: existing.sources
      };
      Object.assign(existing, product, keep, {
        sources: { ...(product.sources || {}), ...(existing.sources || {}), catalog: product.sku },
        updatedAt: new Date().toISOString()
      });
    } else {
      applyProtectedSourceProduct(db, existing, product, "Source catalog");
    }
    return { item: existing, existing: true };
  }
  const item = {
    id: crypto.randomUUID(),
    ...product,
    qty: Number(product.stockQty ?? product.qty ?? 0),
    reserved: 0,
    reorderPoint: Number(product.reorderPoint || 0),
    shadowSkus: [],
    serialUnits: [],
    warehouseStock: [],
    sources: { ...(product.sources || {}), catalog: product.sku },
    createdAt: new Date().toISOString(),
    createdBy: String(creation.createdBy || "DataPlus").trim() || "DataPlus",
    createdMethod: String(creation.createdMethod || "Product import").trim() || "Product import",
    createdSource: String(creation.createdSource || "Source catalog / data dump").trim() || "Source catalog / data dump",
    createdSourceDetail: String(creation.createdSourceDetail || "").trim(),
    updatedAt: new Date().toISOString()
  };
  db.inventory.push(item);
  return { item, existing: false };
}

function needsSourceCatalogEnrichment(item = {}) {
  if (isInventoryShellProduct(item)) return true;
  return !sourceTextValue(item.vendorSku)
    || !sourceTextValue(item.supplier || item.vendor)
    || !sourceTextValue(item.mfrPartNumber)
    || !sourceTextValue(item.defaultImage || item.originalImage)
    || !sourceTextValue(item.shortDescription)
    || !sourceTextValue(item.longDescription)
    || !sourceTextValue(item.barcode)
    || !(Number(item.cost || item.price || item.stockQty || item.qty || 0) > 0);
}

async function buildSourceEnrichmentForSkus(db = {}, skus = []) {
  const sourceProducts = await findCatalogProductsBySkus(skus, db);
  const current = readProductSourceEnrichmentSync();
  let changed = 0;
  for (const product of sourceProducts) {
    const normalized = normalizeCatalogProductForInventory(product);
    if (!normalized?.sku) continue;
    current[String(normalized.sku).trim().toLowerCase()] = normalized;
    changed += 1;
  }
  writeProductSourceEnrichmentSync(current);
  return { changed, total: Object.keys(current).length, skus: sourceProducts.map((product) => product.sku).filter(Boolean) };
}

async function sourceEnrichmentCandidateSkusFromPostgres(options = {}) {
  const limit = Math.max(1, Math.min(50000, Number(options.limit || 1000)));
  const pageSize = Math.max(100, Math.min(5000, Number(options.pageSize || 1000)));
  const progress = typeof options.progress === "function" ? options.progress : null;
  const isCanceled = typeof options.isCanceled === "function" ? options.isCanceled : () => false;
  const totalRows = await postgres.countProducts();
  const enrichmentMap = readProductSourceEnrichmentSync();
  const candidates = [];
  let processedRows = 0;
  for (let page = 1; processedRows < totalRows && candidates.length < limit; page += 1) {
    if (isCanceled()) throw new Error("Source enrichment backfill canceled.");
    const result = await postgres.listProducts({ page, limit: pageSize });
    const products = result?.inventory || [];
    if (!products.length) break;
    for (const item of products) {
      const sku = String(item?.sku || "").trim();
      if (!sku) continue;
      const key = sku.toLowerCase();
      if (!enrichmentMap[key] && needsSourceCatalogEnrichment(item)) {
        candidates.push(sku);
        if (candidates.length >= limit) break;
      }
    }
    processedRows += products.length;
    if (progress) {
      progress({
        phase: "finding_candidates",
        processedRows,
        totalRows,
        candidateRows: candidates.length,
        message: `Found ${candidates.length.toLocaleString()} source enrichment candidate${candidates.length === 1 ? "" : "s"}.`
      });
    }
    if (products.length < pageSize) break;
  }
  return { candidates, scannedRows: processedRows, totalRows };
}

async function buildSourceEnrichmentForSkusPaged(skus = [], options = {}) {
  const uniqueSkus = [...new Set((skus || []).map((sku) => String(sku || "").trim()).filter(Boolean))];
  const chunkSize = Math.max(10, Math.min(500, Number(options.chunkSize || 100)));
  const progress = typeof options.progress === "function" ? options.progress : null;
  const isCanceled = typeof options.isCanceled === "function" ? options.isCanceled : () => false;
  const workDb = normalizeDb(await readDbFast({ skipInventory: true }));
  let changed = 0;
  let persisted = 0;
  let processedRows = 0;
  let total = Object.keys(readProductSourceEnrichmentSync()).length;
  const enrichedSkus = [];
  for (let index = 0; index < uniqueSkus.length; index += chunkSize) {
    if (isCanceled()) throw new Error("Source enrichment backfill canceled.");
    const chunk = uniqueSkus.slice(index, index + chunkSize);
    let currentProducts = [];
    if (postgres.isPostgresEnabled()) {
      currentProducts = await postgres.readProductsByKeys(chunk);
      workDb.inventory = currentProducts;
    }
    const result = await buildSourceEnrichmentForSkus(workDb, chunk);
    changed += Number(result.changed || 0);
    total = Number(result.total || total || 0);
    enrichedSkus.push(...(result.skus || []));
    if (postgres.isPostgresEnabled() && currentProducts.length && (result.skus || []).length) {
      const enrichmentMap = readProductSourceEnrichmentSync();
      const mergedProducts = currentProducts
        .map((item) => sourceEnrichedItem(item, enrichmentMap))
        .filter((item) => item?.id || item?.sku);
      if (mergedProducts.length) {
        await postgres.upsertProductsFromState(mergedProducts);
        persisted += mergedProducts.length;
      }
    }
    processedRows += chunk.length;
    if (progress) {
      progress({
        phase: "enriching",
        processedRows,
        totalRows: uniqueSkus.length,
        changed,
        message: `Updated source enrichment for ${changed.toLocaleString()} product${changed === 1 ? "" : "s"}; persisted ${persisted.toLocaleString()} Postgres row${persisted === 1 ? "" : "s"}.`
      });
    }
  }
  return { changed, persisted, total, skus: enrichedSkus };
}

function startSourceEnrichmentBackfillJob(jobId, attrs = {}) {
  setTimeout(async () => {
    const job = activeJobRecords.get(jobId);
    if (!job) return;
    try {
      job.status = "running";
      job.phase = "starting";
      job.startedAt = job.startedAt || new Date().toISOString();
      job.updatedAt = new Date().toISOString();
      job.message = "Source catalog enrichment backfill is running...";
      upsertImportJobStore(job);
      setActiveJobProgress(jobId, {
        status: "running",
        phase: "starting",
        startedAt: job.startedAt,
        processedRows: 0,
        totalRows: job.totalRows || Number(attrs.limit || 0) || 0,
        progressPercent: 0
      });
      const isCanceled = () => !["queued", "running"].includes(String(activeJobProgress.get(jobId)?.status || job.status || "").toLowerCase());
      const updateProgress = (patch = {}) => {
        const next = setActiveJobProgress(jobId, { status: "running", ...patch });
        Object.assign(job, {
          phase: next.phase,
          totalRows: next.totalRows,
          processedRows: next.processedRows,
          progressPercent: next.progressPercent,
          estimatedSecondsRemaining: next.estimatedSecondsRemaining,
          changed: patch.changed ?? job.changed,
          message: patch.message || job.message,
          updatedAt: new Date().toISOString()
        });
        activeJobRecords.set(jobId, normalizeImportJob(job));
        upsertImportJobStore(job);
      };
      let candidates = Array.isArray(attrs.skus)
        ? attrs.skus.map((sku) => String(sku || "").trim()).filter(Boolean)
        : [];
      let scannedRows = 0;
      if (!candidates.length && postgres.isPostgresEnabled()) {
        const result = await sourceEnrichmentCandidateSkusFromPostgres({
          limit: attrs.limit,
          isCanceled,
          progress: updateProgress
        });
        candidates = result.candidates;
        scannedRows = result.scannedRows;
      }
      if (!candidates.length) {
        activeJobProgress.delete(jobId);
        finishImportJob(job, {
          status: "success",
          phase: "complete",
          message: "No products need source catalog enrichment.",
          totalRows: scannedRows || 0,
          processedRows: scannedRows || 0,
          progressPercent: 100,
          estimatedSecondsRemaining: 0,
          changed: 0
        });
        return;
      }
      updateProgress({
        phase: "enriching",
        processedRows: 0,
        totalRows: candidates.length,
        message: `Updating source enrichment for ${candidates.length.toLocaleString()} product${candidates.length === 1 ? "" : "s"}...`
      });
      const result = await buildSourceEnrichmentForSkusPaged(candidates, { isCanceled, progress: updateProgress });
      publicStateJsonCache = null;
      activeJobProgress.delete(jobId);
      finishImportJob(job, {
        status: "success",
        phase: "complete",
        message: `Source catalog enrichment updated for ${Number(result.changed || 0).toLocaleString()} product${Number(result.changed || 0) === 1 ? "" : "s"}.`,
        totalRows: candidates.length,
        processedRows: candidates.length,
        progressPercent: 100,
        estimatedSecondsRemaining: 0,
        changed: result.changed || 0,
        details: [
          scannedRows ? `Scanned ${scannedRows.toLocaleString()} Postgres products to find candidates.` : "",
          Number(result.persisted || 0) ? `Persisted ${Number(result.persisted || 0).toLocaleString()} enriched product row${Number(result.persisted || 0) === 1 ? "" : "s"} back to Postgres.` : ""
        ].filter(Boolean).join(" ")
      });
    } catch (error) {
      activeJobProgress.delete(jobId);
      const canceled = /canceled|cancelled|stopped/i.test(String(error.message || ""));
      finishImportJob(job, {
        status: canceled ? "stopped" : "failed",
        phase: canceled ? "stopped" : "failed",
        message: canceled ? "Source catalog enrichment backfill was canceled." : error.message || "Source catalog enrichment backfill failed.",
        errors: canceled ? [] : [error.message || "Source catalog enrichment backfill failed."],
        missingCount: canceled ? 0 : 1
      });
    }
  }, 1000);
}

async function findCatalogProductsBySkus(skus = [], db = {}) {
  const wanted = new Set(skus.map((sku) => String(sku || "").toLowerCase()).filter(Boolean));
  const found = [];
  if (!wanted.size) return found;
  const overrides = sourceCatalogOverrideMap(db);
  const vendorMappings = vendorCategoryMappingMap(db);
  const productsBySku = inventoryBySkuMap(db);
  const decorate = (product) => decorateSourceCatalogProduct(product, overrides, productsBySku, vendorMappings);
  if (postgres.isPostgresEnabled()) {
    try {
      const rows = await postgres.readVendorCatalogItemsBySkus([...wanted]);
      if (Array.isArray(rows) && rows.length) {
        for (const row of rows) {
          const normalized = normalizeCatalogProductForInventory(row);
          if (!normalized?.sku) continue;
          found.push(decorate(normalized));
          wanted.delete(String(normalized.sku || "").toLowerCase());
        }
      }
      return found;
    } catch (error) {
      console.warn("Postgres source SKU lookup failed, falling back to catalog file:", error.message);
    }
  }
  if (!fs.existsSync(CATALOG_FILE)) return found;
  const index = readSourceCatalogIndexManifest();
  if (index) {
    const byShard = new Map();
    for (const sku of wanted) {
      const shard = skuShardName(sku);
      byShard.set(shard, [...(byShard.get(shard) || []), sku]);
    }
    for (const [shard, shardSkus] of byShard) {
      const shardPath = path.join(CATALOG_INDEX_SKU_DIR, `${shard}.ndjson`);
      if (!fs.existsSync(shardPath)) continue;
      const shardWanted = new Set(shardSkus);
      const rl = readline.createInterface({ input: fs.createReadStream(shardPath, { encoding: "utf8" }), crlfDelay: Infinity });
      for await (const line of rl) {
        if (!line.trim()) continue;
        let row;
        try { row = JSON.parse(line); } catch { continue; }
        const sku = String(row[0] || "").toLowerCase();
        if (!shardWanted.has(sku)) continue;
        const product = await readCatalogProductAtOffset(row[1]);
        if (product) found.push(decorate(product));
        wanted.delete(sku);
        shardWanted.delete(sku);
        if (!shardWanted.size) {
          rl.close();
          break;
        }
      }
    }
    return found;
  }
  const rl = readline.createInterface({
    input: fs.createReadStream(CATALOG_FILE, { encoding: "utf8" }),
    crlfDelay: Infinity
  });
  for await (const line of rl) {
    if (!line.trim()) continue;
    let product;
    try {
      product = JSON.parse(line);
    } catch {
      continue;
    }
    const key = String(product.sku || "").toLowerCase();
    if (wanted.has(key)) {
      found.push(decorate(product));
      wanted.delete(key);
      if (!wanted.size) {
        rl.close();
        break;
      }
    }
  }
  return found;
}

async function purchaseOrderWithCatalogImages(purchaseOrder = {}, db = {}) {
  const lineField = Array.isArray(purchaseOrder.items)
    ? "items"
    : Array.isArray(purchaseOrder.lines)
      ? "lines"
      : "";
  if (!lineField) return purchaseOrder;

  const lines = purchaseOrder[lineField];
  const skus = [...new Set(lines.map((line) => String(line?.sku || "").trim()).filter(Boolean))];
  if (!skus.length) return purchaseOrder;

  const [managedProducts, sourceProducts] = await Promise.all([
    postgres.isPostgresEnabled() ? postgres.readProductsByKeys(skus) : Promise.resolve([]),
    findCatalogProductsBySkus(skus, db)
  ]);
  const imagesBySku = new Map();
  for (const product of [...(managedProducts || []), ...(sourceProducts || [])]) {
    const key = String(product?.sku || "").trim().toLowerCase();
    const image = compactCatalogImageUrl(product || {});
    if (key && image && !imagesBySku.has(key)) imagesBySku.set(key, image);
  }

  return {
    ...purchaseOrder,
    [lineField]: lines.map((line) => ({
      ...line,
      defaultImage: String(line?.defaultImage || line?.imageUrl || line?.image || "").trim()
        || imagesBySku.get(String(line?.sku || "").trim().toLowerCase())
        || ""
    }))
  };
}

async function findSourceCatalogAlternatesBySkus(skus = [], db = {}) {
  const wanted = [...new Set(skus.map((sku) => String(sku || "").trim().toLowerCase()).filter(Boolean))];
  const result = Object.fromEntries(wanted.map((sku) => [sku, []]));
  if (!wanted.length) return result;
  const overrides = sourceCatalogOverrideMap(db);
  const vendorMappings = vendorCategoryMappingMap(db);
  const productsBySku = inventoryBySkuMap(db);
  if (postgres.isPostgresEnabled()) {
    try {
      const rows = await postgres.readVendorCatalogItemsBySkus(wanted);
      if (Array.isArray(rows)) {
        for (const row of rows) {
          const normalized = normalizeCatalogProductForInventory(row);
          if (!normalized?.sku) continue;
          const sku = String(normalized.sku || "").toLowerCase();
          if (!result[sku]) continue;
          const decorated = decorateSourceCatalogProduct(normalized, overrides, productsBySku, vendorMappings);
          if (!decorated.sourceCatalogDeleted) result[sku].push(catalogSummary(decorated));
        }
        return result;
      }
    } catch (error) {
      console.warn("Postgres source alternate lookup failed, falling back to catalog file:", error.message);
    }
  }
  if (!fs.existsSync(CATALOG_FILE)) return result;
  const index = readSourceCatalogIndexManifest();
  if (index) {
    const byShard = new Map();
    for (const sku of wanted) {
      const shard = skuShardName(sku);
      byShard.set(shard, [...(byShard.get(shard) || []), sku]);
    }
    for (const [shard, shardSkus] of byShard) {
      const shardPath = path.join(CATALOG_INDEX_SKU_DIR, `${shard}.ndjson`);
      if (!fs.existsSync(shardPath)) continue;
      const shardWanted = new Set(shardSkus);
      const rl = readline.createInterface({ input: fs.createReadStream(shardPath, { encoding: "utf8" }), crlfDelay: Infinity });
      for await (const line of rl) {
        if (!line.trim()) continue;
        let row;
        try { row = JSON.parse(line); } catch { continue; }
        const sku = String(row[0] || "").toLowerCase();
        if (!shardWanted.has(sku)) continue;
        const product = await readCatalogProductAtOffset(row[1]);
        if (!product) continue;
        const decorated = decorateSourceCatalogProduct(product, overrides, productsBySku, vendorMappings);
        if (!decorated.sourceCatalogDeleted) result[sku].push(catalogSummary(decorated));
      }
    }
    return result;
  }
  const wantedSet = new Set(wanted);
  const rl = readline.createInterface({
    input: fs.createReadStream(CATALOG_FILE, { encoding: "utf8" }),
    crlfDelay: Infinity
  });
  for await (const line of rl) {
    if (!line.trim()) continue;
    let product;
    try { product = JSON.parse(line); } catch { continue; }
    const sku = String(product.sku || "").toLowerCase();
    if (!wantedSet.has(sku)) continue;
    const decorated = decorateSourceCatalogProduct(product, overrides, productsBySku, vendorMappings);
    if (!decorated.sourceCatalogDeleted) result[sku].push(catalogSummary(decorated));
  }
  return result;
}

async function annotateCatalogAlternateCounts(items = [], db = {}) {
  const skus = items.map((item) => item.sku).filter(Boolean);
  if (!skus.length) return items;
  const alternates = await findSourceCatalogAlternatesBySkus(skus, db);
  return items.map((item) => {
    const rows = alternates[String(item.sku || "").toLowerCase()] || [];
    const vendors = new Set(rows.map((row) => row.supplier || row.vendor || "").filter(Boolean).map((value) => String(value).toLowerCase()));
    return { ...item, alternateVendorCount: Math.max(0, vendors.size - 1) };
  });
}

async function scanCatalog({ query = "", page = 1, limit = 50, filters = {}, sort = "", cursor = "", db = {} } = {}) {
  const pageNumber = Math.max(1, Number(page || 1));
  const pageSize = Math.min(100, Math.max(1, Number(limit || 50)));
  const offset = (pageNumber - 1) * pageSize;
  const q = String(query || "").trim().toLowerCase();
  const exactSkuQuery = /^[a-z0-9_-]{6,}$/i.test(String(query || "").trim());
  const filtered = hasCatalogFilters(filters);
  const selectedSuppliers = String(filters.suppliers || filters.supplier || "").split("|").map((value) => value.trim()).filter(Boolean);
  const supplierIndexedFilter = selectedSuppliers.length >= 1 && !q;
  const supplierOnlyFilter = supplierIndexedFilter && [filters.active, filters.productMembership, filters.stockStatus, filters.hasStock, filters.hasImage, filters.multipleSuppliers, filters.stockQty, filters.stockQtyOperator, filters.hazardous, filters.toBeDiscontinued, filters.brand, filters.manufacturer, filters.category].every((value) => !value);
  const vendorIndex = supplierIndexedFilter ? readCatalogVendorIndex() : null;
  const supplierNames = new Set(selectedSuppliers.map((supplier) => supplier.toLowerCase()));
  const supplierTotal = supplierOnlyFilter
    ? (vendorIndex?.vendors || []).filter((row) => supplierNames.has(String(row.name || "").toLowerCase())).reduce((sum, row) => sum + Number(row.productCount || 0), 0)
    : 0;
  const maxScanRows = q && !filtered ? 50000 : Infinity;
  const result = {
    items: [],
    page: pageNumber,
    limit: pageSize,
    totalMatches: 0,
    hasMore: false,
    scanned: 0,
    partial: false,
    manifest: readCatalogManifest(),
    vendorIndex: supplierIndexedFilter ? vendorIndex : undefined
  };
  const cacheLatestPage = sort === "latest" && !q && !filtered && pageNumber <= 200;
  const cacheCursor = cursor ? crypto.createHash("sha1").update(String(cursor)).digest("hex").slice(0, 16) : "first";
  const cacheKey = cacheLatestPage ? `dataplus:catalog:latest:v3:${cacheCursor}:${pageSize}` : "";
  if (cacheKey) {
    const cached = await redisCache.getJson(cacheKey);
    if (cached) return { ...cached, cached: true };
  }
  if (postgres.isPostgresEnabled()) {
    try {
      const pgResult = await postgres.listVendorCatalogItems({ query, page: pageNumber, limit: pageSize, filters: catalogFiltersWithIndexedSupplierKeys(filters), sort, cursor });
      if (pgResult) {
        const overrides = sourceCatalogOverrideMap(db);
        const vendorMappings = vendorCategoryMappingMap(db);
        const normalizedItems = pgResult.items
          .map((item) => normalizeCatalogProductForInventory(item))
          .filter(Boolean);
        const managedProducts = await postgres.readProductsByKeys(
          normalizedItems.flatMap((item) => sourceCatalogLookupKeys(item)),
          { includeMarketplaceIds: false }
        );
        const productsBySku = managedProductLookup(managedProducts);
        result.items = normalizedItems
          .map((item) => decorateSourceCatalogProduct(item, overrides, productsBySku, vendorMappings))
          .filter((item) => !item.sourceCatalogDeleted)
          .map(catalogSummary);
        result.totalMatches = Number(pgResult.total || 0);
        result.hasMore = result.totalMatches > offset + result.items.length;
        result.scanned = result.items.length;
        result.manifest = { ...(result.manifest || {}), productCount: result.totalMatches, source: "postgres:vendor_catalog_items" };
        result.indexed = true;
        result.database = "postgres";
        result.nextCursor = pgResult.nextCursor || "";
        if (cacheKey) await redisCache.setJson(cacheKey, result, REDIS_CATALOG_CACHE_TTL_SECONDS);
        return result;
      }
    } catch (error) {
      console.warn("Postgres source catalog scan failed, falling back to catalog file:", error.message);
    }
  }
  if (!fs.existsSync(CATALOG_FILE)) return result;
  if (filters.toBeDiscontinued === "true" && !q) {
    const closeoutSkus = readCloseoutSkus();
    result.totalMatches = closeoutSkus.length;
    result.hasMore = result.totalMatches > offset + pageSize;
    if (!closeoutSkus.length) return result;
    const pageSkus = closeoutSkus.slice(offset, offset + pageSize);
    const items = await findCatalogProductsBySkus(pageSkus, db);
    result.items = items
      .filter((item) => productMatchesCatalogFilters(item, filters))
      .map(catalogSummary);
    result.hasMore = result.totalMatches > offset + result.items.length;
    result.indexed = true;
    return result;
  }
  const overrides = sourceCatalogOverrideMap(db);
  const vendorMappings = vendorCategoryMappingMap(db);
  const productsBySku = managedProductLookup(Array.isArray(db.inventory) ? db.inventory : []);
  const sourceIndex = supplierIndexedFilter ? readSourceCatalogIndexManifest() : null;
  if (sourceIndex) {
    const supplierRows = (sourceIndex.suppliers || []).filter((row) => supplierNames.has(String(row.name || "").toLowerCase()));
    if (supplierRows.length) {
      let matched = 0;
      let scanned = 0;
      for (const supplier of supplierRows) {
        const supplierPath = path.join(CATALOG_INDEX_DIR, supplier.file || "");
        if (!fs.existsSync(supplierPath)) continue;
        const rl = readline.createInterface({ input: fs.createReadStream(supplierPath, { encoding: "utf8" }), crlfDelay: Infinity });
        for await (const line of rl) {
          if (!line.trim()) continue;
          scanned += 1;
          let item;
          try { item = JSON.parse(line); } catch { continue; }
          item = decorateSourceCatalogProduct(item, overrides, productsBySku, vendorMappings);
          if (item.sourceCatalogDeleted) continue;
          if (!productMatchesCatalogFilters(item, filters)) continue;
          if (matched >= offset && result.items.length < pageSize) result.items.push(catalogSummary(item));
          matched += 1;
          if (supplierOnlyFilter && result.items.length >= pageSize && matched >= offset + pageSize) {
            rl.close();
            break;
          }
        }
        if (supplierOnlyFilter && result.items.length >= pageSize && matched >= offset + pageSize) break;
      }
      result.scanned = scanned;
      result.totalMatches = supplierOnlyFilter ? (supplierRows.reduce((sum, row) => sum + Number(row.productCount || 0), 0) || matched) : matched;
      result.items = await annotateCatalogAlternateCounts(result.items, db);
      result.hasMore = result.totalMatches > offset + result.items.length;
      result.indexed = true;
      return result;
    }
  }

  const rl = readline.createInterface({
    input: fs.createReadStream(CATALOG_FILE, { encoding: "utf8" }),
    crlfDelay: Infinity
  });

  for await (const line of rl) {
    result.scanned += 1;
    if (!line.trim()) continue;
    let product;
    try {
      product = JSON.parse(line);
    } catch {
      continue;
    }
    if (Number.isFinite(maxScanRows) && result.scanned >= maxScanRows) {
      result.partial = true;
      rl.close();
      break;
    }
    product = decorateSourceCatalogProduct(product, overrides, productsBySku, vendorMappings);
    if (product.sourceCatalogDeleted) continue;
    if (q && !catalogSearchText(product).includes(q)) continue;
    if (!productMatchesCatalogFilters(product, filters)) continue;
    if (result.totalMatches >= offset && result.items.length < pageSize) {
      result.items.push(catalogSummary(product));
    }
    result.totalMatches += 1;
    if (exactSkuQuery && String(product.sku || "").toLowerCase() === q) {
      result.hasMore = false;
      rl.close();
      break;
    }
    if (q && !filtered && result.items.length >= pageSize) {
      result.hasMore = true;
      result.partial = true;
      rl.close();
      break;
    }
    if (supplierOnlyFilter && supplierTotal && result.items.length >= pageSize && result.totalMatches >= offset + pageSize) {
      result.totalMatches = supplierTotal;
      result.hasMore = supplierTotal > offset + result.items.length;
      rl.close();
      break;
    }
    if (!filtered && !q && result.items.length >= pageSize && result.totalMatches > offset + pageSize) {
      result.hasMore = true;
      rl.close();
      break;
    }
  }
  if (supplierOnlyFilter && supplierTotal) result.totalMatches = supplierTotal;
  if (!result.hasMore) result.hasMore = result.totalMatches > offset + result.items.length;
  if (!q && !hasCatalogFilters(filters) && result.manifest?.productCount) result.totalMatches = Number(result.manifest.productCount || result.totalMatches);
  result.items = await annotateCatalogAlternateCounts(result.items, db);
  return result;
}

async function collectCatalogProductsForExport({ query = "", filters = {}, limit = 10000, db = {} } = {}) {
  const maxItems = Math.min(25000, Math.max(1, Number(limit || 10000)));
  const q = String(query || "").trim().toLowerCase();
  const overrides = sourceCatalogOverrideMap(db);
  const vendorMappings = vendorCategoryMappingMap(db);
  const productsBySku = managedProductLookup(Array.isArray(db.inventory) ? db.inventory : []);
  if (postgres.isPostgresEnabled()) {
    try {
      const pgResult = await postgres.collectVendorCatalogItems({ query, filters: catalogFiltersWithIndexedSupplierKeys(filters), limit: maxItems });
      if (pgResult) {
        const normalizedItems = pgResult.items
          .map((item) => normalizeCatalogProductForInventory(item))
          .filter(Boolean);
        const managedProducts = await postgres.readProductsByKeys(
          normalizedItems.flatMap((item) => sourceCatalogLookupKeys(item)),
          { includeMarketplaceIds: false }
        );
        const managedBySku = managedProductLookup(managedProducts);
        return {
          items: normalizedItems
            .map((item) => decorateSourceCatalogProduct(item, overrides, managedBySku, vendorMappings))
            .filter((item) => !item.sourceCatalogDeleted)
            .map(catalogSummary),
          matched: Number(pgResult.matched || 0),
          limited: Boolean(pgResult.limited),
          database: "postgres"
        };
      }
    } catch (error) {
      console.warn("Postgres source catalog export collection failed, falling back to catalog file:", error.message);
    }
  }
  const selectedSuppliers = String(filters.suppliers || filters.supplier || "").split("|").map((value) => value.trim()).filter(Boolean);
  const supplierIndexedFilter = selectedSuppliers.length >= 1 && !q;
  const supplierOnlyFilter = supplierIndexedFilter && [filters.active, filters.productMembership, filters.stockStatus, filters.hasStock, filters.hasImage, filters.multipleSuppliers, filters.stockQty, filters.stockQtyOperator, filters.hazardous, filters.toBeDiscontinued, filters.brand, filters.manufacturer, filters.category].every((value) => !value);
  const sourceIndex = supplierIndexedFilter ? readSourceCatalogIndexManifest() : null;
  const supplierNames = new Set(selectedSuppliers.map((supplier) => supplier.toLowerCase()));
  const items = [];
  let matched = 0;

  if (sourceIndex) {
    const supplierRows = (sourceIndex.suppliers || []).filter((row) => supplierNames.has(String(row.name || "").toLowerCase()));
    for (const supplier of supplierRows) {
      const supplierPath = path.join(CATALOG_INDEX_DIR, supplier.file || "");
      if (!fs.existsSync(supplierPath)) continue;
      const rl = readline.createInterface({ input: fs.createReadStream(supplierPath, { encoding: "utf8" }), crlfDelay: Infinity });
      for await (const line of rl) {
        if (!line.trim()) continue;
        let item;
        try { item = JSON.parse(line); } catch { continue; }
        item = decorateSourceCatalogProduct(item, overrides, productsBySku, vendorMappings);
        if (item.sourceCatalogDeleted) continue;
        if (!productMatchesCatalogFilters(item, filters)) continue;
        matched += 1;
        items.push(catalogSummary(item));
        if (items.length >= maxItems) {
          rl.close();
          break;
        }
      }
      if (items.length >= maxItems) break;
    }
    return { items, matched: supplierRows.reduce((sum, row) => sum + Number(row.productCount || 0), 0) || matched, limited: items.length >= maxItems };
  }

  if (!fs.existsSync(CATALOG_FILE)) return { items, matched: 0, limited: false };
  const rl = readline.createInterface({
    input: fs.createReadStream(CATALOG_FILE, { encoding: "utf8" }),
    crlfDelay: Infinity
  });
  for await (const line of rl) {
    if (!line.trim()) continue;
    let product;
    try {
      product = JSON.parse(line);
    } catch {
      continue;
    }
    product = decorateSourceCatalogProduct(product, overrides, productsBySku, vendorMappings);
    if (product.sourceCatalogDeleted) continue;
    if (q && !catalogSearchText(product).includes(q)) continue;
    if (!productMatchesCatalogFilters(product, filters)) continue;
    matched += 1;
    items.push(catalogSummary(product));
    if (items.length >= maxItems) {
      rl.close();
      break;
    }
  }
  return { items, matched, limited: items.length >= maxItems };
}

function normalizeSourceImportMode(value = "") {
  const mode = String(value || "").trim().toLowerCase();
  if (["new-only", "new"].includes(mode)) return "new-only";
  if (["update-existing", "updates-only", "existing-only", "update"].includes(mode)) return "update-existing";
  return "new-and-update";
}

function catalogImportComparable(item = {}) {
  const fields = [
    "sku", "title", "marketplaceTitle", "shortDescription", "longDescription", "brand", "supplier", "supplierCode",
    "vendor", "vendorSku", "mfrPartNumber", "barcode", "category", "mainCategory", "sourceCategory", "vendorCategory",
    "uom", "uomQty", "minQuantity", "quantityIncrements", "stockQty", "qty", "stockStatus", "cost", "sourceCost",
    "price", "websitePrice", "vendorWebsitePrice", "fobPrice", "msrp", "toBeDiscontinued", "closeoutEligible",
    "packageLength", "packageWidth", "packageHeight", "packageWeight", "itemLength", "itemWidth", "itemHeight", "itemWeight",
    "dimensionalWeight", "defaultImage", "originalImage"
  ];
  const normalized = {};
  for (const field of fields) {
    const value = item[field];
    if (typeof value === "number") normalized[field] = Number.isFinite(value) ? Number(value.toFixed(4)) : 0;
    else if (typeof value === "boolean") normalized[field] = value;
    else if (Array.isArray(value)) normalized[field] = value.map((entry) => sourceTextValue(entry)).filter(Boolean).sort();
    else normalized[field] = sourceTextValue(value);
  }
  return JSON.stringify(normalized);
}

async function sourceCatalogImportImpact({ skus = [], allFiltered = false, query = "", filters = {}, limit = 0, db = null, importMode = "" } = {}) {
  if (!postgres.isPostgresEnabled()) return { matched: 0, requested: 0, importable: 0, existing: 0, newProducts: 0, closeouts: 0, limited: false, skus: [] };
  const settings = readSystemSettingsStore(db?.systemSettings || {});
  let mode = normalizeSourceImportMode(importMode || settings.sourceCatalogDefaultImportMode);
  const newSkusEnabled = settings.catalogImportNewSkusEnabled !== false;
  if (!newSkusEnabled && mode !== "update-existing") mode = "update-existing";
  const batchLimit = sourceCatalogImportBatchLimit(settings);
  const effectiveLimit = Math.max(1, Math.min(batchLimit, Number(limit || batchLimit)));
  let sourceRows = [];
  let matched = skus.length;
  let limited = false;
  if (allFiltered) {
    const collected = await postgres.collectVendorCatalogItems({
      query,
      filters: catalogFiltersWithIndexedSupplierKeys(filters),
      limit: effectiveLimit,
      includeCount: false
    });
    sourceRows = collected?.items || [];
    matched = Number(collected?.matched || sourceRows.length || 0);
    limited = Boolean(collected?.limited);
  } else {
    sourceRows = await postgres.readVendorCatalogItemsBySkus(skus);
  }
  const runtimeDb = db || normalizeDb(await readDbFast({ skipInventory: true }));
  const overrides = sourceCatalogOverrideMap(runtimeDb);
  sourceRows = sourceRows.filter((row) => !overrides[String(row.sku || "").toLowerCase()]?.deleted);
  const importSkus = [...new Set(sourceRows.map((row) => row.sku).filter(Boolean))];
  const importKeys = [...new Set(sourceRows.flatMap((row) => sourceCatalogLookupKeys(row)))];
  const existingProducts = importKeys.length ? await postgres.readProductsByKeys(importKeys) : [];
  const existingByKey = managedProductLookup(existingProducts);
  const sourceRowIsManaged = (row) => Boolean(managedProductForSource(row, existingByKey));
  const candidateSourceRows = sourceRows;
  const existingCount = candidateSourceRows.filter(sourceRowIsManaged).length;
  const newCount = candidateSourceRows.length - existingCount;
  if (mode === "new-only") {
    sourceRows = sourceRows.filter((row) => !sourceRowIsManaged(row));
  } else if (mode === "update-existing") {
    sourceRows = sourceRows.filter((row) => sourceRowIsManaged(row));
  }
  const discontinuedRows = sourceRows.filter((row) => row.toBeDiscontinued || row.closeoutEligible);
  const skippedDiscontinued = settings.catalogMarkDiscontinuedRows === false ? discontinuedRows.length : 0;
  if (settings.catalogMarkDiscontinuedRows === false) {
    sourceRows = sourceRows.filter((row) => !row.toBeDiscontinued && !row.closeoutEligible);
  }
  const filteredImportSkus = [...new Set(sourceRows.map((row) => row.sku).filter(Boolean))];
  const closeouts = discontinuedRows.length;
  return {
    matched,
    requested: allFiltered ? matched : skus.length,
    importable: filteredImportSkus.length,
    existing: existingCount,
    newProducts: newCount,
    skippedExisting: mode === "new-only" ? existingCount : 0,
    skippedNew: mode === "update-existing" ? newCount : 0,
    newSkusDisabled: !newSkusEnabled,
    skippedDiscontinued,
    closeouts,
    limited,
    batchLimit,
    importMode: mode,
    skus: filteredImportSkus,
    sourceRows
  };
}

async function promoteSourceCatalogRows({ sourceRows = [], skus = [], progress, isCanceled } = {}) {
  const db = normalizeDb(await readDbFast({ skipInventory: true }));
  const settings = readSystemSettingsStore(db.systemSettings || {});
  let rows = sourceRows;
  if (!rows.length && skus.length) rows = await postgres.readVendorCatalogItemsBySkus(skus);
  if (settings.catalogMarkDiscontinuedRows === false) {
    rows = rows.filter((row) => !row.toBeDiscontinued && !row.closeoutEligible);
  }
  const importSkus = [...new Set(rows.map((row) => row.sku).filter(Boolean))];
  const importKeys = [...new Set(rows.flatMap((row) => sourceCatalogLookupKeys(row)))];
  const existingProducts = importKeys.length ? await postgres.readProductsByKeys(importKeys) : [];
  db.inventory = existingProducts || [];
  const products = rows.map(normalizeCatalogProductForInventory).filter(Boolean);
  const changedItems = [];
  let created = 0;
  let updated = 0;
  let skippedUnchanged = 0;
  let skippedNew = 0;
  const existingByKey = managedProductLookup(existingProducts);
  for (let index = 0; index < products.length; index += 1) {
    if (isCanceled?.()) throw new Error("Source catalog import canceled.");
    const product = products[index];
    const existing = managedProductForSource(product, existingByKey);
    const existed = Boolean(existing);
    const shouldReport = progress && (index % 250 === 0 || index === products.length - 1);
    if (!existed && settings.catalogImportNewSkusEnabled === false) {
      skippedNew += 1;
      if (shouldReport) progress({
        phase: "promoting_products",
        processedRows: index + 1,
        totalRows: products.length,
        message: `Reviewed ${(index + 1).toLocaleString()} of ${products.length.toLocaleString()} source products (${skippedNew.toLocaleString()} new SKU${skippedNew === 1 ? "" : "s"} skipped by catalog settings).`
      });
      continue;
    }
    if (existed && settings.catalogUpdateChangedRowsOnly !== false && catalogImportComparable(existing) === catalogImportComparable(product)) {
      skippedUnchanged += 1;
      if (shouldReport) progress({
        phase: "promoting_products",
        processedRows: index + 1,
        totalRows: products.length,
        message: `Reviewed ${(index + 1).toLocaleString()} of ${products.length.toLocaleString()} source products (${skippedUnchanged.toLocaleString()} unchanged row${skippedUnchanged === 1 ? "" : "s"} skipped).`
      });
      continue;
    }
    const upserted = upsertInventoryProductFromCatalog(db, product, {
      createdBy: "DataPlus",
      createdMethod: "Product import",
      createdSource: "Source catalog / data dump"
    });
    if (upserted.item) changedItems.push(upserted.item);
    if (existed || upserted.existing) updated += 1;
    else created += 1;
    if (shouldReport) {
      progress({
        phase: "promoting_products",
        processedRows: index + 1,
        totalRows: products.length,
        message: `Reviewed ${(index + 1).toLocaleString()} of ${products.length.toLocaleString()} source products; imported ${changedItems.length.toLocaleString()} changed.`
      });
    }
  }
  const batchSize = 1000;
  for (let index = 0; index < changedItems.length; index += batchSize) {
    if (isCanceled?.()) throw new Error("Source catalog import canceled.");
    await postgres.upsertProductsFromState(changedItems.slice(index, index + batchSize));
    if (progress) {
      progress({
        phase: "saving_products",
        processedRows: Math.min(index + batchSize, changedItems.length),
        totalRows: changedItems.length,
        message: `Saved ${Math.min(index + batchSize, changedItems.length).toLocaleString()} of ${changedItems.length.toLocaleString()} products.`
      });
    }
  }
  const summary = await postgres.readOperationalSummary();
  return { changed: changedItems.length, created, updated, skippedUnchanged, skippedNew, requested: importSkus.length, summary };
}

async function queueSourceCatalogImportJob(db, body = {}, impact = {}) {
  const totalRows = Number(impact.importable || impact.requested || 0);
  const attrs = {
    section: "Source Catalog",
    category: "Source Catalog",
    operation: body.allFiltered ? "Filtered source catalog import" : "Source catalog import",
    direction: "import",
    status: "queued",
    fileName: "source-catalog-filtered-import",
    totalRows,
    processedRows: 0,
    progressPercent: 0,
    phase: "queued",
    workerTask: shouldRunJobsInline() ? "" : "source-catalog-import",
    workerPayload: shouldRunJobsInline() ? {} : body,
    message: `Source catalog import queued for ${totalRows.toLocaleString()} product${totalRows === 1 ? "" : "s"}.`,
    details: [
      body.allFiltered ? "Scope: all filtered source catalog results." : "Scope: selected source catalog rows.",
      impact.importMode ? `Import mode: ${impact.importMode}.` : "",
      impact.limited ? `Limited to first ${Number(impact.batchLimit || 25000).toLocaleString()} matches.` : "",
      impact.newSkusDisabled ? "New SKU creation is disabled by Catalog settings." : "",
      impact.skippedNew ? `${Number(impact.skippedNew).toLocaleString()} new SKU${Number(impact.skippedNew) === 1 ? "" : "s"} will be skipped.` : "",
      impact.skippedDiscontinued ? `${Number(impact.skippedDiscontinued).toLocaleString()} discontinued/closeout row${Number(impact.skippedDiscontinued) === 1 ? "" : "s"} will be skipped.` : "",
      "Unchanged existing rows are skipped during the worker run when change-only updates are enabled."
    ].filter(Boolean).join(" ")
  };
  const duplicate = await findActiveDuplicateImportJob(db, attrs);
  if (duplicate) {
    duplicate.duplicateOfActiveJob = true;
    duplicate.message = `${duplicate.operation || "Source catalog import"} is already ${String(duplicate.status || "queued").toLowerCase()}.`;
    return normalizeImportJob(duplicate);
  }
  const job = createImportJob(db, attrs);
  if (shouldRunJobsInline()) {
    activeJobRecords.set(job.id, normalizeImportJob(job));
    setActiveJobProgress(job.id, { status: "queued", phase: "queued", totalRows, processedRows: 0, progressPercent: 0 });
    startSourceCatalogImportJob(job.id, body);
  }
  return job;
}

async function runSourceCatalogImportWorkerJob(job = {}, body = {}) {
  const startedAt = job.startedAt || new Date().toISOString();
  job = await persistWorkerImportJob(job, {
    status: "running",
    phase: "collecting_source_rows",
    startedAt,
    processedRows: 0,
    message: "Collecting source catalog rows..."
  });
  let lastPersistedAt = 0;
  const progress = (patch = {}) => {
    const processedRows = Number(patch.processedRows ?? job.processedRows ?? 0) || 0;
    const totalRows = Number(patch.totalRows ?? job.totalRows ?? 0) || 0;
    Object.assign(job, normalizeImportJob({
      ...job,
      ...patch,
      status: "running",
      totalRows,
      processedRows,
      progressPercent: patch.progressPercent ?? progressPercent(processedRows, totalRows),
      estimatedSecondsRemaining: patch.estimatedSecondsRemaining ?? estimateRemainingSeconds(startedAt, processedRows, totalRows),
      lastProgressAt: new Date().toISOString()
    }));
    if (Date.now() - lastPersistedAt > 1000 || Number(job.progressPercent || 0) >= 100) {
      lastPersistedAt = Date.now();
      postgres.upsertOperationJob(job).catch((error) => console.error("Unable to persist source import progress:", error.message || error));
    }
  };
  const runningDb = normalizeDb(await readDbFast({ skipInventory: true }));
  const impact = await sourceCatalogImportImpact({
    skus: Array.isArray(body.skus) ? body.skus : [],
    allFiltered: body.allFiltered === true || String(body.allFiltered || "").toLowerCase() === "true",
    query: body.query || "",
    filters: body.filters || {},
    limit: body.limit || 25000,
    importMode: body.importMode || body.sourceImportMode || "",
    db: runningDb
  });
  progress({ phase: "source_rows_ready", processedRows: 0, totalRows: impact.importable, message: `${impact.importable.toLocaleString()} source rows ready to import.` });
  const result = await promoteSourceCatalogRows({ sourceRows: impact.sourceRows || [], skus: impact.skus || [], progress, isCanceled: () => false });
  let analyzeResult = { tables: [] };
  try {
    analyzeResult = await postgres.analyzeCatalogTables({ products: true });
  } catch (error) {
    analyzeResult = { tables: [], error: error.message || "Planner statistics refresh failed." };
  }
  const status = impact.limited || impact.skippedNew || result.skippedNew || impact.skippedDiscontinued ? "warning" : "success";
  const message = `Reviewed ${result.requested.toLocaleString()} source product${result.requested === 1 ? "" : "s"}; imported ${result.changed.toLocaleString()} changed (${result.created.toLocaleString()} new, ${result.updated.toLocaleString()} updated).`;
  finishImportJob(job, {
    status,
    message,
    details: [job.details, result.skippedUnchanged ? `${result.skippedUnchanged.toLocaleString()} unchanged row${result.skippedUnchanged === 1 ? "" : "s"} skipped.` : "", result.skippedNew ? `${result.skippedNew.toLocaleString()} new SKU${result.skippedNew === 1 ? "" : "s"} skipped.` : "", impact.skippedDiscontinued ? `${impact.skippedDiscontinued.toLocaleString()} discontinued/closeout row${impact.skippedDiscontinued === 1 ? "" : "s"} skipped.` : "", impact.limited ? `Only the first ${Number(impact.batchLimit || 25000).toLocaleString()} filtered matches were reviewed.` : "", analyzeResult.tables.length ? `Planner statistics refreshed for ${analyzeResult.tables.join(", ")}.` : "", analyzeResult.error ? `Planner statistics refresh skipped: ${analyzeResult.error}` : ""].filter(Boolean).join(" "),
    totalRows: result.requested,
    processedRows: result.requested,
    changed: result.changed,
    missingCount: 0,
    progressPercent: 100,
    estimatedSecondsRemaining: 0,
    phase: "complete"
  });
  await postgres.upsertOperationJob(job);
  queueDataQualityScanIfEnabled("source catalog import").catch(() => {});
  publicStateJsonCache = null;
  return job;
}

function startSourceCatalogImportJob(jobId, body = {}) {
  setTimeout(async () => {
    try {
      const runningDb = normalizeDb(await readDbFast({ skipInventory: true }));
      const job = findImportJob(runningDb, jobId);
      if (!job) return;
      job.status = "running";
      job.startedAt = job.startedAt || new Date().toISOString();
      job.updatedAt = new Date().toISOString();
      job.message = "Importing source catalog products...";
      upsertImportJobStore(job);
      let lastProgressPersistedAt = 0;
      const progress = (patch = {}) => {
        const next = setActiveJobProgress(jobId, {
          ...patch,
          status: "running",
          startedAt: job.startedAt
        });
        Object.assign(job, {
          processedRows: next.processedRows,
          totalRows: next.totalRows,
          progressPercent: next.progressPercent,
          estimatedSecondsRemaining: next.estimatedSecondsRemaining,
          phase: next.phase,
          lastProgressAt: next.lastProgressAt,
          message: next.message || job.message
        });
        activeJobRecords.set(jobId, normalizeImportJob(job));
        if (Date.now() - lastProgressPersistedAt > 1000 || Number(next.progressPercent || 0) >= 100) {
          lastProgressPersistedAt = Date.now();
          upsertImportJobStore(job);
        }
      };
      const isCanceled = () => !["queued", "running"].includes(String(activeJobProgress.get(jobId)?.status || job.status || "").toLowerCase());
      progress({ phase: "collecting_source_rows", processedRows: 0, totalRows: Number(job.totalRows || 0), message: "Collecting source catalog rows..." });
      const impact = await sourceCatalogImportImpact({
        skus: Array.isArray(body.skus) ? body.skus : [],
        allFiltered: body.allFiltered === true || String(body.allFiltered || "").toLowerCase() === "true",
        query: body.query || "",
        filters: body.filters || {},
        limit: body.limit || 25000,
        importMode: body.importMode || body.sourceImportMode || "",
        db: runningDb
      });
      progress({ phase: "source_rows_ready", processedRows: 0, totalRows: impact.importable, message: `${impact.importable.toLocaleString()} source rows ready to import.` });
      const result = await promoteSourceCatalogRows({ sourceRows: impact.sourceRows || [], skus: impact.skus || [], progress, isCanceled });
      let analyzeResult = { tables: [] };
      try {
        analyzeResult = await postgres.analyzeCatalogTables({ products: true });
      } catch (error) {
        analyzeResult = { tables: [], error: error.message || "Planner statistics refresh failed." };
      }
      const status = impact.limited || impact.skippedNew || result.skippedNew || impact.skippedDiscontinued ? "warning" : "success";
      const message = `Reviewed ${result.requested.toLocaleString()} source product${result.requested === 1 ? "" : "s"}; imported ${result.changed.toLocaleString()} changed (${result.created.toLocaleString()} new, ${result.updated.toLocaleString()} updated).`;
      finishImportJob(job, {
        status,
        message,
        details: [job.details, result.skippedUnchanged ? `${result.skippedUnchanged.toLocaleString()} unchanged row${result.skippedUnchanged === 1 ? "" : "s"} skipped.` : "", result.skippedNew ? `${result.skippedNew.toLocaleString()} new SKU${result.skippedNew === 1 ? "" : "s"} skipped.` : "", impact.skippedDiscontinued ? `${impact.skippedDiscontinued.toLocaleString()} discontinued/closeout row${impact.skippedDiscontinued === 1 ? "" : "s"} skipped.` : "", impact.limited ? `Only the first ${Number(impact.batchLimit || 25000).toLocaleString()} filtered matches were reviewed.` : "", analyzeResult.tables.length ? `Planner statistics refreshed for ${analyzeResult.tables.join(", ")}.` : "", analyzeResult.error ? `Planner statistics refresh skipped: ${analyzeResult.error}` : ""].filter(Boolean).join(" "),
        totalRows: result.requested,
        processedRows: result.requested,
        changed: result.changed,
        missingCount: 0,
        progressPercent: 100,
        estimatedSecondsRemaining: 0,
        phase: "complete"
      });
      queueDataQualityScanIfEnabled("source catalog import").catch(() => {});
      activeJobProgress.delete(jobId);
      activeJobRecords.delete(jobId);
      upsertImportJobStore(job);
    } catch (error) {
      const failedDb = normalizeDb(await readDbFast({ skipInventory: true }));
      const job = findImportJob(failedDb, jobId) || normalizeImportJob({ id: jobId, operation: "Source catalog import" });
      const wasCanceled = /canceled|cancelled|stopped/i.test(String(error.message || ""));
      finishImportJob(job, {
        status: wasCanceled ? "stopped" : "failed",
        message: wasCanceled ? "Source catalog import was canceled." : error.message || "Source catalog import failed.",
        errors: wasCanceled ? [] : [error.message || "Source catalog import failed."],
        missingCount: wasCanceled ? 0 : 1,
        phase: wasCanceled ? "stopped" : "failed",
        estimatedSecondsRemaining: 0
      });
      activeJobProgress.delete(jobId);
      activeJobRecords.delete(jobId);
      upsertImportJobStore(job);
    }
  }, 10);
}

async function scanCatalogFacets() {
  const sourceCatalogIndexSupplierNames = () => {
    const sourceIndex = readSourceCatalogIndexManifest();
    const vendorIndex = readCatalogVendorIndex();
    return [
      ...(sourceIndex?.suppliers || []),
      ...(vendorIndex?.vendors || []),
      ...(vendorIndex?.suppliers || [])
    ]
      .map((supplier) => typeof supplier === "string" ? supplier : supplier?.name)
      .filter(Boolean);
  };
  if (postgres.isPostgresEnabled()) {
    try {
      const facets = await postgres.vendorCatalogFacets();
      if (facets) {
        const sortValues = (values = [], limit = 500) => [...new Set(values.filter(Boolean))].sort((a, b) => String(a).localeCompare(String(b))).slice(0, limit);
        const suppliers = sortValues([
          ...(facets.suppliers || []),
          ...sourceCatalogIndexSupplierNames()
        ].map((value) => canonicalCatalogSupplierName(value)), 50000);
        const stockStatuses = sortValues(facets.stockStatuses);
        const brands = sortValues((facets.brands || []).map(formatBrandName));
        const categories = sortValues((facets.categories || []).map(formatCategoryName));
        return {
          suppliers,
          stockStatuses,
          brands,
          categories,
          scanned: Number(facets.total || 0),
          manifest: { ...(readCatalogManifest() || {}), productCount: Number(facets.total || 0), source: "postgres:vendor_catalog_items" },
          vendorIndex: { generatedAt: new Date().toISOString(), vendors: suppliers.map((name) => ({ name })) },
          database: "postgres"
        };
      }
    } catch (error) {
      console.warn("Postgres source catalog facets failed, falling back to catalog file:", error.message);
    }
  }
  const mtime = fs.existsSync(CATALOG_FILE) ? fs.statSync(CATALOG_FILE).mtimeMs : 0;
  const vendorIndex = readCatalogVendorIndex();
  if (catalogFacetCache && catalogFacetCache.mtime === mtime && catalogFacetCache.vendorIndexGeneratedAt === vendorIndex?.generatedAt) return catalogFacetCache.data;
  const result = {
    suppliers: new Set((vendorIndex?.vendors || vendorIndex?.suppliers || []).map((vendor) => typeof vendor === "string" ? vendor : vendor.name).filter(Boolean)),
    stockStatuses: new Set(),
    brands: new Set(),
    categories: new Set(),
    scanned: 0,
    manifest: readCatalogManifest(),
    vendorIndex
  };
  if (!fs.existsSync(CATALOG_FILE)) {
    return { suppliers: [...result.suppliers].sort((a, b) => a.localeCompare(b)), stockStatuses: [], brands: [], categories: [], scanned: 0, manifest: result.manifest, vendorIndex };
  }
  const maxRows = 50000;
  const rl = readline.createInterface({
    input: fs.createReadStream(CATALOG_FILE, { encoding: "utf8" }),
    crlfDelay: Infinity
  });
  for await (const line of rl) {
    if (!line.trim()) continue;
    let product;
    try {
      product = JSON.parse(line);
    } catch {
      continue;
    }
    result.scanned += 1;
    if (product.supplier || product.vendor) {
      result.suppliers.add(canonicalCatalogSupplierName(product.supplier || product.vendor, product.supplierCode));
    }
    if (product.stockStatus) result.stockStatuses.add(String(product.stockStatus));
    if (product.brand) result.brands.add(formatBrandName(product.brand));
    if (product.category) result.categories.add(formatCategoryName(product.category));
    if (result.scanned >= maxRows) {
      rl.close();
      break;
    }
  }
  const sortValues = (set, limit = 500) => [...set].sort((a, b) => a.localeCompare(b)).slice(0, limit);
  const sortCategories = (set, limit = 500) => {
    const byKey = new Map();
    for (const value of set) {
      const formatted = formatCategoryName(value);
      if (!formatted) continue;
      byKey.set(formatted.toLowerCase(), formatted);
    }
    return [...byKey.values()].sort((a, b) => a.localeCompare(b)).slice(0, limit);
  };
  const sortBrands = (set, limit = 500) => {
    const byKey = new Map();
    const brandLabelScore = (label) => {
      const value = String(label || "");
      let score = value === value.toLowerCase() ? 0 : 1;
      if (/[A-Z]{2,}/.test(value) || /\b\d+[A-Z]+\b/.test(value)) score += 1;
      if (/^([A-Z]\.){2,}[A-Z]?\.?/.test(value)) score += 1;
      return score;
    };
    for (const value of set) {
      const formatted = formatBrandName(value);
      if (!formatted) continue;
      const key = formatted.toLowerCase();
      const current = byKey.get(key);
      if (!current || brandLabelScore(formatted) > brandLabelScore(current)) byKey.set(key, formatted);
    }
    return [...byKey.values()].sort((a, b) => a.localeCompare(b)).slice(0, limit);
  };
  const data = {
    suppliers: sortValues([...result.suppliers].map((value) => canonicalCatalogSupplierName(value)), 10000),
    stockStatuses: sortValues(result.stockStatuses),
    brands: sortBrands(result.brands),
    categories: sortCategories(result.categories),
    scanned: result.scanned,
    manifest: result.manifest,
    vendorIndex: result.vendorIndex
  };
  catalogFacetCache = { mtime, vendorIndexGeneratedAt: vendorIndex?.generatedAt, data };
  return data;
}

function readCatalogChangeRows(limit = 500) {
  if (!fs.existsSync(CATALOG_CHANGE_LOG_FILE)) return [];
  const stat = fs.statSync(CATALOG_CHANGE_LOG_FILE);
  const readSize = Math.min(stat.size, 8 * 1024 * 1024);
  const fd = fs.openSync(CATALOG_CHANGE_LOG_FILE, "r");
  const buffer = Buffer.alloc(readSize);
  try {
    fs.readSync(fd, buffer, 0, readSize, stat.size - readSize);
  } finally {
    fs.closeSync(fd);
  }
  return buffer.toString("utf8")
    .split(/\r?\n/)
    .filter(Boolean)
    .slice(-Math.max(1, Number(limit || 500)))
    .map((line) => {
      try {
        return JSON.parse(line);
      } catch {
        return null;
      }
    })
    .filter(Boolean)
    .reverse();
}

function catalogChangeSummary(rows = []) {
  const summary = {
    total: rows.length,
    costChanges: 0,
    stockChanges: 0,
    closeouts: 0,
    up: 0,
    down: 0
  };
  for (const row of rows) {
    if (["sourceCost", "fobPrice", "websitePrice", "listPrice"].includes(row.field)) summary.costChanges += 1;
    if (["stockQty", "stockStatus"].includes(row.field)) summary.stockChanges += 1;
    if (row.toBeDiscontinued || row.field === "toBeDiscontinued") summary.closeouts += 1;
    if (row.direction === "up") summary.up += 1;
    if (row.direction === "down") summary.down += 1;
  }
  return summary;
}

function catalogChangeTrackingStatus() {
  const manifest = readCatalogManifest() || {};
  return {
    manifest,
    snapshotExists: fs.existsSync(CATALOG_CHANGE_SNAPSHOT_FILE),
    snapshotPath: CATALOG_CHANGE_SNAPSHOT_FILE,
    changeLogExists: fs.existsSync(CATALOG_CHANGE_LOG_FILE),
    changeLogPath: CATALOG_CHANGE_LOG_FILE,
    closeoutExists: fs.existsSync(CATALOG_CLOSEOUT_FILE),
    closeoutPath: CATALOG_CLOSEOUT_FILE,
    changeTracking: manifest.changeTracking || null
  };
}

function readShopifyRuntimeCredentials() {
  try {
    const stats = fs.statSync(SHOPIFY_RUNTIME_CREDENTIALS_FILE);
    if (shopifyRuntimeCredentialsCache.mtimeMs === stats.mtimeMs) return shopifyRuntimeCredentialsCache.value;
    const parsed = JSON.parse(fs.readFileSync(SHOPIFY_RUNTIME_CREDENTIALS_FILE, "utf8"));
    shopifyRuntimeCredentialsCache = { mtimeMs: stats.mtimeMs, value: parsed && typeof parsed === "object" ? parsed : {} };
  } catch {
    shopifyRuntimeCredentialsCache = { mtimeMs: 0, value: {} };
  }
  return shopifyRuntimeCredentialsCache.value;
}

function writeShopifyRuntimeCredentials(patch = {}) {
  const current = readShopifyRuntimeCredentials();
  const next = { ...current, ...patch, updatedAt: new Date().toISOString() };
  fs.mkdirSync(path.dirname(SHOPIFY_RUNTIME_CREDENTIALS_FILE), { recursive: true });
  const temporary = `${SHOPIFY_RUNTIME_CREDENTIALS_FILE}.${process.pid}.tmp`;
  fs.writeFileSync(temporary, `${JSON.stringify(next, null, 2)}\n`, { mode: 0o600 });
  fs.renameSync(temporary, SHOPIFY_RUNTIME_CREDENTIALS_FILE);
  shopifyRuntimeCredentialsCache = { mtimeMs: 0, value: next };
  return next;
}

function readEbayRuntimeCredentials() {
  try {
    const stats = fs.statSync(EBAY_RUNTIME_CREDENTIALS_FILE);
    if (ebayRuntimeCredentialsCache.mtimeMs === stats.mtimeMs) return ebayRuntimeCredentialsCache.value;
    const parsed = JSON.parse(fs.readFileSync(EBAY_RUNTIME_CREDENTIALS_FILE, "utf8"));
    ebayRuntimeCredentialsCache = { mtimeMs: stats.mtimeMs, value: parsed && typeof parsed === "object" ? parsed : {} };
  } catch {
    ebayRuntimeCredentialsCache = { mtimeMs: 0, value: {} };
  }
  return ebayRuntimeCredentialsCache.value;
}

function writeEbayRuntimeCredentials(patch = {}) {
  const current = readEbayRuntimeCredentials();
  const next = { ...current, ...patch, updatedAt: new Date().toISOString() };
  fs.mkdirSync(path.dirname(EBAY_RUNTIME_CREDENTIALS_FILE), { recursive: true });
  const temporary = `${EBAY_RUNTIME_CREDENTIALS_FILE}.${process.pid}.tmp`;
  fs.writeFileSync(temporary, `${JSON.stringify(next, null, 2)}\n`, { mode: 0o600 });
  fs.renameSync(temporary, EBAY_RUNTIME_CREDENTIALS_FILE);
  ebayRuntimeCredentialsCache = { mtimeMs: 0, value: next };
  return next;
}

function credentialPreview(value) {
  const normalized = String(value || "").trim();
  if (!normalized) return "";
  if (normalized.length <= 8) return `${normalized.slice(0, 2)}${"*".repeat(Math.max(2, normalized.length - 2))}`;
  return `${normalized.slice(0, 4)}${"*".repeat(Math.min(12, Math.max(6, normalized.length - 8)))}${normalized.slice(-4)}`;
}

function publicEbayConfigStatus(db = {}) {
  const config = getEbayConfig(db);
  const runtime = readEbayRuntimeCredentials();
  const connectorState = mergedConnectorState(db);
  const channelSettings = ebayChannelSettings(Object.keys(db || {}).length ? db : (dbCache.data || {}));
  return {
    environment: config.environment,
    ruName: config.ruName,
    scope: config.scope,
    hasClientCredentials: Boolean(config.clientId && config.clientSecret),
    hasSellerAuthorization: Boolean(config.refreshToken || config.accessToken),
    hasAccessToken: Boolean(config.accessToken),
    sellerAuthorizedAt: connectorState.ebayAuthorizedAt || connectorState.ebayTokenCreatedAt || "",
    accessTokenExpiresAt: config.accessTokenExpiresAt || "",
    connectionVerifiedAt: connectorState.ebayConnectionVerifiedAt || "",
    connectionVerificationMessage: connectorState.ebayConnectionVerificationMessage || "",
    webhookEnabled: Boolean(channelSettings.ebayWebhookEnabled),
    webhookEndpoint: ebayWebhookEndpoint(channelSettings),
    webhookVerificationTokenConfigured: Boolean(channelSettings.ebayWebhookVerificationToken),
    webhookLastReceivedAt: connectorState.ebayWebhookLastReceivedAt || "",
    webhookLastTopic: connectorState.ebayWebhookLastTopic || "",
    webhookLastSignatureVerifiedAt: connectorState.ebayWebhookLastSignatureVerifiedAt || "",
    webhookVerificationAt: connectorState.ebayWebhookVerificationAt || "",
    webhookVerificationMessage: connectorState.ebayWebhookVerificationMessage || "",
    clientIdPreview: credentialPreview(config.clientId),
    clientSecretPreview: credentialPreview(config.clientSecret),
    refreshTokenPreview: credentialPreview(config.refreshToken),
    accessTokenPreview: credentialPreview(config.accessToken),
    runtimeManaged: Boolean(Object.keys(runtime).length),
    configured: Boolean(config.clientId && config.clientSecret && config.ruName),
  };
}

function publicEbayHealthStatus(db = {}) {
  const channel = findChannelByName(db, "eBay");
  const settings = channel?.settings || DEFAULT_CHANNEL_SETTINGS;
  const accountHealth = settings.ebayAccountHealth && typeof settings.ebayAccountHealth === "object" ? settings.ebayAccountHealth : {};
  const credentials = publicEbayConfigStatus(db);
  const hasDefaults = Boolean(settings.ebayMerchantLocationKey && settings.ebayPaymentPolicyId && settings.ebayReturnPolicyId && settings.ebayFulfillmentPolicyId);
  return {
    channel: {
      id: channel?.id || "",
      connected: Boolean(channel?.connected),
      enabled: channel?.enabled !== false,
      lastSync: channel?.lastSync || ""
    },
    credentials,
    account: {
      status: accountHealth.status || (hasDefaults ? "ready" : "needs_attention"),
      lastSyncedAt: settings.ebayAccountSettingsSyncedAt || accountHealth.updatedAt || "",
      merchantLocations: Array.isArray(settings.ebayMerchantLocations) ? settings.ebayMerchantLocations.length : 0,
      paymentPolicies: Array.isArray(settings.ebayPaymentPolicies) ? settings.ebayPaymentPolicies.length : 0,
      returnPolicies: Array.isArray(settings.ebayReturnPolicies) ? settings.ebayReturnPolicies.length : 0,
      fulfillmentPolicies: Array.isArray(settings.ebayFulfillmentPolicies) ? settings.ebayFulfillmentPolicies.length : 0,
      failures: Array.isArray(accountHealth.failures) ? accountHealth.failures : []
    },
    workflows: {
      inventoryUpdateEnabled: settings.ebayInventoryUpdateEnabled !== false,
      priceUpdateEnabled: settings.ebayPriceUpdateEnabled !== false,
      trackingUploadEnabled: settings.ebayTrackingUploadEnabled !== false,
      settlementImportEnabled: settings.ebaySettlementImportEnabled === true,
      autoRelistEnabled: settings.ebayAutoRelistEnabled === true,
      webhookEnabled: settings.ebayWebhookEnabled === true,
      webhookEndpoint: ebayWebhookEndpoint(settings)
    },
    defaultsReady: hasDefaults
  };
}

function shopifyAdminConfig() {
  const runtime = readShopifyRuntimeCredentials();
  const shop = String(runtime.storeDomain || process.env.SHOPIFY_STORE_DOMAIN || process.env.SHOPIFY_SHOP_DOMAIN || process.env.SHOPIFY_STORE || "").trim().replace(/^https?:\/\//i, "").replace(/\/+$/g, "");
  const accessToken = String(runtime.accessToken || process.env.SHOPIFY_ADMIN_ACCESS_TOKEN || process.env.SHOPIFY_ACCESS_TOKEN || "").trim();
  const clientId = String(runtime.clientId || process.env.SHOPIFY_CLIENT_ID || process.env.SHOPIFY_APP_CLIENT_ID || "").trim();
  const clientSecret = String(runtime.clientSecret || process.env.SHOPIFY_CLIENT_SECRET || process.env.SHOPIFY_APP_CLIENT_SECRET || "").trim();
  const apiVersion = String(runtime.apiVersion || process.env.SHOPIFY_ADMIN_API_VERSION || "2026-04").trim();
  return { shop, accessToken, clientId, clientSecret, apiVersion };
}

function publicShopifyConfigStatus() {
  const config = shopifyAdminConfig();
  const runtime = readShopifyRuntimeCredentials();
  return {
    shop: config.shop,
    apiVersion: config.apiVersion,
    hasAccessToken: Boolean(config.accessToken),
    hasClientCredentials: Boolean(config.clientId && config.clientSecret),
    clientIdPreview: credentialPreview(config.clientId),
    clientSecretPreview: credentialPreview(config.clientSecret),
    accessTokenPreview: credentialPreview(config.accessToken),
    runtimeManaged: Boolean(Object.keys(runtime).length),
    configured: Boolean(config.shop && (config.accessToken || (config.clientId && config.clientSecret)))
  };
}

function configuredShopifyAppUrl() {
  return String(process.env.SHOPIFY_APP_URL || process.env.APPLICATION_URL || "").trim();
}

function configuredPublicAppUrl(req = null) {
  const configured = String(process.env.APPLICATION_URL || process.env.SHOPIFY_APP_URL || "").trim().replace(/\/+$/, "");
  if (/^https:\/\//i.test(configured)) return configured;
  const host = String(req?.headers?.host || "").trim();
  if (!host) return "";
  const forwardedProto = String(req?.headers?.["x-forwarded-proto"] || "").split(",")[0].trim();
  const protocol = forwardedProto || (req?.socket?.encrypted ? "https" : "http");
  return `${protocol}://${host}`;
}

function ebayWebhookEndpoint(settings = {}, req = null) {
  const configured = String(settings?.ebayWebhookEndpoint || "").trim().replace(/\/+$/, "");
  if (configured) return configured;
  const publicUrl = configuredPublicAppUrl(req);
  return publicUrl ? `${publicUrl}/api/webhooks/ebay` : "";
}

function ebayWebhookTokenIsValid(value = "") {
  return /^[A-Za-z0-9_-]{32,80}$/.test(String(value || "").trim());
}

function ebayWebhookState(db = {}, patch = {}) {
  const next = {
    ...readConnectorStateSync(),
    ...(db.connectorState || {}),
    ...patch
  };
  db.connectorState = next;
  writeConnectorStateSync(next);
  return next;
}

function ebayWebhookPublicKey(value = "") {
  const key = String(value || "").trim().replace(/\\n/g, "\n");
  if (!key) return "";
  if (/-----BEGIN PUBLIC KEY-----/.test(key)) return key;
  return `-----BEGIN PUBLIC KEY-----\n${key.replace(/\s+/g, "")}\n-----END PUBLIC KEY-----`;
}

const EBAY_WEBHOOK_PUBLIC_KEY_CACHE_TTL_MS = 60 * 60 * 1000;
const ebayWebhookPublicKeyCache = new Map();

async function getEbayWebhookPublicKey(db, keyId) {
  const cacheKey = String(keyId || "").trim();
  const cached = ebayWebhookPublicKeyCache.get(cacheKey);
  if (cached && cached.expiresAt > Date.now()) return cached.publicKey;
  const keyPayload = await ebayRequest(db, `/commerce/notification/v1/public_key/${encodeURIComponent(cacheKey)}`, {
    tokenType: "app",
    operation: "Verify eBay webhook signature",
    timeoutMs: 15000
  });
  const publicKey = ebayWebhookPublicKey(keyPayload?.key || keyPayload?.publicKey || keyPayload?.public_key || "");
  if (!publicKey) throw new Error("eBay returned no usable public key for this webhook signature.");
  ebayWebhookPublicKeyCache.set(cacheKey, { publicKey, expiresAt: Date.now() + EBAY_WEBHOOK_PUBLIC_KEY_CACHE_TTL_MS });
  return publicKey;
}

async function verifyEbayWebhookSignature(db, payload, signatureHeader = "") {
  const header = String(signatureHeader || "").trim();
  if (!header) return { valid: false, reason: "Missing X-EBAY-SIGNATURE header." };
  let signatureEnvelope;
  try {
    signatureEnvelope = JSON.parse(Buffer.from(header, "base64").toString("utf8"));
  } catch {
    return { valid: false, reason: "The X-EBAY-SIGNATURE header is not a valid eBay signature envelope." };
  }
  const keyId = String(signatureEnvelope.kid || signatureEnvelope.keyId || "").trim();
  const signature = String(signatureEnvelope.signature || "").trim();
  if (!keyId || !signature) return { valid: false, reason: "The eBay signature envelope is missing its key ID or signature." };
  try {
    const publicKey = await getEbayWebhookPublicKey(db, keyId);
    const verifier = crypto.createVerify("SHA256");
    // eBay's official Node SDK verifies the canonical JSON payload, not the
    // original transport bytes (which may contain harmless whitespace).
    verifier.update(JSON.stringify(payload));
    verifier.end();
    const valid = verifier.verify(publicKey, Buffer.from(signature, "base64"));
    return valid ? { valid: true, keyId } : { valid: false, reason: "eBay webhook signature verification failed." };
  } catch (error) {
    return { valid: false, reason: `eBay webhook signature verification could not run: ${error.message}` };
  }
}

async function verifyEbayWebhookSetup(db, req = null) {
  const settings = ebayChannelSettings(db);
  const endpoint = ebayWebhookEndpoint(settings, req);
  const verificationToken = String(settings.ebayWebhookVerificationToken || "").trim();
  if (!/^https:\/\//i.test(endpoint)) throw new Error("Set a public HTTPS eBay webhook endpoint before verifying notification setup.");
  if (!ebayWebhookTokenIsValid(verificationToken)) throw new Error("Set a webhook verification token with 32-80 letters, numbers, underscores, or hyphens before verifying notification setup.");
  const topics = await ebayRequest(db, "/commerce/notification/v1/topic", {
    tokenType: "app",
    operation: "Verify eBay Notification API",
    timeoutMs: 15000
  });
  const verifiedAt = new Date().toISOString();
  ebayWebhookState(db, {
    ebayWebhookVerificationAt: verifiedAt,
    ebayWebhookVerificationMessage: "eBay Notification API credentials verified. Configure a destination and topic subscriptions in eBay using this endpoint."
  });
  return {
    verified: true,
    verifiedAt,
    endpoint,
    topicCount: Array.isArray(topics?.topics) ? topics.topics.length : 0,
    message: "eBay Notification API credentials verified. The endpoint is ready for eBay's challenge request and signed event deliveries."
  };
}

function ebayNotificationArray(payload = {}, key = "") {
  if (Array.isArray(payload)) return payload;
  if (key && Array.isArray(payload?.[key])) return payload[key];
  for (const candidate of ["topics", "destinations", "subscriptions", "items", "data"]) {
    if (Array.isArray(payload?.[candidate])) return payload[candidate];
  }
  return [];
}

function ebayNotificationTopicId(topic = {}) {
  return String(topic.topicId || topic.id || topic.name || "").trim();
}

function ebayNotificationDestinationId(destination = {}) {
  return String(destination.destinationId || destination.id || "").trim();
}

function ebayNotificationSubscriptionId(subscription = {}) {
  return String(subscription.subscriptionId || subscription.id || "").trim();
}

function ebayNotificationPayload(topic = {}) {
  const supported = Array.isArray(topic.supportedPayloads) ? topic.supportedPayloads : [];
  const preferred = supported.find((item) => String(item.deliveryProtocol || "").toUpperCase() === "HTTPS" && String(item.format || "").toUpperCase() === "JSON") || supported[0] || {};
  return {
    deliveryProtocol: preferred.deliveryProtocol || "HTTPS",
    format: preferred.format || "JSON",
    ...(preferred.schemaVersion ? { schemaVersion: preferred.schemaVersion } : {})
  };
}

function isEbayNotificationConfigurationError(error) {
  const status = Number(error?.status || error?.statusCode || 0);
  const message = String(error?.message || error || "");
  return (status === 409 && /195003|configurations required for notifications/i.test(message))
    || (status === 404 && /195026|configuration not found/i.test(message));
}

function ebayNotificationConfigurationMessage() {
  return "eBay Notification API configuration is required. Add an alert email in the eBay channel settings, save it, then sync the selected topics.";
}

async function fetchEbayNotificationStatus(db) {
  const [topics, destinations] = await Promise.all([
    ebayRequest(db, "/commerce/notification/v1/topic", { tokenType: "app", operation: "Load eBay notification topics", timeoutMs: 15000 }),
    ebayRequest(db, "/commerce/notification/v1/destination", { tokenType: "app", operation: "Load eBay webhook destinations", timeoutMs: 15000 })
  ]);
  let notificationConfig = null;
  let notificationConfigRequired = false;
  let notificationConfigError = "";
  try {
    notificationConfig = await ebayRequest(db, "/commerce/notification/v1/config", { tokenType: "app", operation: "Load eBay notification configuration", timeoutMs: 15000 });
  } catch (error) {
    if (!isEbayNotificationConfigurationError(error)) throw error;
    notificationConfigRequired = true;
    notificationConfigError = ebayNotificationConfigurationMessage();
  }
  let subscriptions = { subscriptions: [] };
  try {
    subscriptions = await ebayRequest(db, "/commerce/notification/v1/subscription", { tokenType: "app", operation: "Load eBay webhook subscriptions", timeoutMs: 15000 });
  } catch (error) {
    if (!isEbayNotificationConfigurationError(error)) throw error;
    notificationConfigRequired = true;
    notificationConfigError = ebayNotificationConfigurationMessage();
  }
  const topicRows = ebayNotificationArray(topics, "topics").map((topic) => ({
    ...topic,
    topicId: ebayNotificationTopicId(topic),
    payloads: Array.isArray(topic.supportedPayloads) ? topic.supportedPayloads : []
  })).filter((topic) => topic.topicId);
  const destinationRows = ebayNotificationArray(destinations, "destinations").map((destination) => ({
    ...destination,
    destinationId: ebayNotificationDestinationId(destination)
  })).filter((destination) => destination.destinationId);
  const subscriptionRows = ebayNotificationArray(subscriptions, "subscriptions").map((subscription) => ({
    ...subscription,
    subscriptionId: ebayNotificationSubscriptionId(subscription)
  })).filter((subscription) => subscription.subscriptionId);
  return { topics: topicRows, destinations: destinationRows, subscriptions: subscriptionRows, notificationConfig, notificationConfigRequired, notificationConfigError };
}

function ebayWebhookTopicDefaults(topics = []) {
  const preferred = ["ORDER_CONFIRMATION", "ORDER_CANCELLATION", "ORDER_UPDATE", "FULFILLMENT"];
  return topics.filter((topic) => {
    const id = ebayNotificationTopicId(topic).toUpperCase();
    return preferred.some((candidate) => id.includes(candidate));
  }).map(ebayNotificationTopicId);
}

async function syncEbayWebhookSubscriptions(db, req = null, requestedTopicIds = null) {
  const settings = ebayChannelSettings(db);
  if (settings.ebayWebhookEnabled !== true) {
    throw new Error("Enable signed eBay webhook processing and save the eBay channel settings before syncing notification subscriptions.");
  }
  const endpoint = ebayWebhookEndpoint(settings, req);
  const verificationToken = String(settings.ebayWebhookVerificationToken || "").trim();
  if (!/^https:\/\//i.test(endpoint)) throw new Error("Set a public HTTPS eBay webhook endpoint before syncing notification subscriptions.");
  if (!ebayWebhookTokenIsValid(verificationToken)) throw new Error("Set a webhook verification token with 32-80 letters, numbers, underscores, or hyphens before syncing notification subscriptions.");

  const current = await fetchEbayNotificationStatus(db);
  const requested = Array.isArray(requestedTopicIds)
    ? requestedTopicIds.map((value) => String(value || "").trim()).filter(Boolean)
    : null;
  const topicIds = requested !== null ? requested : ebayWebhookTopicDefaults(current.topics);
  if (!topicIds.length) {
    const verifiedAt = new Date().toISOString();
    ebayWebhookState(db, {
      ebayWebhookVerificationAt: verifiedAt,
      ebayWebhookDestinationId: "",
      ebayWebhookSubscriptionIds: [],
      ebayWebhookTopicIds: [],
      ebayWebhookVerificationMessage: "eBay notification subscriptions are disabled because no topics are selected."
    });
    return { ...current, destinationId: "", selectedTopicIds: [], syncedAt: verifiedAt };
  }
  if (current.notificationConfigRequired) {
    const alertEmail = String(settings.ebayNotificationAlertEmail || "").trim().toLowerCase();
    if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(alertEmail)) {
      throw new Error(`${ebayNotificationConfigurationMessage()} A valid email address is required.`);
    }
    current.notificationConfig = await ebayRequest(db, "/commerce/notification/v1/config", {
      method: "PUT",
      body: { alertEmail },
      tokenType: "app",
      operation: "Configure eBay Notification API alerts"
    });
    current.notificationConfigRequired = false;
    current.notificationConfigError = "";
  }
  const name = "DataPlus";
  let destination = current.destinations.find((row) => String(row.name || "").trim().toLowerCase() === name.toLowerCase());
  const destinationBody = {
    name,
    status: topicIds.length ? "ENABLED" : "DISABLED",
    deliveryConfig: { endpoint, verificationToken }
  };
  if (!destination) {
    destination = {
      ...await ebayRequest(db, "/commerce/notification/v1/destination", {
        method: "POST",
        body: destinationBody,
        tokenType: "app",
        operation: "Create eBay webhook destination"
      }),
      ...destinationBody
    };
  } else {
    const destinationId = ebayNotificationDestinationId(destination);
    const updated = await ebayRequest(db, `/commerce/notification/v1/destination/${encodeURIComponent(destinationId)}`, {
      method: "PUT",
      body: destinationBody,
      tokenType: "app",
      operation: "Update eBay webhook destination"
    });
    destination = { ...destination, ...updated, ...destinationBody, destinationId };
  }
  const destinationId = ebayNotificationDestinationId(destination);
  if (!destinationId) throw new Error("eBay did not return a destination ID after creating the DataPlus webhook destination.");

  const subscriptions = [];
  for (const topicId of topicIds) {
    const topic = current.topics.find((row) => ebayNotificationTopicId(row) === topicId);
    if (!topic) continue;
    const payload = ebayNotificationPayload(topic);
    const body = { destinationId, topicId, status: "ENABLED", payload };
    const existing = current.subscriptions.find((row) => ebayNotificationTopicId(row) === topicId && String(row.destinationId || "") === destinationId);
    if (existing && ebayNotificationSubscriptionId(existing)) {
      const subscriptionId = ebayNotificationSubscriptionId(existing);
      const updated = await ebayRequest(db, `/commerce/notification/v1/subscription/${encodeURIComponent(subscriptionId)}`, {
        method: "PUT",
        body,
        tokenType: "app",
        operation: `Enable eBay webhook subscription ${topicId}`
      });
      subscriptions.push({ ...existing, ...updated, ...body, subscriptionId });
    } else {
      const created = await ebayRequest(db, "/commerce/notification/v1/subscription", {
        method: "POST",
        body,
        tokenType: "app",
        operation: `Create eBay webhook subscription ${topicId}`
      });
      subscriptions.push({ ...created, ...body, subscriptionId: ebayNotificationSubscriptionId(created) });
    }
  }
  // Keep eBay's enabled subscriptions aligned with the user's selection. This
  // prevents a topic that was unchecked in DataPlus from continuing to deliver
  // events in the background.
  for (const existing of current.subscriptions) {
    const existingDestinationId = String(existing.destinationId || "");
    const existingTopicId = ebayNotificationTopicId(existing);
    const subscriptionId = ebayNotificationSubscriptionId(existing);
    if (existingDestinationId !== destinationId || !subscriptionId || topicIds.includes(existingTopicId)) continue;
    await ebayRequest(db, `/commerce/notification/v1/subscription/${encodeURIComponent(subscriptionId)}/disable`, {
      method: "POST",
      body: {},
      tokenType: "app",
      operation: `Disable eBay webhook subscription ${existingTopicId || subscriptionId}`
    });
  }
  const verifiedAt = new Date().toISOString();
  ebayWebhookState(db, {
    ebayWebhookVerificationAt: verifiedAt,
    ebayWebhookDestinationId: destinationId,
    ebayWebhookSubscriptionIds: subscriptions.map(ebayNotificationSubscriptionId).filter(Boolean),
    ebayWebhookTopicIds: topicIds,
    ebayWebhookVerificationMessage: `DataPlus destination is enabled with ${subscriptions.length} eBay notification subscription${subscriptions.length === 1 ? "" : "s"}.`
  });
  return { ...await fetchEbayNotificationStatus(db), destinationId, selectedTopicIds: topicIds, syncedAt: verifiedAt };
}

async function testEbayWebhookSubscription(db, subscriptionId) {
  const id = String(subscriptionId || "").trim();
  if (!id) throw new Error("A subscription ID is required to send an eBay webhook test.");
  return ebayRequest(db, `/commerce/notification/v1/subscription/${encodeURIComponent(id)}/test`, {
    method: "POST",
    body: {},
    tokenType: "app",
    operation: `Test eBay webhook subscription ${id}`
  });
}

function sanitizeApiLogMessage(value = "") {
  return String(value || "")
    .replace(/shpat_[A-Za-z0-9_\-]+/g, "[token]")
    .replace(/shp[a-z]{2,}_[A-Za-z0-9_\-]+/g, "[secret]")
    .replace(/access_token["']?\s*:\s*["'][^"']+["']/gi, 'access_token:"[token]"')
    .slice(0, 1200);
}

function pruneFileChannelApiLogs(days = CHANNEL_API_LOG_RETENTION_DAYS) {
  if (!fs.existsSync(CHANNEL_API_LOG_FILE)) return 0;
  const cutoff = Date.now() - Math.max(1, Number(days || CHANNEL_API_LOG_RETENTION_DAYS)) * 24 * 60 * 60 * 1000;
  let removed = 0;
  const kept = [];
  for (const line of fs.readFileSync(CHANNEL_API_LOG_FILE, "utf8").split(/\r?\n/)) {
    if (!line.trim()) continue;
    try {
      const row = JSON.parse(line);
      const time = Date.parse(row.createdAt || "");
      if (Number.isFinite(time) && time < cutoff) {
        removed += 1;
        continue;
      }
    } catch {
      removed += 1;
      continue;
    }
    kept.push(line);
  }
  if (removed) fs.writeFileSync(CHANNEL_API_LOG_FILE, `${kept.join("\n")}${kept.length ? "\n" : ""}`, "utf8");
  return removed;
}

function pruneChannelApiLogsSoon(force = false) {
  const now = Date.now();
  if (!force && now - channelApiLogPruneLastRun < 60 * 60 * 1000) return;
  channelApiLogPruneLastRun = now;
  setTimeout(() => {
    try {
      pruneFileChannelApiLogs(CHANNEL_API_LOG_RETENTION_DAYS + 1);
    } catch {
      // API log retention must never block the app.
    }
    if (postgres.isPostgresEnabled()) {
      postgres.pruneChannelApiLogs(CHANNEL_API_LOG_RETENTION_DAYS + 1).catch(() => {
        // API log retention must never block the app.
      });
    }
  }, 250);
}

function appendChannelApiLog(entry = {}) {
  try {
    pruneChannelApiLogsSoon();
    fs.mkdirSync(path.dirname(CHANNEL_API_LOG_FILE), { recursive: true });
    const row = {
      id: entry.id || crypto.randomUUID(),
      createdAt: entry.createdAt || new Date().toISOString(),
      channel: entry.channel || "Shopify",
      kind: entry.kind || "api",
      actionGroup: entry.actionGroup || inferChannelActionGroup(`${entry.operation || ""} ${entry.path || ""}`),
      status: entry.status || (entry.ok ? "success" : "failed"),
      transport: entry.transport || "",
      method: entry.method || "",
      path: entry.path || "",
      operation: entry.operation || "",
      statusCode: entry.statusCode || 0,
      ok: Boolean(entry.ok),
      durationMs: Math.max(0, Number(entry.durationMs || 0)),
      requestId: entry.requestId || "",
      jobId: entry.jobId || "",
      entityType: entry.entityType || "",
      entityId: entry.entityId || "",
      actor: entry.actor || "",
      trigger: entry.trigger || "",
      phase: entry.phase || "",
      message: sanitizeApiLogMessage(entry.message || entry.error || "")
    };
    fs.appendFileSync(CHANNEL_API_LOG_FILE, `${JSON.stringify(row)}\n`);
    if (postgres.isPostgresEnabled()) {
      postgres.insertChannelApiLog(row).catch(() => {
        // API logging must never block the marketplace action.
      });
    }
  } catch {
    // API logging must never block the marketplace action.
  }
}

function channelLogMatches(row = {}, { channel = "", jobId = "", kind = "", actionGroup = "", status = "", query = "" } = {}) {
  const matches = (actual, expected) => !String(expected || "").trim()
    || String(actual || "").trim().toLowerCase() === String(expected || "").trim().toLowerCase();
  if (!matches(row.channel, channel) || !matches(row.jobId, jobId) || !matches(row.kind || "api", kind)) return false;
  if (!matches(row.actionGroup || inferChannelActionGroup(`${row.operation || ""} ${row.path || ""}`), actionGroup)) return false;
  if (!matches(row.status || (row.ok ? "success" : "failed"), status)) return false;
  const needle = String(query || "").trim().toLowerCase();
  if (!needle) return true;
  return [row.channel, row.operation, row.message, row.path, row.jobId, row.entityId, row.actor]
    .some((value) => String(value || "").toLowerCase().includes(needle));
}

function readFileChannelApiLogs({ channel = "", days = 365, limit = 1000, jobId = "", kind = "", actionGroup = "", status = "", query = "" } = {}) {
  if (!fs.existsSync(CHANNEL_API_LOG_FILE)) return [];
  const channelKey = String(channel || "").trim().toLowerCase();
  const jobKey = String(jobId || "").trim();
  const minTime = Date.now() - Math.max(1, Number(days || 365)) * 24 * 60 * 60 * 1000;
  const maxRows = Math.max(1, Math.min(1000, Number(limit || 250)));
  const rows = [];
  const lines = fs.readFileSync(CHANNEL_API_LOG_FILE, "utf8").split(/\r?\n/).filter(Boolean);
  for (let index = lines.length - 1; index >= 0 && rows.length < maxRows; index -= 1) {
    try {
      const row = JSON.parse(lines[index]);
      const time = Date.parse(row.createdAt || "");
      if (!Number.isFinite(time) || time < minTime) continue;
      if (!channelLogMatches(row, { channel: channelKey, jobId: jobKey, kind, actionGroup, status, query })) continue;
      rows.push(row);
    } catch {
      // Ignore malformed log lines.
    }
  }
  return rows;
}

async function readChannelApiLogs({ channel = "", days = 365, limit = 1000, jobId = "", kind = "", actionGroup = "", status = "", query = "" } = {}) {
  const fileRows = readFileChannelApiLogs({ channel, days, limit, jobId, kind, actionGroup, status, query });
  if (!postgres.isPostgresEnabled()) return fileRows;
  try {
    const pgRows = (await postgres.readChannelApiLogs({ channel, days, limit, jobId }))
      .filter((row) => channelLogMatches(row, { channel, jobId, kind, actionGroup, status, query }));
    const byKey = new Map();
    for (const row of [...pgRows, ...fileRows]) {
      const key = `${row.createdAt}|${row.channel}|${row.transport || ""}|${row.method}|${row.path}|${row.statusCode}|${row.ok}|${row.requestId || ""}|${row.jobId || ""}|${row.message}`;
      byKey.set(key, row);
    }
    return [...byKey.values()]
      .sort((a, b) => new Date(b.createdAt || 0) - new Date(a.createdAt || 0))
      .slice(0, Math.max(1, Math.min(1000, Number(limit || 250))));
  } catch {
    return fileRows;
  }
}

async function fetchShopifyShippingProfiles() {
  async function fetchPage(useMerchantFilter = true, cursor = null) {
    const args = useMerchantFilter ? "first: $first, after: $after, merchantOwnedOnly: true" : "first: $first, after: $after";
    return shopifyGraphqlRequestAuto(`
      query DeliveryProfiles($first: Int!, $after: String) {
        deliveryProfiles(${args}) {
          edges {
            cursor
            node {
              id
              name
              default
            }
          }
          pageInfo {
            hasNextPage
            endCursor
          }
        }
      }
    `, { first: 50, after: cursor }, { operation: "Fetch Shopify shipping profiles" });
  }
  const profiles = [];
  let after = null;
  let useMerchantFilter = true;
  do {
    let data;
    try {
      data = await fetchPage(useMerchantFilter, after);
    } catch (error) {
      if (!useMerchantFilter || after || !/merchantOwnedOnly|argument/i.test(error.message || "")) throw error;
      useMerchantFilter = false;
      data = await fetchPage(false, after);
    }
    const connection = data.deliveryProfiles || {};
    for (const edge of connection.edges || []) {
      const node = edge.node || {};
      const id = String(node.id || "").trim();
      const name = String(node.name || "").trim();
      if (!id && !name) continue;
      profiles.push({
        id,
        name: name || id,
        default: Boolean(node.default)
      });
    }
    after = connection.pageInfo?.hasNextPage ? connection.pageInfo.endCursor : null;
  } while (after);
  return normalizeShopifyShippingProfiles(profiles);
}

function shopifyGraphqlOperationName(query = "") {
  return String(query || "").match(/\b(query|mutation)\s+([A-Za-z0-9_]+)/)?.[2] || "GraphQL request";
}

function shopifyGraphqlRequest(query, variables = {}, options = {}) {
  const config = shopifyAdminConfig();
  if (!config.shop || !config.accessToken) {
    throw new Error("Shopify Admin API is not configured. Add SHOPIFY_STORE_DOMAIN and SHOPIFY_ADMIN_ACCESS_TOKEN to .env.");
  }
  return shopifyGraphqlRequestWithToken(query, variables, config.accessToken, options);
}

function shopifyGraphqlRequestWithToken(query, variables = {}, accessToken = "", options = {}) {
  const config = shopifyAdminConfig();
  if (!config.shop || !accessToken) {
    throw new Error("Shopify Admin API is not configured. Add SHOPIFY_STORE_DOMAIN and Shopify credentials to .env.");
  }
  const startedAt = Date.now();
  const requestPath = `/admin/api/${encodeURIComponent(config.apiVersion)}/graphql.json`;
  const operation = shopifyGraphqlOperationName(query);
  const payload = JSON.stringify({ query, variables });
  const requestOptions = {
    hostname: config.shop,
    path: requestPath,
    method: "POST",
    headers: {
      "Content-Type": "application/json",
      "Content-Length": Buffer.byteLength(payload),
      "X-Shopify-Access-Token": accessToken
    }
  };
  return new Promise((resolve, reject) => {
    const req = https.request(requestOptions, (response) => {
      const chunks = [];
      response.on("data", (chunk) => chunks.push(chunk));
      response.on("end", () => {
        const text = Buffer.concat(chunks).toString("utf8");
        let data;
        try {
          data = text ? JSON.parse(text) : {};
        } catch {
          appendChannelApiLog({ channel: "Shopify", transport: "GraphQL", method: "POST", path: requestPath, operation: options.operation || operation, statusCode: response.statusCode, ok: false, durationMs: Date.now() - startedAt, message: `Non-JSON response (${response.statusCode})`, requestId: response.headers["x-request-id"] || "", jobId: options.jobId || "" });
          return reject(new Error(`Shopify returned a non-JSON response (${response.statusCode}).`));
        }
        if (response.statusCode < 200 || response.statusCode >= 300) {
          appendChannelApiLog({ channel: "Shopify", transport: "GraphQL", method: "POST", path: requestPath, operation: options.operation || operation, statusCode: response.statusCode, ok: false, durationMs: Date.now() - startedAt, message: text, requestId: response.headers["x-request-id"] || "", jobId: options.jobId || "" });
          const error = new Error(`Shopify API error (${response.statusCode}): ${text}`);
          error.statusCode = response.statusCode;
          error.retryAfter = Number(response.headers["retry-after"] || 0) || 0;
          return reject(error);
        }
        if (Array.isArray(data.errors) && data.errors.length) {
          const message = data.errors.map((error) => error.message || JSON.stringify(error)).join("; ");
          appendChannelApiLog({ channel: "Shopify", transport: "GraphQL", method: "POST", path: requestPath, operation: options.operation || operation, statusCode: response.statusCode, ok: false, durationMs: Date.now() - startedAt, message, requestId: response.headers["x-request-id"] || "", jobId: options.jobId || "" });
          const error = new Error(`Shopify GraphQL error: ${message}`);
          error.statusCode = response.statusCode;
          error.responseText = text;
          const throttled = data.errors.some((item) => String(item?.extensions?.code || "").toUpperCase() === "THROTTLED" || /throttl|rate limit/i.test(String(item?.message || "")));
          if (throttled) {
            const throttle = data.extensions?.cost?.throttleStatus || {};
            const requested = Number(data.extensions?.cost?.requestedQueryCost || 0);
            const available = Number(throttle.currentlyAvailable || 0);
            const restoreRate = Number(throttle.restoreRate || 0);
            error.statusCode = 429;
            error.retryAfter = restoreRate > 0 && requested > available ? Math.ceil((requested - available) / restoreRate) + 1 : 2;
            error.shopifyThrottle = true;
          }
          return reject(error);
        }
        appendChannelApiLog({ channel: "Shopify", transport: "GraphQL", method: "POST", path: requestPath, operation: options.operation || operation, statusCode: response.statusCode, ok: true, durationMs: Date.now() - startedAt, message: "OK", requestId: response.headers["x-request-id"] || "", jobId: options.jobId || "" });
        resolve(data.data || {});
      });
    });
    req.on("error", (error) => {
      appendChannelApiLog({ channel: "Shopify", transport: "GraphQL", method: "POST", path: requestPath, operation: options.operation || operation, ok: false, durationMs: Date.now() - startedAt, message: error.message, jobId: options.jobId || "" });
      reject(error);
    });
    req.write(payload);
    req.end();
  });
}

function shopifyRestRequest(method, resourcePath, body = null, options = {}) {
  return shopifyRestRequestWithToken(method, resourcePath, body, shopifyAdminConfig().accessToken, options);
}

function shopifyTokenRequest(options = {}) {
  const config = shopifyAdminConfig();
  if (!config.shop || !config.clientId || !config.clientSecret) {
    throw new Error("Shopify client credentials are not configured. Add SHOPIFY_STORE_DOMAIN, SHOPIFY_CLIENT_ID, and SHOPIFY_CLIENT_SECRET to .env.");
  }
  if (shopifyAccessTokenCache.token && shopifyAccessTokenCache.expiresAt > Date.now() + 60_000) {
    return Promise.resolve(shopifyAccessTokenCache);
  }
  const payload = new URLSearchParams({
    grant_type: "client_credentials",
    client_id: config.clientId,
    client_secret: config.clientSecret
  }).toString();
  const startedAt = Date.now();
  const requestPath = "/admin/oauth/access_token";
  const requestOptions = {
    hostname: config.shop,
    path: requestPath,
    method: "POST",
    headers: {
      "Content-Type": "application/x-www-form-urlencoded",
      "Content-Length": Buffer.byteLength(payload)
    }
  };
  return new Promise((resolve, reject) => {
    const req = https.request(requestOptions, (response) => {
      const chunks = [];
      response.on("data", (chunk) => chunks.push(chunk));
      response.on("end", () => {
        const text = Buffer.concat(chunks).toString("utf8");
        let data = {};
        try {
          data = text ? JSON.parse(text) : {};
        } catch {
          appendChannelApiLog({ channel: "Shopify", transport: "OAuth", method: "POST", path: requestPath, operation: options.operation || "Token request", statusCode: response.statusCode, ok: false, durationMs: Date.now() - startedAt, message: `Non-JSON response (${response.statusCode})`, requestId: response.headers["x-request-id"] || "", jobId: options.jobId || "" });
          return reject(new Error(`Shopify returned a non-JSON response (${response.statusCode}).`));
        }
        if (response.statusCode < 200 || response.statusCode >= 300) {
          appendChannelApiLog({ channel: "Shopify", transport: "OAuth", method: "POST", path: requestPath, operation: options.operation || "Token request", statusCode: response.statusCode, ok: false, durationMs: Date.now() - startedAt, message: text, requestId: response.headers["x-request-id"] || "", jobId: options.jobId || "" });
          return reject(new Error(`Shopify token error (${response.statusCode}): ${text}`));
        }
        const token = String(data.access_token || "").trim();
        if (!token) return reject(new Error("Shopify token response did not include access_token."));
        const expiresIn = Math.max(60, Number(data.expires_in || 86399));
        shopifyAccessTokenCache = {
          token,
          scope: String(data.scope || ""),
          expiresAt: Date.now() + Math.max(60, expiresIn - 60) * 1000
        };
        appendChannelApiLog({ channel: "Shopify", transport: "OAuth", method: "POST", path: requestPath, operation: options.operation || "Token request", statusCode: response.statusCode, ok: true, durationMs: Date.now() - startedAt, message: "OK", requestId: response.headers["x-request-id"] || "", jobId: options.jobId || "" });
        resolve(shopifyAccessTokenCache);
      });
    });
    req.on("error", (error) => {
      appendChannelApiLog({ channel: "Shopify", transport: "OAuth", method: "POST", path: requestPath, operation: options.operation || "Token request", ok: false, durationMs: Date.now() - startedAt, message: error.message, jobId: options.jobId || "" });
      reject(error);
    });
    req.write(payload);
    req.end();
  });
}

async function shopifyAdminAccessToken(options = {}) {
  const config = shopifyAdminConfig();
  if (config.clientId && config.clientSecret) {
    return (await shopifyTokenRequest(options)).token;
  }
  if (config.accessToken) return config.accessToken;
  throw new Error("Shopify Admin API is not configured. Add SHOPIFY_CLIENT_ID and SHOPIFY_CLIENT_SECRET, or SHOPIFY_ADMIN_ACCESS_TOKEN, to .env.");
}

async function refreshShopifyAdminAccessToken(options = {}) {
  shopifyAccessTokenCache = { token: "", expiresAt: 0, scope: "" };
  const config = shopifyAdminConfig();
  if (config.clientId && config.clientSecret) {
    const tokenState = await shopifyTokenRequest({ ...options, operation: options.operation || "Refresh Shopify token" });
    return {
      tokenSource: "client_credentials",
      hasToken: Boolean(tokenState.token),
      scope: tokenState.scope || "",
      scopes: String(tokenState.scope || "").split(/[\s,]+/).filter(Boolean),
      expiresAt: tokenState.expiresAt ? new Date(tokenState.expiresAt).toISOString() : ""
    };
  }
  if (config.accessToken) {
    return {
      tokenSource: "env_admin_token",
      hasToken: true,
      scope: "",
      scopes: [],
      expiresAt: "",
      message: "Using SHOPIFY_ADMIN_ACCESS_TOKEN from .env. Update that token in Shopify if scopes changed."
    };
  }
  throw new Error("Shopify Admin API is not configured. Add SHOPIFY_CLIENT_ID and SHOPIFY_CLIENT_SECRET, or SHOPIFY_ADMIN_ACCESS_TOKEN, to .env.");
}

async function shopifyRestRequestAuto(method, resourcePath, body = null, options = {}) {
  let token = await shopifyAdminAccessToken(options);
  const maxAttempts = options.retryOnThrottle !== false ? Math.max(1, Math.min(10, Number(options.maxThrottleAttempts || 8) || 8)) : 1;
  let attempt = 0;
  let refreshedToken = false;
  while (attempt < maxAttempts) {
    attempt += 1;
    try {
      return await shopifyRestRequestWithToken(method, resourcePath, body, token, options);
    } catch (error) {
      if (!refreshedToken && [401, 403].includes(Number(error.statusCode || 0)) && shopifyAdminConfig().clientId && shopifyAdminConfig().clientSecret) {
        refreshedToken = true;
        appendChannelApiLog({ channel: "Shopify", transport: "REST", method, path: resourcePath, operation: options.operation || resourcePath, statusCode: Number(error.statusCode), ok: false, durationMs: 0, message: "Access token was rejected; refreshing client credentials and retrying once.", jobId: options.jobId || "" });
        await refreshShopifyAdminAccessToken({ ...options, operation: `Refresh token after ${options.operation || resourcePath}` });
        token = await shopifyAdminAccessToken(options);
        continue;
      }
      if (error.statusCode !== 429 || attempt >= maxAttempts) throw error;
      const retryAfterSeconds = Math.max(1, Number(error.retryAfter || 0) || 0);
      const fallbackSeconds = Math.min(120, Math.max(8, attempt * attempt * 3));
      const waitSeconds = retryAfterSeconds || fallbackSeconds;
      appendChannelApiLog({ channel: "Shopify", transport: "REST", method, path: resourcePath, operation: options.operation || resourcePath, statusCode: 429, ok: false, durationMs: 0, message: `Rate limited; retrying in ${waitSeconds}s (attempt ${attempt} of ${maxAttempts}).`, jobId: options.jobId || "" });
      if (typeof options.onThrottle === "function") {
        await options.onThrottle({ attempt, maxAttempts, waitSeconds, error });
      }
      await new Promise((resolve) => setTimeout(resolve, waitSeconds * 1000));
    }
  }
  throw new Error("Shopify request failed after throttle retries.");
}

async function shopifyGraphqlRequestAuto(query, variables = {}, options = {}) {
  let token = await shopifyAdminAccessToken(options);
  const maxAttempts = options.retryOnThrottle !== false ? Math.max(1, Math.min(10, Number(options.maxThrottleAttempts || 8) || 8)) : 1;
  let attempt = 0;
  let refreshedToken = false;
  while (attempt < maxAttempts) {
    attempt += 1;
    try {
      return await shopifyGraphqlRequestWithToken(query, variables, token, options);
    } catch (error) {
      if (!refreshedToken && [401, 403].includes(Number(error.statusCode || 0)) && shopifyAdminConfig().clientId && shopifyAdminConfig().clientSecret) {
        refreshedToken = true;
        appendChannelApiLog({ channel: "Shopify", transport: "GraphQL", method: "POST", path: "/graphql.json", operation: options.operation || shopifyGraphqlOperationName(query), statusCode: Number(error.statusCode), ok: false, durationMs: 0, message: "Access token was rejected; refreshing client credentials and retrying once.", jobId: options.jobId || "" });
        await refreshShopifyAdminAccessToken({ ...options, operation: `Refresh token after ${options.operation || shopifyGraphqlOperationName(query)}` });
        token = await shopifyAdminAccessToken(options);
        continue;
      }
      if (Number(error.statusCode || 0) !== 429 || attempt >= maxAttempts) throw error;
      const retryAfterSeconds = Math.max(1, Number(error.retryAfter || 0) || 0);
      const fallbackSeconds = Math.min(120, Math.max(2, attempt * attempt * 2));
      const waitSeconds = retryAfterSeconds || fallbackSeconds;
      appendChannelApiLog({ channel: "Shopify", transport: "GraphQL", method: "POST", path: "/graphql.json", operation: options.operation || shopifyGraphqlOperationName(query), statusCode: 429, ok: false, durationMs: 0, message: `Rate limited; retrying in ${waitSeconds}s (attempt ${attempt} of ${maxAttempts}).`, jobId: options.jobId || "" });
      if (typeof options.onThrottle === "function") await options.onThrottle({ attempt, maxAttempts, waitSeconds, error });
      await new Promise((resolve) => setTimeout(resolve, waitSeconds * 1000));
    }
  }
  throw new Error("Shopify GraphQL request failed after throttle retries.");
}

// Shopify's client-credentials response can occasionally omit scopes that the
// installed app can in fact use. Verify the protected fields themselves for
// connection health instead of treating the response metadata as authoritative.
async function verifyShopifyOrderAccess() {
  try {
    await shopifyGraphqlRequestAuto(`
      query DataPlusOrderAccessProbe {
        orders(first: 1) {
          nodes {
            id
            customer { id }
          }
        }
      }
    `, {}, { operation: "Verify Shopify order access", retryOnThrottle: false });
    return { ok: true, hasReadOrders: true, hasReadCustomers: true, missingOrderScopes: [] };
  } catch (error) {
    const message = String(error?.message || error || "");
    const missingOrderScopes = [];
    if (/read_orders|orders field/i.test(message)) missingOrderScopes.push("read_orders");
    if (/read_customers|customer field/i.test(message)) missingOrderScopes.push("read_customers");
    return {
      ok: false,
      hasReadOrders: !missingOrderScopes.includes("read_orders"),
      hasReadCustomers: !missingOrderScopes.includes("read_customers"),
      missingOrderScopes,
      message
    };
  }
}

function shopifyOrderSource(sourceName = "") {
  const sourceKey = String(sourceName || "").trim().toLowerCase();
  const lookup = {
    web: { channel: "Online Store", type: "online" },
    shop: { channel: "Shop", type: "online" },
    pos: { channel: "Point of Sale", type: "point_of_sale" },
    draft_order: { channel: "Draft Order", type: "draft" },
    shopify_draft_order: { channel: "Draft Order", type: "draft" },
    mobile_app: { channel: "Mobile App", type: "mobile" },
    api: { channel: "Shopify API", type: "api" }
  };
  return { sourceKey, ...(lookup[sourceKey] || { channel: sourceKey || "Unknown Shopify source", type: sourceKey ? "third_party" : "online" }) };
}

function shopifySourceIsAllowed(order = {}, configuredSources = "Native Shopify sources") {
  const allowed = String(configuredSources || "Native Shopify sources").split(/[,;]+/).map((value) => value.trim().toLowerCase()).filter(Boolean);
  if (!allowed.length || allowed.some((value) => ["all", "*", "all sources", "all shopify sources"].includes(value))) return true;
  const raw = String(order.shopifySourceName || "").trim().toLowerCase();
  const display = String(order.channelSource || "").trim().toLowerCase();
  if (allowed.some((value) => ["native", "native shopify", "native shopify sources"].includes(value))) {
    return ["web", "shop", "pos", "draft_order", "shopify_draft_order", "mobile_app", "api"].includes(raw);
  }
  return allowed.includes(raw) || allowed.includes(display);
}

function shopifyOrderToDataPlusOrder(node = {}) {
  const source = shopifyOrderSource(node.sourceName);
  const customer = node.customer || {};
  const shipping = node.shippingAddress || {};
  const billing = node.billingAddress || {};
  const financial = String(node.displayFinancialStatus || "").toLowerCase();
  const fulfillment = String(node.displayFulfillmentStatus || "").toLowerCase();
  const status = node.cancelledAt ? "canceled" : financial === "refunded" ? "refunded" : fulfillment === "fulfilled" ? "fulfilled" : fulfillment === "partial" ? "partial_fulfilled" : financial === "paid" ? "processing" : "new";
  return {
    id: String(node.id || "").replace("gid://shopify/Order/", "shopify-order-"),
    shopifyOrderId: node.id || "",
    orderNumber: node.name || "",
    marketplaceOrderId: String(node.id || ""),
    source: "Shopify",
    channelSource: source.channel,
    shopifySourceName: source.sourceKey,
    orderType: source.type,
    status,
    financialStatus: node.displayFinancialStatus || "",
    fulfillmentStatus: node.displayFulfillmentStatus || "",
    cancelledAt: node.cancelledAt || "",
    buyer: customer.displayName || [shipping.firstName, shipping.lastName].filter(Boolean).join(" ") || node.email || "",
    buyerEmail: customer.email || node.email || "",
    phone: shipping.phone || customer.phone || "",
    customerId: customer.id || "",
    currency: node.currencyCode || "USD",
    total: Number(node.totalPriceSet?.shopMoney?.amount || 0),
    subtotal: Number(node.subtotalPriceSet?.shopMoney?.amount || 0),
    tax: Number(node.totalTaxSet?.shopMoney?.amount || 0),
    shippingCost: Number(node.totalShippingPriceSet?.shopMoney?.amount || 0),
    discountTotal: Number(node.totalDiscountsSet?.shopMoney?.amount || 0),
    paidAmount: financial === "paid" ? Number(node.totalPriceSet?.shopMoney?.amount || 0) : 0,
    qty: (node.lineItems?.edges || []).reduce((sum, edge) => sum + Number(edge.node?.quantity || 0), 0),
    address: { name: [shipping.firstName, shipping.lastName].filter(Boolean).join(" "), company: shipping.company || "", line1: shipping.address1 || "", line2: shipping.address2 || "", city: shipping.city || "", state: shipping.province || "", postalCode: shipping.zip || "", country: shipping.countryCodeV2 || shipping.country || "", phone: shipping.phone || "" },
    billingAddress: { name: [billing.firstName, billing.lastName].filter(Boolean).join(" "), company: billing.company || "", line1: billing.address1 || "", line2: billing.address2 || "", city: billing.city || "", state: billing.province || "", postalCode: billing.zip || "", country: billing.countryCodeV2 || billing.country || "", phone: billing.phone || "" },
    shippingLines: (node.shippingLines?.edges || []).map((edge) => ({ title: edge.node?.title || "", code: edge.node?.code || "", price: Number(edge.node?.originalPriceSet?.shopMoney?.amount || 0) })),
    discountCodes: (node.discountCodes || []).map((code) => String(code)),
    items: (node.lineItems?.edges || []).map((edge, index) => ({ lineId: edge.node?.id || "", lineIndex: index, sku: edge.node?.sku || edge.node?.variant?.sku || "", originalSku: edge.node?.sku || edge.node?.variant?.sku || "", channelVariantSku: edge.node?.variant?.sku || edge.node?.sku || "", channelVariantId: edge.node?.variant?.id || "", title: edge.node?.title || "", qty: Number(edge.node?.quantity || 0), price: Number(edge.node?.originalUnitPriceSet?.shopMoney?.amount || 0), taxable: Boolean(edge.node?.taxable), vendor: edge.node?.vendor || "", variantTitle: edge.node?.variantTitle || "" })),
    payments: (node.transactions || []).map((transaction) => ({ id: transaction?.id || crypto.randomUUID(), provider: transaction?.gateway || "Shopify", transactionId: transaction?.authorizationCode || transaction?.id || "", amount: Number(transaction?.amountSet?.shopMoney?.amount || 0), currency: transaction?.amountSet?.shopMoney?.currencyCode || node.currencyCode || "USD", status: String(transaction?.status || "").toLowerCase(), kind: String(transaction?.kind || "").toLowerCase(), manuallyCapturable: Boolean(transaction?.manuallyCapturable), parentTransactionId: transaction?.parentTransaction?.id || "", createdAt: transaction?.createdAt || "" })),
    shopifyAdminUrl: node.legacyResourceId ? `https://admin.shopify.com/store/${shopifyAdminConfig().shop.split(".")[0]}/orders/${node.legacyResourceId}` : "",
    createdAt: node.createdAt || new Date().toISOString(), updatedAt: node.updatedAt || new Date().toISOString(), importedAt: new Date().toISOString()
  };
}

async function importShopifyOrders(limit = 250, filters = {}) {
  const query = `query DataPlusOrders($first: Int!, $after: String) { orders(first: $first, after: $after, sortKey: CREATED_AT, reverse: true) { pageInfo { hasNextPage endCursor } edges { node { id legacyResourceId name sourceName email currencyCode createdAt updatedAt cancelledAt displayFinancialStatus displayFulfillmentStatus customer { id displayName email phone } subtotalPriceSet { shopMoney { amount } } totalPriceSet { shopMoney { amount } } totalTaxSet { shopMoney { amount } } totalShippingPriceSet { shopMoney { amount } } totalDiscountsSet { shopMoney { amount } } shippingAddress { firstName lastName company address1 address2 city province zip country countryCodeV2 phone } billingAddress { firstName lastName company address1 address2 city province zip country countryCodeV2 phone } discountCodes shippingLines(first: 20) { edges { node { title code originalPriceSet { shopMoney { amount } } } } } lineItems(first: 250) { edges { node { id sku title quantity taxable vendor variantTitle variant { id sku } originalUnitPriceSet { shopMoney { amount } } } } } transactions(first: 50) { id kind status gateway authorizationCode createdAt manuallyCapturable parentTransaction { id } amountSet { shopMoney { amount currencyCode } } } } } } }`;
  const imported = []; let after = null;
  while (imported.length < limit) {
    const data = await shopifyGraphqlRequestAuto(query, { first: Math.min(250, limit - imported.length), after }, { operation: "Import Shopify orders" });
    const connection = data?.orders || {}; imported.push(...(connection.edges || []).map((edge) => shopifyOrderToDataPlusOrder(edge.node)).filter((order) => order.id));
    if (!connection.pageInfo?.hasNextPage || !connection.pageInfo?.endCursor) break; after = connection.pageInfo.endCursor;
  }
  const sources = String(filters.sources || "Native Shopify sources");
  const filtered = imported.filter((order) => shopifySourceIsAllowed(order, sources));
  for (let index = 0; index < filtered.length; index += 1) {
    if (!isTerminalCustomerDemand(filtered[index])) continue;
    const existing = await postgres.readOrderByKey(filtered[index].id);
    filtered[index] = preserveMarketplaceOrderOperations(filtered[index], existing);
  }
  await postgres.upsertOrdersFromState(filtered, { replace: false });
  await reconcilePersistedTerminalOrders(filtered, { user: "Shopify order import" });
  clearOrderApiCache();
  return filtered;
}

function shopifyOrderWebhookQuery() {
  return `query DataPlusOrderWebhook($id: ID!) { order(id: $id) { id legacyResourceId name sourceName email currencyCode createdAt updatedAt cancelledAt displayFinancialStatus displayFulfillmentStatus customer { id displayName email phone } subtotalPriceSet { shopMoney { amount } } totalPriceSet { shopMoney { amount } } totalTaxSet { shopMoney { amount } } totalShippingPriceSet { shopMoney { amount } } totalDiscountsSet { shopMoney { amount } } shippingAddress { firstName lastName company address1 address2 city province zip country countryCodeV2 phone } billingAddress { firstName lastName company address1 address2 city province zip country countryCodeV2 phone } discountCodes shippingLines(first: 20) { edges { node { title code originalPriceSet { shopMoney { amount } } } } } lineItems(first: 250) { edges { node { id sku title quantity taxable vendor variantTitle variant { id sku } originalUnitPriceSet { shopMoney { amount } } } } } transactions(first: 50) { id kind status gateway authorizationCode createdAt manuallyCapturable parentTransaction { id } amountSet { shopMoney { amount currencyCode } } } } }`;
}

async function refreshShopifyOrderFromWebhook(orderId = "", settings = {}, webhook = {}) {
  if (!orderId.startsWith("gid://shopify/Order/")) throw new Error("Webhook payload did not include a Shopify order ID.");
  const data = await shopifyGraphqlRequestAuto(shopifyOrderWebhookQuery(), { id: orderId }, { operation: `Refresh Shopify order webhook ${orderId}` });
  const incoming = shopifyOrderToDataPlusOrder(data?.order || {});
  if (!incoming.id) throw new Error("Shopify could not load the order referenced by this webhook.");
  if (!shopifySourceIsAllowed(incoming, settings.shopifyOrderImportSources)) return { skipped: true, reason: `Sales channel ${incoming.channelSource || "Unknown"} is not enabled for Shopify order imports.` };
  const existing = await postgres.readOrderByKey(incoming.id);
  const merged = preserveMarketplaceOrderOperations(incoming, existing);
  merged.updatedAt = new Date().toISOString();
  merged.importedAt = new Date().toISOString();
  addOrderTimeline(merged, { type: "channel_sync", title: "Shopify webhook applied", message: `${String(webhook.topic || "orders/update")} refreshed the local order record.`, user: "Shopify" });
  await postgres.saveOrder(merged);
  await reconcilePersistedTerminalOrders([merged], { user: `Shopify ${String(webhook.topic || "orders/update")}` });
  clearOrderApiCache(merged.id);
  return { order: merged, created: !existing };
}

async function fetchShopifyLocations() {
  const data = await shopifyGraphqlRequestAuto(`
    query DataPlusLocations {
      locations(first: 250) {
        nodes { id name isActive fulfillsOnlineOrders }
      }
    }
  `, {}, { operation: "Fetch Shopify locations" });
  return (data.locations?.nodes || [])
    .map((row) => ({
      id: normalizeShopifyLocationGid(row.id),
      name: String(row.name || row.id || "Shopify location").trim(),
      isActive: row.isActive !== false,
      fulfillsOnlineOrders: row.fulfillsOnlineOrders === true
    }))
    .filter((row) => row.id)
    .sort((a, b) => a.name.localeCompare(b.name));
}

const SHOPIFY_WEBHOOK_MAX_CONCURRENCY = Math.max(1, Math.min(10, Number(process.env.DATAPLUS_SHOPIFY_WEBHOOK_CONCURRENCY || 3) || 3));
let shopifyWebhookInFlight = 0;

async function readChannelSettingsFast(channelName = "") {
  if (postgres.isPostgresEnabled()) {
    const connections = await postgres.readStateField("connections");
    return findChannelByName({ connections: Array.isArray(connections) ? connections : [] }, channelName)?.settings || DEFAULT_CHANNEL_SETTINGS;
  }
  const db = await readDbFast({ skipInventory: true });
  return findChannelByName(db, channelName)?.settings || DEFAULT_CHANNEL_SETTINGS;
}

async function registerShopifyOrderWebhooks() {
  const baseUrl = configuredShopifyAppUrl().replace(/\/+$/, "");
  if (!/^https:\/\//i.test(baseUrl)) throw new Error("Set SHOPIFY_APP_URL to the public HTTPS DataPlus URL before registering webhooks.");
  const uri = `${baseUrl}/api/webhooks/shopify/orders`;
  // ORDERS_UPDATED also arrives after financial changes, including refunds. Some
  // shops reject REFUNDS_CREATE even when order access is granted, so it must not
  // prevent the rest of the order synchronization subscriptions from registering.
  const topics = ["ORDERS_CREATE", "ORDERS_UPDATED", "ORDERS_CANCELLED", "ORDERS_PARTIALLY_FULFILLED", "ORDERS_FULFILLED", "REFUNDS_CREATE"];
  const current = await shopifyGraphqlRequestAuto(`query DataPlusWebhookSubscriptions { webhookSubscriptions(first: 100) { nodes { id topic callbackUrl } } }`, {}, { operation: "Inspect Shopify order webhooks" });
  const existing = current?.webhookSubscriptions?.nodes || [];
  const created = [];
  const failed = [];
  for (const topic of topics) {
    if (existing.some((entry) => String(entry.topic || "") === topic && String(entry.callbackUrl || "") === uri)) continue;
    try {
      const data = await shopifyGraphqlRequestAuto(`mutation DataPlusWebhookCreate($topic: WebhookSubscriptionTopic!, $webhookSubscription: WebhookSubscriptionInput!) { webhookSubscriptionCreate(topic: $topic, webhookSubscription: $webhookSubscription) { webhookSubscription { id topic callbackUrl } userErrors { field message } } }`, { topic, webhookSubscription: { callbackUrl: uri } }, { operation: `Register Shopify webhook ${topic}` });
      const errors = data?.webhookSubscriptionCreate?.userErrors || [];
      if (errors.length) throw new Error(errors.map((entry) => entry.message || "Shopify could not register the webhook.").join("; "));
      created.push(data?.webhookSubscriptionCreate?.webhookSubscription || { topic });
    } catch (error) {
      failed.push({ topic, message: error.message || "Shopify could not register the webhook." });
    }
  }
  return { uri, created, existing: topics.length - created.length - failed.length, failed };
}

async function cancelShopifyOrder(order = {}, options = {}) {
  const orderId = String(order.shopifyOrderId || "").trim();
  if (!orderId.startsWith("gid://shopify/Order/")) throw new Error("This order is not linked to a Shopify order.");
  const allowedReasons = new Set(["CUSTOMER", "DECLINED", "FRAUD", "INVENTORY", "STAFF", "OTHER"]);
  const reason = String(options.reason || "OTHER").trim().toUpperCase();
  const query = `mutation DataPlusCancelOrder($orderId: ID!, $reason: OrderCancelReason!, $restock: Boolean!, $notifyCustomer: Boolean!, $staffNote: String) { orderCancel(orderId: $orderId, reason: $reason, restock: $restock, notifyCustomer: $notifyCustomer, staffNote: $staffNote, refundMethod: { originalPaymentMethodsRefund: false }) { job { id done } orderCancelUserErrors { field message code } } }`;
  const data = await shopifyGraphqlRequestAuto(query, {
    orderId,
    reason: allowedReasons.has(reason) ? reason : "OTHER",
    restock: options.restock !== false,
    notifyCustomer: Boolean(options.notifyCustomer),
    staffNote: String(options.note || "").slice(0, 255) || null
  }, { operation: `Cancel Shopify order ${order.orderNumber || orderId}` });
  const errors = data?.orderCancel?.orderCancelUserErrors || [];
  if (errors.length) throw new Error(errors.map((entry) => entry.message || "Shopify could not cancel the order.").join("; "));
  return data?.orderCancel?.job || {};
}

async function syncShopifyShipment(order = {}, shipment = {}) {
  const orderId = String(order.shopifyOrderId || "").trim();
  if (!orderId.startsWith("gid://shopify/Order/")) throw new Error("This order is not linked to a Shopify order.");
  const fulfillmentOrderQuery = `query DataPlusFulfillmentOrders($orderId: ID!) { order(id: $orderId) { fulfillmentOrders(first: 50) { nodes { id status lineItems(first: 250) { nodes { id remainingQuantity lineItem { id sku } } } } } } }`;
  const source = await shopifyGraphqlRequestAuto(fulfillmentOrderQuery, { orderId }, { operation: `Load Shopify fulfillment orders ${order.orderNumber || orderId}` });
  const fulfillmentOrders = source?.order?.fulfillmentOrders?.nodes || [];
  const localOrderLines = orderLineItems(order);
  const shipmentLines = Array.isArray(shipment.lines) ? shipment.lines : [];
  const lineItemsByFulfillmentOrder = [];
  for (const fulfillmentOrder of fulfillmentOrders) {
    const fulfillmentOrderLineItems = [];
    for (const fulfillmentLine of fulfillmentOrder.lineItems?.nodes || []) {
      const shopifyLineId = String(fulfillmentLine.lineItem?.id || "");
      const sku = String(fulfillmentLine.lineItem?.sku || "").trim().toLowerCase();
      const localIndex = localOrderLines.findIndex((line) => String(line.lineId || line.id || "") === shopifyLineId || (sku && [line.sku, line.originalSku, line.channelVariantSku].some((value) => String(value || "").trim().toLowerCase() === sku)));
      if (localIndex < 0) continue;
      const localShipmentLine = shipmentLines.find((line) => Number(line.lineIndex || 0) === localIndex)
        || shipmentLines.find((line) => sku && String(line.sku || "").trim().toLowerCase() === sku);
      const quantity = Math.min(Number(localShipmentLine?.qtyFulfilled || localShipmentLine?.qtyAllocated || 0), Number(fulfillmentLine.remainingQuantity || 0));
      if (quantity > 0) fulfillmentOrderLineItems.push({ id: fulfillmentLine.id, quantity });
    }
    if (fulfillmentOrderLineItems.length) lineItemsByFulfillmentOrder.push({ fulfillmentOrderId: fulfillmentOrder.id, fulfillmentOrderLineItems });
  }
  if (!lineItemsByFulfillmentOrder.length) throw new Error("No fulfillable Shopify line items matched this shipment. Refresh the order from Shopify and review the shipment lines.");
  const mutation = `mutation DataPlusFulfillmentCreate($fulfillment: FulfillmentInput!, $message: String) { fulfillmentCreate(fulfillment: $fulfillment, message: $message) { fulfillment { id status trackingInfo { company number url } } userErrors { field message } } }`;
  const trackingInfo = { company: String(shipment.carrierName || shipment.carrier || "").trim() || undefined, number: String(shipment.trackingNumber || "").trim() || undefined, url: String(shipment.trackingUrl || "").trim() || undefined };
  const fulfillment = {
    lineItemsByFulfillmentOrder,
    notifyCustomer: Boolean(shipment.notifyCustomer),
    trackingInfo: Object.values(trackingInfo).some(Boolean) ? trackingInfo : undefined
  };
  const data = await shopifyGraphqlRequestAuto(mutation, { fulfillment, message: `Shipment recorded in DataPlus for ${order.orderNumber || "order"}.` }, { operation: `Send fulfillment to Shopify ${order.orderNumber || orderId}` });
  const errors = data?.fulfillmentCreate?.userErrors || [];
  if (errors.length) throw new Error(errors.map((entry) => entry.message || "Shopify could not create the fulfillment.").join("; "));
  return data?.fulfillmentCreate?.fulfillment || {};
}

function shopifyLabelPurchaseSummary(result = {}) {
  const labels = Array.isArray(result.shippingLabels) ? result.shippingLabels : [];
  return {
    id: String(result.id || ""),
    status: String(result.status || "PENDING_PURCHASE"),
    done: Boolean(result.done),
    errors: (Array.isArray(result.errors) ? result.errors : []).map((entry) => ({ code: String(entry?.code || ""), message: String(entry?.message || "") })).filter((entry) => entry.message),
    labels: labels.map((label) => ({
      id: String(label?.id || ""),
      cancellable: Boolean(label?.cancellable),
      printed: Boolean(label?.printed),
      tracking: label?.trackingInfo ? { company: String(label.trackingInfo.company || ""), number: String(label.trackingInfo.number || ""), url: String(label.trackingInfo.url || "") } : null,
      documents: (Array.isArray(label?.shippingDocuments) ? label.shippingDocuments : []).map((document) => ({
        documentType: String(document?.documentType || "LABEL"),
        format: String(document?.format || ""),
        url: String(document?.url || ""),
        printedAt: String(document?.printedAt || "")
      })).filter((document) => document.url)
    }))
  };
}

function ensureLocalShipmentForPurchasedLabel(order = {}, purchase = {}) {
  if (String(purchase.status || "").toUpperCase() !== "PURCHASED" || !Array.isArray(purchase.labels) || !purchase.labels.length) return null;
  order.shipments = Array.isArray(order.shipments) ? order.shipments : [];
  const existing = order.shipments.find((shipment) => String(shipment.labelPurchaseId || "") === String(purchase.id || ""));
  if (existing) return existing;
  const label = purchase.labels[0] || {};
  const tracking = label.tracking || {};
  const packageInfo = purchase.package || {};
  const shipmentNumber = order.shipments.length + 1;
  const referenceBase = String(order.orderNumber || order.id || "ORDER").replace(/^#/, "");
  const shipment = {
    id: crypto.randomUUID(),
    reference: `${referenceBase}-SH${shipmentNumber}`,
    status: "label_purchased",
    labelPurchaseId: String(purchase.id || ""),
    labelId: String(label.id || ""),
    createdAt: new Date().toISOString(),
    labelPurchasedAt: new Date().toISOString(),
    warehouseId: String(purchase.warehouseId || order.fulfillmentWarehouseId || ""),
    warehouseName: String(purchase.warehouseName || order.fulfillmentWarehouseName || ""),
    carrier: String(tracking.company || "Shopify Shipping"),
    carrierName: String(tracking.company || "Shopify Shipping"),
    service: String(order.selectedShippingQuote?.title || order.shippingService || "Shopify Shipping"),
    trackingNumber: String(tracking.number || ""),
    trackingUrl: String(tracking.url || ""),
    shipDate: String(packageInfo.shipDate || ""),
    notifyCustomer: Boolean(purchase.notifyCustomer),
    documents: Array.isArray(label.documents) ? label.documents : [],
    lines: (Array.isArray(purchase.lines) ? purchase.lines : []).map((line) => ({
      sku: String(line?.sku || ""), lineIndex: Number(line?.lineIndex || 0), qtyAllocated: Number(line?.qty || 0), qtyFulfilled: 0
    })).filter((line) => line.sku && line.qtyAllocated > 0),
    packages: [{
      id: crypto.randomUUID(), weight: Number(packageInfo.weightPounds || 0), length: Number(packageInfo.lengthInches || 0),
      width: Number(packageInfo.widthInches || 0), height: Number(packageInfo.heightInches || 0), updatedAt: new Date().toISOString()
    }],
    channelSync: { status: "awaiting_fulfillment", channel: "Shopify", updatedAt: new Date().toISOString(), message: "Label purchased. Confirm fulfillment before sending the shipment to Shopify." }
  };
  order.shipments.push(shipment);
  order.documents = Array.isArray(order.documents) ? order.documents : [];
  for (const document of shipment.documents) {
    const url = String(document?.url || "").trim();
    if (!url || order.documents.some((entry) => String(entry?.url || "") === url)) continue;
    order.documents.unshift({
      id: crypto.randomUUID(), name: `${shipment.reference} ${String(document?.format || document?.documentType || "label")}`,
      url, type: "shipping_label", note: `Shopify Shipping label for ${shipment.reference}.`, createdAt: new Date().toISOString(), createdBy: "Shopify"
    });
  }
  purchase.shipmentId = shipment.id;
  purchase.shipmentReference = shipment.reference;
  return shipment;
}

async function fetchShopifyFulfillmentOrdersForLabel(order = {}) {
  const orderId = String(order.shopifyOrderId || "").trim();
  if (!orderId.startsWith("gid://shopify/Order/")) throw new Error("This order is not linked to a Shopify order.");
  const query = `query DataPlusLabelFulfillmentOrders($orderId: ID!) { order(id: $orderId) { fulfillmentOrders(first: 50) { nodes { id status } } } }`;
  const data = await shopifyGraphqlRequestAuto(query, { orderId }, { operation: `Load label fulfillment orders ${order.orderNumber || orderId}` });
  return data?.order?.fulfillmentOrders?.nodes || [];
}

async function purchaseShopifyShippingLabel(order = {}, input = {}) {
  const fulfillmentOrders = await fetchShopifyFulfillmentOrdersForLabel(order);
  const requestedFulfillmentOrderId = String(input.fulfillmentOrderId || "").trim();
  const fulfillmentOrder = fulfillmentOrders.find((entry) => String(entry.id || "") === requestedFulfillmentOrderId)
    || fulfillmentOrders.find((entry) => !["CLOSED", "CANCELLED", "INCOMPLETE"].includes(String(entry.status || "").toUpperCase()));
  if (!fulfillmentOrder?.id) throw new Error("No open Shopify fulfillment order is available for label purchase.");
  const weightPounds = Number(input.weightPounds || 0);
  const lengthInches = Number(input.lengthInches || 0);
  const widthInches = Number(input.widthInches || 0);
  const heightInches = Number(input.heightInches || 0);
  if (!(weightPounds > 0)) throw new Error("A package weight greater than zero is required.");
  if (![lengthInches, widthInches, heightInches].every((value) => value > 0)) throw new Error("Package length, width, and height are required.");
  const shipDate = String(input.shipDate || "").trim();
  if (!/^\d{4}-\d{2}-\d{2}$/.test(shipDate)) throw new Error("Enter a valid ship date.");
  const shippingDatetime = new Date(`${shipDate}T12:00:00.000Z`);
  if (!Number.isFinite(shippingDatetime.getTime()) || shippingDatetime.getTime() < Date.now() - 60 * 60 * 1000) throw new Error("The ship date cannot be in the past.");
  const carrierCode = String(input.carrierCode || "").trim();
  const serviceCode = String(input.serviceCode || "").trim();
  if (Boolean(carrierCode) !== Boolean(serviceCode)) throw new Error("Enter both a carrier code and service code, or leave both blank for Shopify's recommended rate.");
  const shippingLabelPurchase = {
    fulfillmentOrderId: fulfillmentOrder.id,
    notifyCustomer: Boolean(input.notifyCustomer),
    shippingDatetime: shippingDatetime.toISOString(),
    totalWeight: { unit: "GRAMS", value: Math.round(weightPounds * 453.592 * 100) / 100 },
    packageInfo: {
      customPackage: {
        type: String(input.packageType || "BOX").toUpperCase(),
        dimensions: { unit: "INCHES", length: lengthInches, width: widthInches, height: heightInches },
        weight: { unit: "GRAMS", value: Math.round(weightPounds * 453.592 * 100) / 100 }
      }
    },
    ...(carrierCode && serviceCode ? { preferredRateSelection: { carrierCode, serviceCode } } : {})
  };
  const mutation = `mutation DataPlusShippingLabelPurchase($shippingLabelPurchase: ShippingLabelPurchaseInput!) { shippingLabelPurchase(shippingLabelPurchase: $shippingLabelPurchase) { shippingLabelPurchaseResult { id done status errors { code message } shippingLabels { id cancellable printed trackingInfo { company number url } shippingDocuments { documentType format url printedAt } } } userErrors { field message code } } }`;
  const data = await shopifyGraphqlRequestAuto(mutation, { shippingLabelPurchase }, { operation: `Purchase Shopify shipping label ${order.orderNumber || order.id || "order"}` });
  const userErrors = data?.shippingLabelPurchase?.userErrors || [];
  if (userErrors.length) throw new Error(userErrors.map((entry) => entry.message || "Shopify could not start the label purchase.").join("; "));
  return { fulfillmentOrderId: fulfillmentOrder.id, result: shopifyLabelPurchaseSummary(data?.shippingLabelPurchase?.shippingLabelPurchaseResult || {}) };
}

async function getShopifyShippingLabelPurchase(purchaseId = "") {
  const id = String(purchaseId || "").trim();
  if (!id.startsWith("gid://shopify/")) throw new Error("A valid Shopify label purchase ID is required.");
  const query = `query DataPlusShippingLabelPurchaseStatus($id: ID!) { node(id: $id) { ... on ShippingLabelPurchaseResult { id done status errors { code message } shippingLabels { id cancellable printed trackingInfo { company number url } shippingDocuments { documentType format url printedAt } } } } }`;
  const data = await shopifyGraphqlRequestAuto(query, { id }, { operation: "Check Shopify shipping label purchase" });
  if (!data?.node?.id) throw new Error("Shopify could not find this label purchase.");
  return shopifyLabelPurchaseSummary(data.node);
}

function shopifyMailingAddressInput(address = {}) {
  const name = String(address.name || "").trim().split(/\s+/).filter(Boolean);
  const country = String(address.countryCode || address.country || "").trim().toUpperCase();
  const countryCode = country.length === 2 ? country : ({ "UNITED STATES": "US", USA: "US", CANADA: "CA" }[country] || "");
  return {
    address1: String(address.line1 || "").trim(),
    address2: String(address.line2 || "").trim() || undefined,
    city: String(address.city || "").trim(),
    provinceCode: String(address.state || "").trim() || undefined,
    zip: String(address.postalCode || "").trim(),
    countryCode: countryCode || undefined,
    firstName: name[0] || undefined,
    lastName: name.slice(1).join(" ") || undefined,
    company: String(address.company || "").trim() || undefined,
    phone: String(address.phone || "").trim() || undefined
  };
}

async function quoteShopifyOrderShipping(order = {}, requestedLines = []) {
  if (String(order.source || "").toLowerCase() !== "shopify") throw new Error("Shopify delivery quotes are available only for Shopify-imported orders.");
  const address = shopifyMailingAddressInput(order.address || {});
  if (![address.address1, address.city, address.zip, address.countryCode].every(Boolean)) throw new Error("A complete shipping address is required before calculating Shopify delivery options.");
  const requestedByIndex = new Map((Array.isArray(requestedLines) ? requestedLines : []).map((line) => [Number(line.lineIndex), Number(line.qty || 0)]).filter(([, quantity]) => quantity > 0));
  let lineItems = orderLineItems(order).map((line, index) => ({ variantId: String(line.channelVariantId || line.shopifyVariantId || "").trim(), quantity: requestedByIndex.size ? Number(requestedByIndex.get(index) || 0) : Number(line.qty || 0) })).filter((line) => line.variantId.startsWith("gid://shopify/ProductVariant/") && line.quantity > 0);
  if (!lineItems.length) {
    const orderId = String(order.shopifyOrderId || "").trim();
    if (orderId.startsWith("gid://shopify/Order/")) {
      const orderQuery = `query DataPlusQuoteOrderLines($id: ID!) { order(id: $id) { lineItems(first: 250) { nodes { quantity variant { id } } } } }`;
      const source = await shopifyGraphqlRequestAuto(orderQuery, { id: orderId }, { operation: `Load Shopify quote lines ${order.orderNumber || order.id || "order"}` });
      lineItems = (source?.order?.lineItems?.nodes || []).map((line) => ({ variantId: String(line?.variant?.id || "").trim(), quantity: Number(line?.quantity || 0) })).filter((line) => line.variantId.startsWith("gid://shopify/ProductVariant/") && line.quantity > 0);
    }
  }
  if (!lineItems.length) throw new Error("No Shopify product variants were found on this order. Refresh the order and review its SKU matches.");
  const query = `mutation DataPlusDraftOrderCalculate($input: DraftOrderInput!) { draftOrderCalculate(input: $input) { calculatedDraftOrder { availableShippingRates { handle title price { amount currencyCode } } totalShippingPriceSet { shopMoney { amount currencyCode } } } userErrors { field message } } }`;
  const data = await shopifyGraphqlRequestAuto(query, { input: { lineItems, shippingAddress: address } }, { operation: `Calculate Shopify delivery options ${order.orderNumber || order.id || "order"}` });
  const errors = data?.draftOrderCalculate?.userErrors || [];
  if (errors.length) throw new Error(errors.map((entry) => entry.message || "Shopify could not calculate delivery options.").join("; "));
  const calculated = data?.draftOrderCalculate?.calculatedDraftOrder || {};
  return {
    id: crypto.randomUUID(),
    source: "Shopify draft-order calculation",
    quotedAt: new Date().toISOString(),
    options: (calculated.availableShippingRates || []).map((rate) => ({ handle: String(rate.handle || ""), title: String(rate.title || "Shipping"), amount: Number(rate.price?.amount || 0), currency: String(rate.price?.currencyCode || order.currency || "USD") })),
    calculatedShipping: { amount: Number(calculated.totalShippingPriceSet?.shopMoney?.amount || 0), currency: String(calculated.totalShippingPriceSet?.shopMoney?.currencyCode || order.currency || "USD") }
  };
}

async function syncShopifyRefund(order = {}, refund = {}) {
  const orderId = String(order.shopifyOrderId || "").trim();
  if (!orderId.startsWith("gid://shopify/Order/")) throw new Error("This order is not linked to a Shopify order.");
  const localLines = orderLineItems(order);
  const refundLineItems = (refund.items || []).map((item) => {
    const line = localLines[Number(item.lineIndex || 0)]
      || localLines.find((candidate) => String(candidate.sku || "").toLowerCase() === String(item.sku || "").toLowerCase());
    const lineItemId = String(line?.lineId || line?.id || "").trim();
    return lineItemId.startsWith("gid://shopify/LineItem/") && Number(item.qty || 0) > 0
      ? { lineItemId, quantity: Number(item.qty || 0) }
      : null;
  }).filter(Boolean);
  if (!refundLineItems.length) throw new Error("No Shopify order lines matched this refund. Refresh the order and verify the selected line items.");
  const mutation = `mutation DataPlusRefundCreate($input: RefundInput!) { refundCreate(input: $input) @idempotent(key: "${crypto.randomUUID()}") { refund { id totalRefundedSet { shopMoney { amount currencyCode } } } userErrors { field message } } }`;
  const data = await shopifyGraphqlRequestAuto(mutation, {
    input: {
      orderId,
      refundLineItems,
      note: String(refund.note || refund.reason || "Refund recorded in DataPlus").slice(0, 255),
      transactions: []
    }
  }, { operation: `Refund Shopify order ${order.orderNumber || orderId}` });
  const errors = data?.refundCreate?.userErrors || [];
  if (errors.length) throw new Error(errors.map((entry) => entry.message || "Shopify could not create the refund.").join("; "));
  return data?.refundCreate?.refund || {};
}

async function syncShopifyReturn(order = {}, returnRecord = {}) {
  const orderId = String(order.shopifyOrderId || "").trim();
  if (!orderId.startsWith("gid://shopify/Order/")) throw new Error("This order is not linked to a Shopify order.");
  const selectedItems = Array.isArray(returnRecord.items) ? returnRecord.items : [];
  if (!selectedItems.length) throw new Error("This return has no line items to send to Shopify.");

  // Shopify returns must reference fulfilled fulfillment-line items, not order line IDs.
  const lookup = `query DataPlusReturnableFulfillments($id: ID!) {
    order(id: $id) {
      returnableFulfillments(first: 100) {
        nodes {
          returnableFulfillmentLineItems(first: 250) {
            nodes {
              quantity
              fulfillmentLineItem { id lineItem { id sku } }
            }
          }
        }
      }
    }
  }`;
  const lookupData = await shopifyGraphqlRequestAuto(lookup, { id: orderId }, { operation: `Find returnable Shopify lines for ${order.orderNumber || orderId}` });
  const candidates = (lookupData?.order?.returnableFulfillments?.nodes || []).flatMap((fulfillment) => fulfillment?.returnableFulfillmentLineItems?.nodes || []);
  const localLines = orderLineItems(order);
  const usedFulfillmentLineIds = new Set();
  const returnLineItems = selectedItems.map((item) => {
    const localLine = localLines[Number(item.lineIndex || 0)]
      || localLines.find((line) => String(line.sku || "").toLowerCase() === String(item.sku || "").toLowerCase());
    const requestedQty = Number(item.qty || 0);
    const matching = candidates.find((candidate) => {
      const fulfillmentLine = candidate?.fulfillmentLineItem || {};
      const exactOrderLine = String(localLine?.lineId || localLine?.id || "") === String(fulfillmentLine?.lineItem?.id || "");
      const sameSku = String(localLine?.sku || item.sku || "").trim().toLowerCase() === String(fulfillmentLine?.lineItem?.sku || "").trim().toLowerCase();
      return !usedFulfillmentLineIds.has(String(fulfillmentLine.id || "")) && Number(candidate?.quantity || 0) >= requestedQty && (exactOrderLine || sameSku);
    });
    if (!matching || requestedQty <= 0) return null;
    const fulfillmentLineItemId = String(matching.fulfillmentLineItem?.id || "");
    usedFulfillmentLineIds.add(fulfillmentLineItemId);
    return {
      fulfillmentLineItemId,
      quantity: requestedQty,
      returnReason: "OTHER",
      returnReasonNote: String(returnRecord.reason || returnRecord.note || "Return created in DataPlus").slice(0, 255)
    };
  }).filter(Boolean);
  if (!returnLineItems.length) throw new Error("No eligible Shopify fulfilled lines matched this return. Refresh the order and confirm the selected quantities were fulfilled and not already refunded.");
  const mutation = `mutation DataPlusReturnCreate($returnInput: ReturnInput!) {
    returnCreate(returnInput: $returnInput) {
      return { id status order { id } }
      userErrors { field message }
    }
  }`;
  const data = await shopifyGraphqlRequestAuto(mutation, {
    returnInput: { orderId, returnLineItems }
  }, { operation: `Create Shopify return for ${order.orderNumber || orderId}` });
  const errors = data?.returnCreate?.userErrors || [];
  if (errors.length) throw new Error(errors.map((entry) => entry.message || "Shopify could not create the return.").join("; "));
  return data?.returnCreate?.return || {};
}

async function captureShopifyPayment(order = {}, payment = {}, amount = 0) {
  const orderId = String(order.shopifyOrderId || "").trim();
  const parentTransactionId = String(payment.id || "").trim();
  const captureAmount = Number(amount || 0);
  if (!orderId.startsWith("gid://shopify/Order/")) throw new Error("This order is not linked to a Shopify order.");
  if (!parentTransactionId.startsWith("gid://shopify/OrderTransaction/")) throw new Error("This payment authorization is not linked to a Shopify transaction.");
  if (!(captureAmount > 0)) throw new Error("Enter a capture amount greater than zero.");
  const mutation = `mutation DataPlusOrderCapture($input: OrderCaptureInput!) {
    orderCapture(input: $input) {
      transaction { id kind status authorizationCode createdAt amountSet { shopMoney { amount currencyCode } } }
      userErrors { field message }
    }
  }`;
  const data = await shopifyGraphqlRequestAuto(mutation, {
    input: { id: orderId, parentTransactionId, amount: captureAmount.toFixed(2) }
  }, { operation: `Capture payment for Shopify order ${order.orderNumber || orderId}` });
  const errors = data?.orderCapture?.userErrors || [];
  if (errors.length) throw new Error(errors.map((entry) => entry.message || "Shopify could not capture the payment.").join("; "));
  return data?.orderCapture?.transaction || {};
}

async function syncShopifyOrderAddress(order = {}) {
  const orderId = String(order.shopifyOrderId || "").trim();
  if (!orderId.startsWith("gid://shopify/Order/")) throw new Error("This order is not linked to a Shopify order.");
  const address = order.address || {};
  const contactParts = String(address.name || order.buyer || "").trim().split(/\s+/).filter(Boolean);
  const shippingAddress = {
    firstName: String(address.firstName || contactParts[0] || "").trim() || undefined,
    lastName: String(address.lastName || contactParts.slice(1).join(" ") || "").trim() || undefined,
    company: String(address.company || "").trim() || undefined,
    address1: String(address.line1 || "").trim() || undefined,
    address2: String(address.line2 || "").trim() || undefined,
    city: String(address.city || "").trim() || undefined,
    province: String(address.state || "").trim() || undefined,
    zip: String(address.postalCode || "").trim() || undefined,
    country: String(address.country || "").trim() || undefined,
    phone: String(address.phone || order.phone || "").trim() || undefined
  };
  const mutation = `mutation DataPlusOrderUpdate($input: OrderInput!) { orderUpdate(input: $input) { order { id email shippingAddress { address1 city province zip country } } userErrors { field message } } }`;
  const data = await shopifyGraphqlRequestAuto(mutation, { input: { id: orderId, email: String(order.buyerEmail || "").trim() || undefined, shippingAddress } }, { operation: `Update Shopify order address ${order.orderNumber || orderId}` });
  const errors = data?.orderUpdate?.userErrors || [];
  if (errors.length) throw new Error(errors.map((entry) => entry.message || "Shopify could not update the order address.").join("; "));
  return data?.orderUpdate?.order || {};
}

function clearOrderApiCache(orderId = "") {
  redisCache.deleteByPrefix("dataplus:orders:").catch(() => {});
  // Detail cache keys are versioned. Clear the detail namespace on writes so every
  // order action immediately returns the saved record rather than a stale snapshot.
  if (orderId) redisCache.deleteByPrefix("dataplus:order-detail:").catch(() => {});
}

function orderAddressLabel(address = {}) {
  return [address.name, address.company, address.line1, address.line2, [address.city, address.state, address.postalCode].filter(Boolean).join(", "), address.country]
    .filter(Boolean)
    .join(" | ");
}

function orderSkuBaseFromUomVariant(sku = "") {
  const value = String(sku || "").trim();
  // These are DataPlus-generated sell-unit suffixes. Restricting the fallback to
  // explicit UOM shapes avoids incorrectly collapsing ordinary hyphenated SKUs.
  return value.replace(/-(?:\d+(?:PC|PK|PACK|CT|CS|CASE|BX|EA)|EA|EACH)$/i, "");
}

function orderLineSkuLookupKeys(lines = []) {
  const keys = [];
  for (const line of Array.isArray(lines) ? lines : []) {
    for (const value of [line.sku, line.mappedSku, line.originalSku, line.channelSku, line.channelVariantSku, line.channelVariantId]) {
      const sku = String(value || "").trim();
      if (!sku) continue;
      keys.push(sku);
      const baseSku = orderSkuBaseFromUomVariant(sku);
      if (baseSku && baseSku.toLowerCase() !== sku.toLowerCase()) keys.push(baseSku);
    }
  }
  return [...new Set(keys.map((value) => value.toLowerCase()))];
}

async function enrichOrderDetail(order = {}) {
  const lines = Array.isArray(order.items) ? order.items : [];
  const keys = orderLineSkuLookupKeys(lines);
  const routePurchaseOrderIds = (order.fulfillmentRoutes || []).map((route) => String(route?.purchaseOrderId || "")).filter(Boolean);
  const purchaseOrderIds = [...new Set([...(order.purchaseOrderIds || []).map((id) => String(id || "")).filter(Boolean), ...routePurchaseOrderIds])];
  const [products, linkedPurchaseOrders] = await Promise.all([
    postgres.isPostgresEnabled() ? postgres.readProductsForOrderSkus(keys) : [],
    postgres.isPostgresEnabled() ? Promise.all(purchaseOrderIds.map((id) => postgres.readPurchaseOrderByKey(id))) : []
  ]);
  const localByKey = new Map();
  for (const product of products) {
    for (const key of [
      product.sku,
      product.id,
      product.vendorSku,
      ...(product.systemVariants || []).map((variant) => variant.sku),
      ...(product.aliases || []).filter((alias) => alias.active !== false).map((alias) => alias.aliasSku),
      ...(product.shopifyVariantSkus || []),
      ...(product.shopifyVariantIds || [])
    ]) {
      if (key) localByKey.set(String(key).toLowerCase(), product);
    }
  }
  let itemRevenue = 0;
  let estimatedCogs = 0;
  const enrichedLines = lines.map((line) => {
    const lineKeys = [line.sku, line.mappedSku, line.originalSku, line.channelSku, line.channelVariantSku, line.channelVariantId].filter(Boolean).map((value) => String(value).toLowerCase());
    const fallbackKeys = lineKeys.map((key) => orderSkuBaseFromUomVariant(key).toLowerCase()).filter((key, index, all) => key && key !== lineKeys[index] && !all.slice(0, index).includes(key));
    const directProduct = lineKeys.map((key) => localByKey.get(key)).find(Boolean) || null;
    const product = directProduct || fallbackKeys.map((key) => localByKey.get(key)).find(Boolean) || null;
    const matchedVariant = product?.systemVariants?.find((variant) => lineKeys.includes(String(variant.sku || "").toLowerCase())) || null;
    // A base SKU is sold as one each. Only an explicitly matched UOM variant
    // (for example BUS101275TRV-6PC) may apply its pack multiplier.
    const sellUnitQty = Number(matchedVariant?.uomQty || 1) || 1;
    const sourceUnitCost = matchedVariant?.unitCost ?? (product ? productEachUnitCost(product) : line.cost);
    const unitCost = Number(sourceUnitCost || 0);
    const quantity = Number(line.qty || 0);
    const revenue = Number(line.price || 0) * quantity;
    const cogs = unitCost * quantity;
    itemRevenue += revenue;
    estimatedCogs += cogs;
    return {
      ...line,
      skuMatchMode: matchedVariant ? "channel-variant" : directProduct ? "direct" : product ? "uom-parent" : "unmatched",
      localSku: product?.sku || "",
      parentSku: product?.sku || line.mappedSku || "",
      localProduct: product ? {
        sku: product.sku,
        title: product.marketplaceTitle || product.title || "",
        defaultImage: productImageUrl(product),
        supplier: product.supplier || "",
        uom: product.uom || "EA",
        uomQty: Number(product.uomQty || 1),
        qty: Number(product.qty || 0),
        reserved: Number(product.reserved || 0),
        available: Math.max(0, Number(product.qty || 0) - Number(product.reserved || 0)),
        itemLength: productShippingDimensionValue(product, "itemLength", "item_length"),
        itemWidth: productShippingDimensionValue(product, "itemWidth", "item_width"),
        itemHeight: productShippingDimensionValue(product, "itemHeight", "item_height"),
        itemWeight: productShippingDimensionValue(product, "itemWeight", "item_weight"),
        packageLength: productShippingDimensionValue(product, "packageLength", "package_length"),
        packageWidth: productShippingDimensionValue(product, "packageWidth", "package_width"),
        packageHeight: productShippingDimensionValue(product, "packageHeight", "package_height"),
        packageWeight: productShippingDimensionValue(product, "packageWeight", "package_weight"),
        shippingClass: productShippingClassification(product).shippingClass || ""
      } : null,
      variant: matchedVariant ? { sku: matchedVariant.sku, parentSku: matchedVariant.parentSku || product?.sku || "", label: matchedVariant.optionValue || matchedVariant.uomName || "", uomQty: Number(matchedVariant.uomQty || 1) } : null,
      sellUnitQty,
      unitCost,
      revenue,
      estimatedCogs: cogs,
      grossProfit: revenue - cogs,
      grossMarginPercent: revenue > 0 ? ((revenue - cogs) / revenue) * 100 : 0
    };
  });
  const marketplaceFees = Number(order.marketplaceFees || 0);
  const refunds = Number(order.refundAmount || 0);
  const total = Number(order.total || 0);
  return {
    ...order,
    timeline: normalizeOrderTimeline(order),
    items: enrichedLines,
    linkedPurchaseOrders: (linkedPurchaseOrders || []).filter(Boolean).map((po) => ({
      id: po.id,
      poNumber: po.poNumber,
      supplier: po.supplier,
      status: po.status,
      createdAt: po.createdAt,
      placedAt: po.placedAt || po.submittedAt || po.sentAt || "",
      expectedAt: po.expectedAt || "",
      warehouseName: po.warehouseName || "",
      totalUnits: Number(po.totalUnits || 0),
      estimatedCost: Number(po.estimatedCost || 0),
      receivedUnits: (po.items || []).reduce((sum, line) => sum + Number(line.receivedQty || 0), 0),
      lineCount: Array.isArray(po.items) ? po.items.length : 0
    })),
    shippingAddressLabel: orderAddressLabel(order.address || {}),
    billingAddressLabel: orderAddressLabel(order.billingAddress || {}),
    profitLoss: {
      orderTotal: total,
      itemRevenue,
      shippingCollected: Number(order.shippingCost || 0),
      estimatedCogs,
      marketplaceFees,
      refunds,
      grossProfit: total - estimatedCogs - marketplaceFees - refunds,
      grossMarginPercent: total > 0 ? ((total - estimatedCogs - marketplaceFees - refunds) / total) * 100 : 0
    }
  };
}

async function hydrateOrderLocalCosts(order = {}) {
  const enriched = await enrichOrderDetail(order);
  order.items = (order.items || []).map((line, index) => {
    const enrichedLine = enriched.items?.[index] || {};
    const unitCost = Number(enrichedLine.unitCost || line.unitCost || line.cost || 0);
    return { ...line, localSku: enrichedLine.localSku || line.localSku || "", unitCost, cost: unitCost };
  });
  return order;
}

function shopifyRestRequestWithToken(method, resourcePath, body = null, accessToken = "", options = {}) {
  const config = shopifyAdminConfig();
  if (!config.shop || !accessToken) {
    throw new Error("Shopify Admin API is not configured. Add SHOPIFY_STORE_DOMAIN and Shopify credentials to .env.");
  }
  const startedAt = Date.now();
  const requestPath = `/admin/api/${encodeURIComponent(config.apiVersion)}${resourcePath}`;
  const payload = body ? JSON.stringify(body) : "";
  const requestOptions = {
    hostname: config.shop,
    path: requestPath,
    method,
    headers: {
      "Accept": "application/json",
      "X-Shopify-Access-Token": accessToken,
      ...(payload ? {
        "Content-Type": "application/json",
        "Content-Length": Buffer.byteLength(payload)
      } : {})
    }
  };
  return new Promise((resolve, reject) => {
    const req = https.request(requestOptions, (response) => {
      const chunks = [];
      response.on("data", (chunk) => chunks.push(chunk));
      response.on("end", () => {
        const text = Buffer.concat(chunks).toString("utf8");
        let data = {};
        try {
          data = text ? JSON.parse(text) : {};
        } catch {
          appendChannelApiLog({ channel: "Shopify", transport: "REST", method, path: requestPath, operation: options.operation || resourcePath, statusCode: response.statusCode, ok: false, durationMs: Date.now() - startedAt, message: `Non-JSON response (${response.statusCode})`, requestId: response.headers["x-request-id"] || "", jobId: options.jobId || "" });
          return reject(new Error(`Shopify returned a non-JSON response (${response.statusCode}).`));
        }
        if (response.statusCode < 200 || response.statusCode >= 300) {
          appendChannelApiLog({ channel: "Shopify", transport: "REST", method, path: requestPath, operation: options.operation || resourcePath, statusCode: response.statusCode, ok: false, durationMs: Date.now() - startedAt, message: text, requestId: response.headers["x-request-id"] || "", jobId: options.jobId || "" });
          const error = new Error(`Shopify API error (${response.statusCode}): ${text}`);
          error.statusCode = response.statusCode;
          error.retryAfter = Number(response.headers["retry-after"] || 0) || 0;
          error.shopifyApiCallLimit = String(response.headers["x-shopify-shop-api-call-limit"] || "");
          error.responseText = text;
          return reject(error);
        }
        appendChannelApiLog({ channel: "Shopify", transport: "REST", method, path: requestPath, operation: options.operation || resourcePath, statusCode: response.statusCode, ok: true, durationMs: Date.now() - startedAt, message: "OK", requestId: response.headers["x-request-id"] || "", jobId: options.jobId || "" });
        resolve(data);
      });
    });
    req.on("error", (error) => {
      appendChannelApiLog({ channel: "Shopify", transport: "REST", method, path: requestPath, operation: options.operation || resourcePath, ok: false, durationMs: Date.now() - startedAt, message: error.message, jobId: options.jobId || "" });
      reject(error);
    });
    if (payload) req.write(payload);
    req.end();
  });
}

async function syncShopifyCloseoutCollection() {
  const existing = await shopifyRestRequestAuto("GET", "/smart_collections.json?handle=closeouts&limit=1");
  const current = Array.isArray(existing.smart_collections) ? existing.smart_collections[0] : null;
  const smartCollection = {
    title: "Closeouts",
    handle: "closeouts",
    body_html: "",
    published: true,
    published_scope: "global",
    sort_order: "best-selling",
    rules: [{ column: "tag", relation: "equals", condition: "closeout" }],
    disjunctive: false,
    metafields_global_title_tag: "Closeouts on Sale",
    metafields_global_description_tag: "Closeout deals on discontinued products while supplies last."
  };
  if (current?.id) {
    const updated = await shopifyRestRequestAuto("PUT", `/smart_collections/${encodeURIComponent(current.id)}.json`, { smart_collection: { id: current.id, ...smartCollection } });
    return { action: "updated", collection: updated.smart_collection || current };
  }
  const created = await shopifyRestRequestAuto("POST", "/smart_collections.json", { smart_collection: smartCollection });
  return { action: "created", collection: created.smart_collection };
}

function shopifySmartCollectionPayloadForType(productType = "") {
  const type = sourceTextValue(productType);
  const title = smartCollectionTitle(type);
  return {
    title,
    handle: smartCollectionHandle(type),
    body_html: "",
    published: true,
    published_scope: "global",
    sort_order: "best-selling",
    rules: [{ column: "type", relation: "equals", condition: type }],
    disjunctive: false,
    metafields_global_title_tag: smartCollectionSeoTitle(title),
    metafields_global_description_tag: smartCollectionSeoDescription(title, type)
  };
}

async function upsertShopifySmartCollectionForType(productType = "", options = {}) {
  const smartCollection = shopifySmartCollectionPayloadForType(productType);
  if (!smartCollection.handle || !sourceTextValue(productType)) return { action: "skipped", reason: "Missing product type" };
  const existing = await shopifyRestRequestAuto("GET", `/smart_collections.json?handle=${encodeURIComponent(smartCollection.handle)}&limit=1`, null, {
    ...options,
    jobId: options.jobId || "",
    operation: "Find Shopify type collection"
  });
  const current = Array.isArray(existing.smart_collections) ? existing.smart_collections[0] : null;
  if (current?.id) {
    const updated = await shopifyRestRequestAuto("PUT", `/smart_collections/${encodeURIComponent(current.id)}.json`, {
      smart_collection: { id: current.id, ...smartCollection }
    }, {
      ...options,
      jobId: options.jobId || "",
      operation: "Update Shopify type collection"
    });
    return { action: "updated", collection: updated.smart_collection || current, handle: smartCollection.handle, productType };
  }
  const created = await shopifyRestRequestAuto("POST", "/smart_collections.json", {
    smart_collection: smartCollection
  }, {
    ...options,
    jobId: options.jobId || "",
    operation: "Create Shopify type collection"
  });
  return { action: "created", collection: created.smart_collection, handle: smartCollection.handle, productType };
}

function normalizeShopifyProductGid(value = "") {
  const text = String(value || "").trim();
  if (!text) return "";
  if (/^gid:\/\/shopify\/Product\/\d+$/i.test(text)) return text;
  const id = text.match(/Product\/(\d+)/i)?.[1] || text.match(/^\d+$/)?.[0] || "";
  return id ? `gid://shopify/Product/${id}` : text;
}

function normalizeShopifyLocationGid(value = "") {
  const text = String(value || "").trim();
  if (!text) return "";
  if (/^gid:\/\/shopify\/Location\/\d+$/i.test(text)) return text;
  const id = text.match(/Locations?\/(\d+)/i)?.[1] || text.match(/^\d+$/)?.[0] || "";
  return id ? `gid://shopify/Location/${id}` : text;
}

function normalizeShopifyVariantGid(value = "") {
  const text = String(value || "").trim();
  if (!text) return "";
  if (/^gid:\/\/shopify\/ProductVariant\/\d+$/i.test(text)) return text;
  const id = text.match(/ProductVariant\/(\d+)/i)?.[1] || text.match(/^\d+$/)?.[0] || "";
  return id ? `gid://shopify/ProductVariant/${id}` : text;
}

function shopifyLegacyId(value = "") {
  return String(value || "").trim().match(/(\d+)$/)?.[1] || "";
}

async function fetchShopifyProductStatusByGid(productGid = "", options = {}) {
  const gid = normalizeShopifyProductGid(productGid);
  if (!gid) throw new Error("Missing Shopify Product GID.");
  const query = `
    query DataPlusProductStatus($id: ID!) {
      node(id: $id) {
        ... on Product {
          id
          legacyResourceId
          title
          handle
          status
          publishedAt
          updatedAt
          onlineStoreUrl
          variants(first: 100) {
            nodes {
              id
              legacyResourceId
              sku
              inventoryQuantity
            }
          }
        }
      }
    }
  `;
  const data = await shopifyGraphqlRequestAuto(query, { id: gid }, { jobId: options.jobId, operation: options.operation || "Fetch Shopify product status" });
  const product = data?.node;
  if (!product?.id) throw new Error(`Shopify product was not found for ${gid}.`);
  return product;
}

function shopifyStatusPayloadFromProduct(product = {}, item = {}) {
  const variants = Array.isArray(product.variants?.nodes) ? product.variants.nodes : [];
  const expectedSkus = new Set(shopifyPurchaseVariants(item).map((variant) => String(variant.sku || "").trim().toLowerCase()).filter(Boolean));
  const currentVariantId = normalizeShopifyVariantGid(item.shopifyVariantId);
  const matchedVariant = variants.find((variant) => currentVariantId && normalizeShopifyVariantGid(variant.id) === currentVariantId)
    || variants.find((variant) => expectedSkus.has(String(variant.sku || "").trim().toLowerCase()))
    || variants[0]
    || null;
  const status = normalizeShopifyStatus(product.status);
  return {
    shopifyId: normalizeShopifyProductGid(product.id),
    shopifyVariantId: matchedVariant?.id ? normalizeShopifyVariantGid(matchedVariant.id) : "",
    shopifyHandle: product.handle || "",
    shopifyStatus: status,
    shopifyPublished: Boolean(product.publishedAt),
    shopifyPublishedAt: product.publishedAt || "",
    shopifyUpdatedAt: product.updatedAt || "",
    shopifySyncedAt: new Date().toISOString(),
    shopifySyncSource: "graphql",
    shopifyOnlineStoreUrl: product.onlineStoreUrl || "",
    shopifyVariantSku: matchedVariant?.sku || "",
    shopifyLiveInventoryQuantity: Number.isFinite(Number(matchedVariant?.inventoryQuantity)) ? Number(matchedVariant.inventoryQuantity) : null,
    shopifyVariantInventoryQuantity: Number.isFinite(Number(matchedVariant?.inventoryQuantity)) ? Number(matchedVariant.inventoryQuantity) : null,
    shopifyVariantCount: variants.length
  };
}

function shopifyStatusMapPatchFromProduct(product = {}, item = {}, payload = {}) {
  const variants = Array.isArray(product.variants?.nodes) ? product.variants.nodes : [];
  const patch = {};
  for (const variant of variants) {
    const sku = String(variant?.sku || "").trim();
    if (!sku) continue;
    const inventoryQuantity = Number.isFinite(Number(variant.inventoryQuantity)) ? Number(variant.inventoryQuantity) : null;
    patch[sku.toLowerCase()] = {
      ...payload,
      sku,
      shopifyVariantId: variant?.id ? normalizeShopifyVariantGid(variant.id) : "",
      shopifyVariantSku: sku,
      shopifyLiveInventoryQuantity: inventoryQuantity,
      shopifyVariantInventoryQuantity: inventoryQuantity
    };
  }
  const itemSku = String(item?.sku || "").trim();
  if (itemSku && !patch[itemSku.toLowerCase()]) patch[itemSku.toLowerCase()] = { ...payload, sku: itemSku };
  return patch;
}

function shopifyStatusPayloadFromVariantNode(variant = {}) {
  const product = variant.product || {};
  const status = normalizeShopifyStatus(product.status);
  return {
    sku: String(variant.sku || "").trim(),
    shopifyId: normalizeShopifyProductGid(product.id),
    shopifyVariantId: normalizeShopifyVariantGid(variant.id),
    shopifyHandle: product.handle || "",
    shopifyStatus: status,
    shopifyPublished: Boolean(product.publishedAt),
    shopifyPublishedAt: product.publishedAt || "",
    shopifyUpdatedAt: product.updatedAt || "",
    shopifySyncedAt: new Date().toISOString(),
    shopifySyncSource: "shopify-api-sku-map",
    shopifyOnlineStoreUrl: product.onlineStoreUrl || "",
    shopifyTitle: product.title || "",
    shopifyVariantSku: String(variant.sku || "").trim(),
    shopifyVariantTitle: variant.title || "",
    shopifyVariantPrice: variant.price || "",
    shopifyVariantCompareAtPrice: variant.compareAtPrice || "",
    shopifyVariantBarcode: variant.barcode || "",
    shopifyVariantInventoryQuantity: Number.isFinite(Number(variant.inventoryQuantity)) ? Number(variant.inventoryQuantity) : null
  };
}

async function fetchShopifyVariantSkuPage(after = null, options = {}) {
  const query = `
    query DataPlusShopifyVariantSkuMap($first: Int!, $after: String) {
      productVariants(first: $first, after: $after) {
        nodes {
          id
          legacyResourceId
          title
          sku
          barcode
          price
          compareAtPrice
          inventoryQuantity
          product {
            id
            legacyResourceId
            title
            handle
            status
            publishedAt
            updatedAt
            onlineStoreUrl
          }
        }
        pageInfo {
          hasNextPage
          endCursor
        }
      }
    }
  `;
  const first = Math.max(1, Math.min(250, Number(options.first || 250)));
  const data = await shopifyGraphqlRequestAuto(query, { first, after }, { jobId: options.jobId, operation: "Build Shopify SKU map" });
  const connection = data?.productVariants || {};
  return {
    variants: Array.isArray(connection.nodes) ? connection.nodes : [],
    hasNextPage: Boolean(connection.pageInfo?.hasNextPage),
    endCursor: connection.pageInfo?.endCursor || ""
  };
}

async function syncInventoryItemShopifyStatus(item = {}, gidOverride = "", options = {}) {
  const gid = normalizeShopifyProductGid(gidOverride || item.shopifyId);
  if (!gid) throw new Error(`Product ${item.sku || item.id || ""} does not have a Shopify Product GID yet.`);
  const product = await fetchShopifyProductStatusByGid(gid, { jobId: options.jobId, operation: "Sync Shopify product status" });
  const payload = shopifyStatusPayloadFromProduct(product, item);
  const fields = ["shopifyId", "shopifyVariantId", "shopifyHandle", "shopifyStatus", "shopifyPublished", "shopifyPublishedAt", "shopifyUpdatedAt", "shopifySyncedAt", "shopifySyncSource", "shopifyOnlineStoreUrl", "shopifyVariantSku", "shopifyLiveInventoryQuantity", "shopifyVariantCount"];
  const changed = [];
  for (const field of fields) {
    if (payload[field] !== undefined && payload[field] !== "" && item[field] !== payload[field]) {
      item[field] = payload[field];
      changed.push(field);
    }
  }
  if (changed.length) item.updatedAt = new Date().toISOString();
  return { item, product, payload, changed };
}

function readCloseoutSkus() {
  if (!fs.existsSync(CATALOG_CLOSEOUT_FILE)) return [];
  try {
    return parseCsv(fs.readFileSync(CATALOG_CLOSEOUT_FILE, "utf8"))
      .map((row) => String(row.sku || row.SKU || "").trim())
      .filter(Boolean);
  } catch {
    return [];
  }
}

async function findCatalogProductBySku(sku, db = {}) {
  const key = String(sku || "").trim().toLowerCase();
  if (!key) return null;
  const overrides = sourceCatalogOverrideMap(db);
  const vendorMappings = vendorCategoryMappingMap(db);
  const productsBySku = inventoryBySkuMap(db);
  if (postgres.isPostgresEnabled()) {
    try {
      const rows = await postgres.readVendorCatalogItemsBySkus([key]);
      const normalized = normalizeCatalogProductForInventory(rows?.[0] || null);
      if (normalized) return decorateSourceCatalogProduct(normalized, overrides, productsBySku, vendorMappings);
      return null;
    } catch (error) {
      console.warn("Postgres source catalog SKU lookup failed, falling back to catalog file:", error.message);
    }
  }
  if (!fs.existsSync(CATALOG_FILE)) return null;
  const indexedProduct = await readCatalogProductFromSkuIndex(key);
  if (indexedProduct) return decorateSourceCatalogProduct(indexedProduct, overrides, productsBySku, vendorMappings);
  const rl = readline.createInterface({
    input: fs.createReadStream(CATALOG_FILE, { encoding: "utf8" }),
    crlfDelay: Infinity
  });
  for await (const line of rl) {
    if (!line.trim()) continue;
    let product;
    try {
      product = JSON.parse(line);
    } catch {
      continue;
    }
    if (String(product.sku || "").toLowerCase() === key) {
      rl.close();
      return decorateSourceCatalogProduct(product, overrides, productsBySku, vendorMappings);
    }
  }
  return null;
}

async function queueShopifyProductCreateJob(payload = {}) {
  const requestedSkus = [...new Set((Array.isArray(payload.skus) ? payload.skus : [])
    .map((sku) => String(sku || "").trim())
    .filter(Boolean))];
  const dryRun = payload.apply === true ? false : payload.dryRun !== false;
  const query = String(payload.query || "");
  const db = await readDbFast({ skipInventory: true });
  requireEnabledChannel(db, "Shopify");
  const launchBatchLimit = shopifyProductLaunchBatchLimit(readSystemSettingsStore(db?.systemSettings || {}));
  const limit = Math.max(1, Math.min(launchBatchLimit, Number(payload.limit || launchBatchLimit) || launchBatchLimit));
  const limitedSkus = requestedSkus.slice(0, limit);
  const allowDraftIncomplete = payload.allowDraftIncomplete === true;
  const filters = payload.filters && Object.keys(payload.filters || {}).length
    ? payload.filters
    : (allowDraftIncomplete ? { channelStatus: "shopify-missing" } : { channelStatusAll: "shopify-missing|shopify-ready" });
  const productTotal = limitedSkus.length || limit;
  const job = createImportJob(db, {
    section: "Products",
    operation: dryRun ? "Shopify product create dry run" : "Shopify product create",
    direction: "sync",
    status: "queued",
    fileName: dryRun ? "shopify-product-create-dry-run.json" : "shopify-product-create-report.json",
    totalRows: productTotal,
    processedRows: 0,
    progressPercent: 0,
    phase: "queued",
    workerTask: shouldRunJobsInline() ? "" : "shopify-product-create",
    workerPayload: shouldRunJobsInline() ? {} : {
      skus: limitedSkus,
      query,
      filters,
      limit,
      dryRun,
      apply: !dryRun,
      allowDraftIncomplete
    },
    message: dryRun
      ? `Shopify product create dry run queued for up to ${Number(productTotal || 0).toLocaleString()} product${Number(productTotal || 0) === 1 ? "" : "s"}.`
      : `Shopify product create queued for up to ${Number(productTotal || 0).toLocaleString()} product${Number(productTotal || 0) === 1 ? "" : "s"}.`
  });
  upsertImportJobStore(job);
  if (shouldRunJobsInline()) {
    setTimeout(() => runShopifyProductCreateWorkerJob(job, {
      skus: limitedSkus,
      query,
      filters,
      limit,
      dryRun,
      apply: !dryRun,
      allowDraftIncomplete
    }).catch((error) => {
      finishImportJob(job, {
        status: "failed",
        message: error.message || "Shopify product create failed.",
        errors: [error.message || "Shopify product create failed."],
        missingCount: 1,
        phase: "failed",
        estimatedSecondsRemaining: 0
      });
      upsertImportJobStore(job);
    }), 250);
  } else {
    await postgres.upsertOperationJob(normalizeImportJob(job));
  }
  return { job: normalizeImportJob(job), state: await postgresLiteState({ importJobs: [job] }) };
}

